                                                                                                                                                                                                    local function Notify(title, content, duration, imageId)
                                                                                                                                                                                                        Library:Notify({
                                                                                                                                                                                                            Title = title or "true am am",
                                                                                                                                                                                                            Content = content or "",
                                                                                                                                                                                                            Duration = duration or 5,
                                                                                                                                                                                                            ImageID = imageId
                                                                                                                                                                                                        })
                                                                                                                                                                                                    end
                                                                                                                                                                                                    _G.TrueAmAm_Notify = Notify

                                                                                                                                                                                                    local function sno(part)
                                                                                                                                                                                                        if part and _G.SetNetOwner_Def then
                                                                                                                                                                                                            pcall(function() _G.SetNetOwner_Def:FireServer(part, part.CFrame) end)
                                                                                                                                                                                                        end
                                                                                                                                                                                                    end
                                                                                                                                                                                                    _G.TrueAmAm_sno = sno

                                                                                                                                                                                                    local function unsno(part)
                                                                                                                                                                                                        if part and _G.DestroyGrabLine_Def then
                                                                                                                                                                                                            pcall(function() _G.DestroyGrabLine_Def:FireServer(part) end)
                                                                                                                                                                                                        end
                                                                                                                                                                                                    end
                                                                                                                                                                                                    _G.TrueAmAm_unsno = unsno

                                                                                                                                                                                                    local function GetTargetPlayer()
                                                                                                                                                                                                        local arr = _G.TrueAmAm_SelectedTargets
                                                                                                                                                                                                        if arr and #arr > 0 then return P:FindFirstChild(arr[1]) end
                                                                                                                                                                                                        return nil
                                                                                                                                                                                                    end
                                                                                                                                                                                                    _G.TrueAmAm_GetTargetPlayer = GetTargetPlayer

                                                                                                                                                                                                    local function GetBlobTargetPlayer()
                                                                                                                                                                                                        local arr = _G.TrueAmAm_SelectedBlobTargets
                                                                                                                                                                                                        if arr and #arr > 0 then return P:FindFirstChild(arr[1]) end
                                                                                                                                                                                                        return nil
                                                                                                                                                                                                    end
                                                                                                                                                                                                    _G.TrueAmAm_GetBlobTargetPlayer = GetBlobTargetPlayer

                                                                                                                                                                                                    local function IsFriend(player)
                                                                                                                                                                                                        if not player or not player.UserId then return false end
                                                                                                                                                                                                        local success, result = pcall(function() return LP:IsFriendsWith(player.UserId) end)
                                                                                                                                                                                                        return success and result or false
                                                                                                                                                                                                    end
                                                                                                                                                                                                    _G.TrueAmAm_IsFriend = IsFriend

                                                                                                                                                                                                    local function FindPCLD()
                                                                                                                                                                                                        local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                        if not hrp then return nil end
                                                                                                                                                                                                        for _, v in pairs(workspace:GetChildren()) do
                                                                                                                                                                                                            if v.Name == "PlayerCharacterLocationDetector" and (v.Position - hrp.Position).Magnitude <= 2 then
                                                                                                                                                                                                                return v
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end
                                                                                                                                                                                                        return nil
                                                                                                                                                                                                    end
                                                                                                                                                                                                    _G.TrueAmAm_FindPCLD = FindPCLD

                                                                                                                                                                                                    local function FindBlob()
                                                                                                                                                                                                        local char = LP.Character
                                                                                                                                                                                                        local hum = char and char:FindFirstChild("Humanoid")
                                                                                                                                                                                                        if not hum then return nil end
                                                                                                                                                                                                        local seat = hum.SeatPart
                                                                                                                                                                                                        if not seat then return nil end
                                                                                                                                                                                                        local blob = seat.Parent
                                                                                                                                                                                                        if not blob or blob.Name ~= "CreatureBlobman" then return nil end
                                                                                                                                                                                                        return blob
                                                                                                                                                                                                    end
                                                                                                                                                                                                    _G.TrueAmAm_FindBlob = FindBlob

