                                                                                                                                                                                                        local MainR = Tabs.Main:CreateBlock({Name = "Utilities", Side = "Right"})

                                                                                                                                                                                                        MainL:CreateLabel({Text = "Player: " .. LP.DisplayName})
                                                                                                                                                                                                        MainL:CreateLabel({Text = "Username: @" .. LP.Name})
                                                                                                                                                                                                        MainL:CreateLabel({Text = "Account: " .. LP.AccountAge .. " days"})
                                                                                                                                                                                                        MainL:CreateLabel({Text = "PlaceId: " .. game.PlaceId})
                                                                                                                                                                                                        MainL:CreateLabel({Text = "Game: FTAP"})

                                                                                                                                                                                                        local StartTime = tick()
                                                                                                                                                                                                        local SessionLabel = MainL:CreateLabel({Text = "Session: 00:00"})

                                                                                                                                                                                                        task.spawn(function()
                                                                                                                                                                                                            while task.wait(1) do
                                                                                                                                                                                                                local elapsed = math.floor(tick() - StartTime)
                                                                                                                                                                                                                local hrs  = math.floor(elapsed / 3600)
                                                                                                                                                                                                                local mins = math.floor((elapsed % 3600) / 60)
                                                                                                                                                                                                                local secs = elapsed % 60
                                                                                                                                                                                                                local timeStr
                                                                                                                                                                                                                if hrs > 0 then timeStr = string.format("%02d:%02d:%02d", hrs, mins, secs)
                                                                                                                                                                                                                else timeStr = string.format("%02d:%02d", mins, secs) end
                                                                                                                                                                                                                pcall(function() SessionLabel:Set("Session: " .. timeStr) end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end)

