                                                                                                                                                                                                        local CosmeticsL = Tabs.Player:CreateBlock({Name = "Cosmetics", Side = "Left"})
                                                                                                                                                                                                        local SoundsR = Tabs.Player:CreateBlock({Name = "Sounds", Side = "Right"})

                                                                                                                                                                                                        -- FOV
