                                                                                                                                                                                                        })

                                                                                                                                                                                                        R.RenderStepped:Connect(function()
                                                                                                                                                                                                            if FOVEnabled and Cam.FieldOfView ~= FOVValue then Cam.FieldOfView = FOVValue end
                                                                                                                                                                                                        end)

                                                                                                                                                                                                        -- Third Person
