                                                                                                                                                                                                                if v then
                                                                                                                                                                                                                    SavedCamMode = LP.CameraMode
                                                                                                                                                                                                                    SavedCamMax = LP.CameraMaxZoomDistance
                                                                                                                                                                                                                    SavedCamMin = LP.CameraMinZoomDistance
                                                                                                                                                                                                                    LP.CameraMode = Enum.CameraMode.Classic
                                                                                                                                                                                                                    LP.CameraMaxZoomDistance = 128
                                                                                                                                                                                                                    LP.CameraMinZoomDistance = 0.5
                                                                                                                                                                                                                else
                                                                                                                                                                                                                    if SavedCamMode then
                                                                                                                                                                                                                        LP.CameraMode = SavedCamMode
                                                                                                                                                                                                                        LP.CameraMaxZoomDistance = SavedCamMax
                                                                                                                                                                                                                        LP.CameraMinZoomDistance = SavedCamMin
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- Infinite Jump
                                                                                                                                                                                                        local infJumpOn = false
                                                                                                                                                                                                        PlayerL:CreateToggle({
                                                                                                                                                                                                            Name = "Infinite Jump",
                                                                                                                                                                                                            Flag = "InfJump",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(v) infJumpOn = v end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        U.JumpRequest:Connect(function()
                                                                                                                                                                                                            if not infJumpOn then return end
                                                                                                                                                                                                            local char = LP.Character
                                                                                                                                                                                                            if not char then return end
                                                                                                                                                                                                            local hum = char:FindFirstChildOfClass("Humanoid")
                                                                                                                                                                                                            if hum then hum:ChangeState(Enum.HumanoidStateType.Jumping) end
                                                                                                                                                                                                        end)

                                                                                                                                                                                                        -- WalkSpeed
                                                                                                                                                                                                        local speedEnabled = false
                                                                                                                                                                                                        local speedValue = 16
                                                                                                                                                                                                        local speedConn = nil

                                                                                                                                                                                                        local function ApplySpeed()
                                                                                                                                                                                                            local char = LP.Character
                                                                                                                                                                                                            local hum = char and char:FindFirstChildOfClass("Humanoid")
                                                                                                                                                                                                            if not hum then return end
                                                                                                                                                                                                            if speedConn then speedConn:Disconnect() speedConn = nil end
                                                                                                                                                                                                            if speedEnabled then
                                                                                                                                                                                                                hum.WalkSpeed = speedValue
                                                                                                                                                                                                                speedConn = hum:GetPropertyChangedSignal("WalkSpeed"):Connect(function()
                                                                                                                                                                                                                    if speedEnabled and hum.WalkSpeed ~= speedValue then
                                                                                                                                                                                                                        hum.WalkSpeed = speedValue
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            else
                                                                                                                                                                                                                hum.WalkSpeed = 16
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end

                                                                                                                                                                                                        PlayerL:CreateToggle({
                                                                                                                                                                                                            Name = "Custom Walkspeed",
                                                                                                                                                                                                            Flag = "WalkspeedToggle",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(v) speedEnabled = v ApplySpeed() task.defer(ApplySpeed) task.delay(0.2, ApplySpeed) end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        PlayerL:CreateSlider({
                                                                                                                                                                                                            Name = "Walkspeed Value",
                                                                                                                                                                                                            Flag = "WalkspeedValue",
                                                                                                                                                                                                            Min = 16, Max = 500, Default = 16,
                                                                                                                                                                                                            Callback = function(v) speedValue = v if speedEnabled then ApplySpeed() end end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- JumpPower
                                                                                                                                                                                                        local jumpEnabled = false
                                                                                                                                                                                                        local jumpValue = 50
                                                                                                                                                                                                        local jumpConn = nil

                                                                                                                                                                                                        local function ApplyJump()
                                                                                                                                                                                                            local char = LP.Character
                                                                                                                                                                                                            local hum = char and char:FindFirstChildOfClass("Humanoid")
                                                                                                                                                                                                            if not hum then return end
                                                                                                                                                                                                            if jumpConn then jumpConn:Disconnect() jumpConn = nil end
                                                                                                                                                                                                            if jumpEnabled then
                                                                                                                                                                                                                hum.UseJumpPower = true
                                                                                                                                                                                                                hum.JumpPower = jumpValue
                                                                                                                                                                                                                jumpConn = hum:GetPropertyChangedSignal("JumpPower"):Connect(function()
                                                                                                                                                                                                                    if jumpEnabled and hum.JumpPower ~= jumpValue then hum.JumpPower = jumpValue end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            else
                                                                                                                                                                                                                hum.UseJumpPower = true
                                                                                                                                                                                                                hum.JumpPower = 50
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end

                                                                                                                                                                                                        PlayerL:CreateToggle({
                                                                                                                                                                                                            Name = "Custom Jump Power",
                                                                                                                                                                                                            Flag = "JumpToggle",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(v) jumpEnabled = v ApplyJump() task.defer(ApplyJump) task.delay(0.2, ApplyJump) end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        PlayerL:CreateSlider({
                                                                                                                                                                                                            Name = "Jump Power Value",
                                                                                                                                                                                                            Flag = "JumpValue",
                                                                                                                                                                                                            Min = 50, Max = 500, Default = 50,
                                                                                                                                                                                                            Callback = function(v) jumpValue = v if jumpEnabled then ApplyJump() end end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        LP.CharacterAdded:Connect(function()
                                                                                                                                                                                                            task.wait(0.1) ApplySpeed() ApplyJump()
                                                                                                                                                                                                        end)

                                                                                                                                                                                                        -- Spin Character
                                                                                                                                                                                                        local spinEnabled = false
                                                                                                                                                                                                        local spinSpeed = 5
                                                                                                                                                                                                        local spinConn = nil

                                                                                                                                                                                                        PlayerL:CreateToggle({
                                                                                                                                                                                                            Name = "Spin Character",
                                                                                                                                                                                                            Flag = "SpinToggle",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(v)
                                                                                                                                                                                                                spinEnabled = v
                                                                                                                                                                                                                if spinConn then spinConn:Disconnect() spinConn = nil end
                                                                                                                                                                                                                if v then
                                                                                                                                                                                                                    spinConn = R.Heartbeat:Connect(function()
                                                                                                                                                                                                                        if not spinEnabled then return end
                                                                                                                                                                                                                        local char = LP.Character
                                                                                                                                                                                                                        local root = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        if root then root.CFrame = root.CFrame * CFrame.Angles(0, math.rad(spinSpeed), 0) end
                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        PlayerL:CreateSlider({
                                                                                                                                                                                                            Name = "Spin Speed",
                                                                                                                                                                                                            Flag = "SpinSpeed",
                                                                                                                                                                                                            Min = 1, Max = 90, Default = 5,
                                                                                                                                                                                                            Callback = function(v) spinSpeed = v end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- Fly
                                                                                                                                                                                                        local flyEnabled = false
                                                                                                                                                                                                        local flySpeed = 120
                                                                                                                                                                                                        local flyVelocity, flyGyro, flyConn

                                                                                                                                                                                                        local function stopFly()
                                                                                                                                                                                                            if flyConn then flyConn:Disconnect() flyConn = nil end
                                                                                                                                                                                                            if flyVelocity then flyVelocity:Destroy() flyVelocity = nil end
                                                                                                                                                                                                            if flyGyro then flyGyro:Destroy() flyGyro = nil end
                                                                                                                                                                                                            local char = LP.Character
                                                                                                                                                                                                            local hum = char and char:FindFirstChildOfClass("Humanoid")
                                                                                                                                                                                                            local root = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            if hum then hum.PlatformStand = false end
                                                                                                                                                                                                            if root then
                                                                                                                                                                                                                root.AssemblyLinearVelocity = Vector3.zero
                                                                                                                                                                                                                root.AssemblyAngularVelocity = Vector3.zero
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function startFly()
                                                                                                                                                                                                            stopFly()
                                                                                                                                                                                                            if not flyEnabled then return end
                                                                                                                                                                                                            flyConn = R.RenderStepped:Connect(function()
                                                                                                                                                                                                                if not flyEnabled then return end
                                                                                                                                                                                                                local char = LP.Character
                                                                                                                                                                                                                local hum = char and char:FindFirstChildOfClass("Humanoid")
                                                                                                                                                                                                                local root = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                if not hum or not root then return end
                                                                                                                                                                                                                local controlPart = (hum.Sit and hum.SeatPart and hum.SeatPart.AssemblyRootPart) or root
                                                                                                                                                                                                                if not flyVelocity or flyVelocity.Parent ~= controlPart then
                                                                                                                                                                                                                    if flyVelocity then flyVelocity:Destroy() end
                                                                                                                                                                                                                    flyVelocity = Instance.new("BodyVelocity")
                                                                                                                                                                                                                    flyVelocity.MaxForce = Vector3.new(1e9, 1e9, 1e9)
                                                                                                                                                                                                                    flyVelocity.Parent = controlPart
                                                                                                                                                                                                                end
                                                                                                                                                                                                                if not flyGyro or flyGyro.Parent ~= controlPart then
                                                                                                                                                                                                                    if flyGyro then flyGyro:Destroy() end
                                                                                                                                                                                                                    flyGyro = Instance.new("BodyGyro")
                                                                                                                                                                                                                    flyGyro.MaxTorque = Vector3.new(1e9, 1e9, 1e9)
                                                                                                                                                                                                                    flyGyro.D = 100
                                                                                                                                                                                                                    flyGyro.Parent = controlPart
                                                                                                                                                                                                                end
                                                                                                                                                                                                                local move = Vector3.zero
                                                                                                                                                                                                                if U:IsKeyDown(Enum.KeyCode.W) then move = move + Vector3.new(0, 0, -1) end
                                                                                                                                                                                                                if U:IsKeyDown(Enum.KeyCode.S) then move = move + Vector3.new(0, 0, 1) end
                                                                                                                                                                                                                if U:IsKeyDown(Enum.KeyCode.A) then move = move + Vector3.new(-1, 0, 0) end
                                                                                                                                                                                                                if U:IsKeyDown(Enum.KeyCode.D) then move = move + Vector3.new(1, 0, 0) end
                                                                                                                                                                                                                if U:IsKeyDown(Enum.KeyCode.Space) then move = move + Vector3.new(0, 1, 0) end
                                                                                                                                                                                                                if U:IsKeyDown(Enum.KeyCode.LeftControl) then move = move + Vector3.new(0, -1, 0) end
                                                                                                                                                                                                                local camCF = Cam.CFrame
                                                                                                                                                                                                                if move.Magnitude > 0 then
                                                                                                                                                                                                                    flyVelocity.Velocity = (camCF.LookVector * -move.Z + camCF.RightVector * move.X + Vector3.new(0, move.Y, 0)) * flySpeed
                                                                                                                                                                                                                else
                                                                                                                                                                                                                    flyVelocity.Velocity = Vector3.zero
                                                                                                                                                                                                                end
                                                                                                                                                                                                                flyGyro.CFrame = CFrame.new(controlPart.Position, controlPart.Position + camCF.LookVector)
                                                                                                                                                                                                                hum.PlatformStand = not hum.Sit
                                                                                                                                                                                                            end)
                                                                                                                                                                                                        end

