                                                                                                                                                                                                                                        local po = prt:FindFirstChild("PartOwner")
                                                                                                                                                                                                                                        if po and po.Value ~= "" then
                                                                                                                                                                                                                                            local holdPart = hkAGModel:FindFirstChild("HoldPart")
                                                                                                                                                                                                                                            local holdRemote = holdPart and holdPart:FindFirstChild("HoldItemRemoteFunction")
                                                                                                                                                                                                                                            if holdRemote then
                                                                                                                                                                                                                                                task.spawn(function()
                                                                                                                                                                                                                                                    pcall(function() holdRemote:InvokeServer(hkAGModel, LP.Character) end)
                                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                                if _G.DestroyToy_Def then _G.DestroyToy_Def:FireServer(hkAGModel) end
                                                                                                                                                                                                                                                local hum = LP.Character:FindFirstChild("Humanoid")
                                                                                                                                                                                                                                                if hum then
                                                                                                                                                                                                                                                    hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
                                                                                                                                                                                                                                                    hum.AutoRotate = true
                                                                                                                                                                                                                                                    if hum.Sit then hum.Sit = false end
                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                po.Value = ""
                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            else
                                                                                                                                                                                                                                local canSpawn = LP:FindFirstChild("CanSpawnToy")
                                                                                                                                                                                                                                if LP.Character and canSpawn and canSpawn.Value and not hkAGSt then
                                                                                                                                                                                                                                    hkAGSt = tick()
                                                                                                                                                                                                                                    task.spawn(function()
                                                                                                                                                                                                                                        if _G.SpawnToy_Def then
                                                                                                                                                                                                                                            pcall(function()
                                                                                                                                                                                                                                                _G.SpawnToy_Def:InvokeServer("InstrumentWoodwindOcarina", CFrame.new(1e5, 1e5, 1e5), Vector3.new(0, 0, 0))
                                                                                                                                                                                                                                            end)
                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                                elseif hkAGSt and tick() - hkAGSt > 1 and myFolder and not myFolder:FindFirstChild("InstrumentWoodwindOcarina") then
                                                                                                                                                                                                                                    hkAGSt = nil
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                local grabbed = false
                                                                                                                                                                                                                                if LP.Character then
                                                                                                                                                                                                                                    for _, prt in pairs(LP.Character:GetChildren()) do
                                                                                                                                                                                                                                        local po = prt:FindFirstChild("PartOwner")
                                                                                                                                                                                                                                        if po and po.Value ~= "" then grabbed = true end
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                if grabbed then
                                                                                                                                                                                                                                    if _G.Struggle_Def then _G.Struggle_Def:FireServer(LP) end
                                                                                                                                                                                                                                    if LP.Character then
                                                                                                                                                                                                                                        local hum = LP.Character:FindFirstChild("Humanoid")
                                                                                                                                                                                                                                        local hrp = LP.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                                        if hum and hrp and _G.RagdollRemote_Def then
                                                                                                                                                                                                                                            _G.RagdollRemote_Def:FireServer(hrp, 0.00000000001)
                                                                                                                                                                                                                                            for _, track in ipairs(hum:GetPlayingAnimationTracks()) do
                                                                                                                                                                                                                                                if track.Animation.AnimationId == "rbxassetid://7047322890" then track:Stop() end
                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                        task.wait()
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- GUCCI ANTI GRAB
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local gucciRunId = 0
                                                                                                                                                                                                        local gucciActive = false
                                                                                                                                                                                                        local gucciTask = nil
                                                                                                                                                                                                        local checkGucciSeatTask = nil

                                                                                                                                                                                                        local function FWC(Parent, Name, Time)
                                                                                                                                                                                                            return Parent:FindFirstChild(Name) or Parent:WaitForChild(Name, Time or 3)
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function toy_spawn_gucci(name, cframe, vector)
                                                                                                                                                                                                            local ToySpawn = RS.MenuToys.SpawnToyRemoteFunction
                                                                                                                                                                                                            local InPlot, InOwnerPlot, CanSpawn = LP.InPlot, LP.InOwnedPlot, LP.CanSpawnToy
                                                                                                                                                                                                            while InPlot.Value and not InOwnerPlot.Value and not CanSpawn.Value do
                                                                                                                                                                                                                task.wait(0.01)
                                                                                                                                                                                                            end
                                                                                                                                                                                                            task.spawn(function()
                                                                                                                                                                                                                ToySpawn:InvokeServer(name, cframe, vector or Vector3.new())
                                                                                                                                                                                                            end)
                                                                                                                                                                                                            local BackPack = workspace:FindFirstChild(LP.Name .. 'SpawnedInToys')
                                                                                                                                                                                                            local SpawnedToy
                                                                                                                                                                                                            BackPack.ChildAdded:Once(function(toy)
                                                                                                                                                                                                                if toy.Name == name and toy:IsA("Model") then
                                                                                                                                                                                                                    SpawnedToy = toy
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end)
                                                                                                                                                                                                            local time = tick()
                                                                                                                                                                                                            while not SpawnedToy do
                                                                                                                                                                                                                if tick()-time < 2 then task.wait(0.01)
                                                                                                                                                                                                                else return false end
                                                                                                                                                                                                            end
                                                                                                                                                                                                            return SpawnedToy
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function GucciAntiGrab()
                                                                                                                                                                                                            if not gucciActive then return end
                                                                                                                                                                                                            gucciRunId = gucciRunId + 1
                                                                                                                                                                                                            local MyId = gucciRunId
                                                                                                                                                                                                            local char = LP.Character or LP.CharacterAdded:Wait()
                                                                                                                                                                                                            local hum = FWC(char, "Humanoid")
                                                                                                                                                                                                            hum.Sit = true
                                                                                                                                                                                                            task.wait(0.02)
                                                                                                                                                                                                            hum.Sit = false
                                                                                                                                                                                                            task.wait(0.02)
                                                                                                                                                                                                            task.spawn(function()
                                                                                                                                                                                                                local time = tick()
                                                                                                                                                                                                                while tick()-time < 0.8 do
                                                                                                                                                                                                                    for _,v in pairs(char:GetChildren()) do
                                                                                                                                                                                                                        if v:IsA('BasePart') then v.Velocity = Vector3.new() end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    task.wait(0.01)
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end)
                                                                                                                                                                                                            local autoGucciT, sitJumpT, Blob, BHead = true, false, nil, nil
                                                                                                                                                                                                            task.spawn(function()
                                                                                                                                                                                                                while not Blob and MyId == gucciRunId do task.wait(0.01) end
                                                                                                                                                                                                                if MyId ~= gucciRunId then return end
                                                                                                                                                                                                                BHead = FWC(Blob, "Head")
                                                                                                                                                                                                                local HitBox = FWC(Blob, "GrabbableHitbox")
                                                                                                                                                                                                                while MyId == gucciRunId and BHead and
                                                                                                                                                                                                                (not BHead:FindFirstChild("PartOwner") or BHead.PartOwner.Value ~= LP.Name) do
                                                                                                                                                                                                                    if HitBox then sno(HitBox) end
                                                                                                                                                                                                                    task.wait(0.01)
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end)
                                                                                                                                                                                                            local hrp = FWC(char, "HumanoidRootPart")
                                                                                                                                                                                                            Blob = toy_spawn_gucci("CreatureBlobman", hrp.CFrame * CFrame.new(0, 0, -5), Vector3.new(0, -15.716, 0))
                                                                                                                                                                                                            if not Blob then return end
                                                                                                                                                                                                            local Seat = FWC(Blob, "VehicleSeat")
                                                                                                                                                                                                            task.defer(function()
                                                                                                                                                                                                                if not(char or hum) then return end
                                                                                                                                                                                                                local startTime = tick()
                                                                                                                                                                                                                while autoGucciT and MyId == gucciRunId and tick()-startTime < 0.3 do
                                                                                                                                                                                                                    if Blob and Blob.Parent then
                                                                                                                                                                                                                        if Seat and Seat.Parent and Seat.Occupant ~= hum then Seat:Sit(hum) end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    task.wait(0.03)
                                                                                                                                                                                                                    if char and hum and hum.Parent then hum:ChangeState(Enum.HumanoidStateType.Jumping) end
                                                                                                                                                                                                                    task.wait(0.03)
                                                                                                                                                                                                                end
                                                                                                                                                                                                                autoGucciT = false
                                                                                                                                                                                                                sitJumpT = false
                                                                                                                                                                                                            end)
                                                                                                                                                                                                            sitJumpT = true
                                                                                                                                                                                                            task.defer(function()
                                                                                                                                                                                                                while sitJumpT and MyId == gucciRunId do
                                                                                                                                                                                                                    if char and hrp and hrp.Parent and _G.RagdollRemote_Def then
                                                                                                                                                                                                                        _G.RagdollRemote_Def:FireServer(hrp, 0.095)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    task.wait(0.01)
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end)
                                                                                                                                                                                                            task.wait(0.4)
                                                                                                                                                                                                            if MyId ~= gucciRunId then return end
                                                                                                                                                                                                            hum.Sit = false
                                                                                                                                                                                                            Blob.Name = "Gucci"
                                                                                                                                                                                                            for _,v in pairs(Blob:GetChildren()) do
                                                                                                                                                                                                                if v:IsA("BasePart") then
                                                                                                                                                                                                                    v.CanCollide = false
                                                                                                                                                                                                                    v.CanTouch = false
                                                                                                                                                                                                                    v.CanQuery = false
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                            task.defer(function()
                                                                                                                                                                                                                while MyId == gucciRunId and Blob and BHead do
                                                                                                                                                                                                                    BHead.CFrame = CFrame.new(BHead.Position.X, 1e5, BHead.Position.Z)
                                                                                                                                                                                                                    task.wait(0.01)
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end)
                                                                                                                                                                                                        end

                                                                                                                                                                                                        DefL:CreateToggle({
                                                                                                                                                                                                            Name = "Gucci Anti Grab",
                                                                                                                                                                                                            Flag = "GucciAntiGrab",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                gucciActive = Value
                                                                                                                                                                                                                if gucciTask then task.cancel(gucciTask) gucciTask = nil end
                                                                                                                                                                                                                if checkGucciSeatTask then task.cancel(checkGucciSeatTask) checkGucciSeatTask = nil end
                                                                                                                                                                                                                if not Value then
                                                                                                                                                                                                                    local BackPack = workspace:FindFirstChild(LP.Name .. 'SpawnedInToys')
                                                                                                                                                                                                                    if BackPack then
                                                                                                                                                                                                                        for _, v in pairs(BackPack:GetChildren()) do
                                                                                                                                                                                                                            if v.Name == "Gucci" or v.Name == "CreatureBlobman" then
                                                                                                                                                                                                                                pcall(function() if _G.DestroyToy_Def then _G.DestroyToy_Def:FireServer(v) end end)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    return
                                                                                                                                                                                                                end
                                                                                                                                                                                                                gucciTask = task.spawn(function()
                                                                                                                                                                                                                    while gucciActive do
                                                                                                                                                                                                                        local BackPack = workspace:FindFirstChild(LP.Name .. 'SpawnedInToys')
                                                                                                                                                                                                                        local gucci = BackPack and BackPack:FindFirstChild("Gucci")
                                                                                                                                                                                                                        if not gucci then GucciAntiGrab() end
                                                                                                                                                                                                                        task.wait(0.5)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                                checkGucciSeatTask = task.spawn(function()
                                                                                                                                                                                                                    while gucciActive do
                                                                                                                                                                                                                        local char = LP.Character
                                                                                                                                                                                                                        local hum = char and char:FindFirstChild("Humanoid")
                                                                                                                                                                                                                        if hum and hum.SeatPart then
                                                                                                                                                                                                                            local seatParent = hum.SeatPart.Parent
                                                                                                                                                                                                                            if seatParent and (seatParent.Name == "Gucci" or seatParent.Name == "CreatureBlobman") then
                                                                                                                                                                                                                                local isOurGucci = false
                                                                                                                                                                                                                                local BackPack = workspace:FindFirstChild(LP.Name .. 'SpawnedInToys')
                                                                                                                                                                                                                                if BackPack then
                                                                                                                                                                                                                                    for _, v in pairs(BackPack:GetChildren()) do
                                                                                                                                                                                                                                        if v == seatParent then isOurGucci = true break end
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                if isOurGucci then
                                                                                                                                                                                                                                    pcall(function() if _G.DestroyToy_Def then _G.DestroyToy_Def:FireServer(seatParent) end end)
                                                                                                                                                                                                                                    task.wait(0.2)
                                                                                                                                                                                                                                    if gucciActive then GucciAntiGrab() end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        task.wait(0.3)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- ANTI OWNERSHIP 1
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local antiOwnershipActive = false
                                                                                                                                                                                                        local antiOwnershipTask   = nil

                                                                                                                                                                                                        DefL:CreateToggle({
                                                                                                                                                                                                            Name = "Anti Ownership",
                                                                                                                                                                                                            Flag = "AntiOwnership",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                antiOwnershipActive = Value
                                                                                                                                                                                                                if antiOwnershipTask then task.cancel(antiOwnershipTask) antiOwnershipTask = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                antiOwnershipTask = task.spawn(function()
                                                                                                                                                                                                                    while antiOwnershipActive do
                                                                                                                                                                                                                        pcall(function()
                                                                                                                                                                                                                            local character = LP.Character
                                                                                                                                                                                                                            if character and character:FindFirstChild("Head") then
                                                                                                                                                                                                                                local head = character.Head
                                                                                                                                                                                                                                if head:FindFirstChild("PartOwner") then
                                                                                                                                                                                                                                    if _G.Struggle_Def then _G.Struggle_Def:FireServer(LP) end
                                                                                                                                                                                                                                    for _, part in pairs(character:GetChildren()) do
                                                                                                                                                                                                                                        if part:IsA("BasePart") then part.Anchored = true end
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                    local isHeld = LP:FindFirstChild("IsHeld")
                                                                                                                                                                                                                                    while isHeld and isHeld.Value and antiOwnershipActive do task.wait() end
                                                                                                                                                                                                                                    for _, part in pairs(character:GetChildren()) do
                                                                                                                                                                                                                                        if part:IsA("BasePart") then part.Anchored = false end
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                        task.wait(0.1)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- ANTI OWNERSHIP 2
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local antiOwn2Active = false
                                                                                                                                                                                                        local antiOwn2Conn   = nil
                                                                                                                                                                                                        local antiOwn2SavedCF = nil
                                                                                                                                                                                                        local antiOwn2Loop   = nil

                                                                                                                                                                                                        DefL:CreateToggle({
                                                                                                                                                                                                            Name = "Anti Ownership 2",
                                                                                                                                                                                                            Flag = "AntiOwnership2",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                antiOwn2Active = Value
                                                                                                                                                                                                                if antiOwn2Conn then antiOwn2Conn:Disconnect() antiOwn2Conn = nil end
                                                                                                                                                                                                                if antiOwn2Loop then task.cancel(antiOwn2Loop) antiOwn2Loop = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                local isHeld = LP:WaitForChild("IsHeld", 5)
                                                                                                                                                                                                                local struggleEvent = RS:WaitForChild("CharacterEvents"):WaitForChild("Struggle")
                                                                                                                                                                                                                antiOwn2Conn = isHeld.Changed:Connect(function(heldState)
                                                                                                                                                                                                                    if not antiOwn2Active then return end
                                                                                                                                                                                                                    local char = LP.Character
                                                                                                                                                                                                                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if heldState then
                                                                                                                                                                                                                        if hrp then
                                                                                                                                                                                                                            antiOwn2SavedCF = hrp.CFrame
                                                                                                                                                                                                                            hrp.Anchored = true
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        antiOwn2Loop = task.spawn(function()
                                                                                                                                                                                                                            while isHeld and isHeld.Value and antiOwn2Active do
                                                                                                                                                                                                                                struggleEvent:FireServer(LP)
                                                                                                                                                                                                                                task.wait()
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                            if hrp and hrp.Parent then
                                                                                                                                                                                                                                hrp.Anchored = false
                                                                                                                                                                                                                                if antiOwn2SavedCF then hrp.CFrame = antiOwn2SavedCF end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                    else
                                                                                                                                                                                                                        if hrp and hrp.Parent then
                                                                                                                                                                                                                            hrp.Anchored = false
                                                                                                                                                                                                                            if antiOwn2SavedCF then hrp.CFrame = antiOwn2SavedCF end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- ANTI EXPLOSION
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local antiExplosionActive = false
                                                                                                                                                                                                        local antiExplosionConn   = nil

                                                                                                                                                                                                        DefL:CreateToggle({
                                                                                                                                                                                                            Name = "Anti Explosion",
                                                                                                                                                                                                            Flag = "AntiExplosion",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                antiExplosionActive = Value
                                                                                                                                                                                                                if antiExplosionConn then antiExplosionConn:Disconnect() antiExplosionConn = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                antiExplosionConn = workspace.ChildAdded:Connect(function(model)
                                                                                                                                                                                                                    if not antiExplosionActive then return end
                                                                                                                                                                                                                    if model.Name ~= "Part" then return end
                                                                                                                                                                                                                    local char = LP.Character
                                                                                                                                                                                                                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not hrp then return end
                                                                                                                                                                                                                    local ok, pos = pcall(function() return model.Position end)
                                                                                                                                                                                                                    if not ok then return end
                                                                                                                                                                                                                    if (pos - hrp.Position).Magnitude <= 20 then
                                                                                                                                                                                                                        local bp = Instance.new("BodyPosition")
                                                                                                                                                                                                                        bp.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                                                                                                                                                                                                                        bp.P = 1e6
                                                                                                                                                                                                                        bp.D = 5000
                                                                                                                                                                                                                        bp.Position = hrp.Position
                                                                                                                                                                                                                        bp.Name = "TrueAmAmExplodeFix"
                                                                                                                                                                                                                        bp.Parent = hrp
                                                                                                                                                                                                                        task.delay(0.25, function()
                                                                                                                                                                                                                            if bp and bp.Parent then bp:Destroy() end
                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- ANTI FIRE
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local antiFireActive = false
                                                                                                                                                                                                        local antiFireConn   = nil

                                                                                                                                                                                                        local function GetAnyPlotBarrier()
                                                                                                                                                                                                            local plots = workspace:FindFirstChild("Plots")
                                                                                                                                                                                                            if not plots then return nil end
                                                                                                                                                                                                            for i = 1, 5 do
                                                                                                                                                                                                                local p = plots:FindFirstChild("Plot" .. i)
                                                                                                                                                                                                                local b = p and p:FindFirstChild("Barrier")
                                                                                                                                                                                                                local pb = b and b:FindFirstChild("PlotBarrier")
                                                                                                                                                                                                                if pb and pb:IsA("BasePart") then return pb end
                                                                                                                                                                                                            end
                                                                                                                                                                                                            return nil
                                                                                                                                                                                                        end

                                                                                                                                                                                                        DefL:CreateToggle({
                                                                                                                                                                                                            Name = "Anti Fire",
                                                                                                                                                                                                            Flag = "AntiFire",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                antiFireActive = Value
                                                                                                                                                                                                                if antiFireConn then antiFireConn:Disconnect() antiFireConn = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                local char = LP.Character
                                                                                                                                                                                                                if not char then return end
                                                                                                                                                                                                                local hum = char:WaitForChild("Humanoid", 5)
                                                                                                                                                                                                                if not hum then return end
                                                                                                                                                                                                                local fireDeb = hum:WaitForChild("FireDebounce", 5)
                                                                                                                                                                                                                if not fireDeb then return end
                                                                                                                                                                                                                antiFireConn = fireDeb.Changed:Connect(function(isBurning)
                                                                                                                                                                                                                    if not antiFireActive or not isBurning then return end
                                                                                                                                                                                                                    local char2 = LP.Character
                                                                                                                                                                                                                    if not char2 then return end
                                                                                                                                                                                                                    local hrp = char2:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not hrp then return end
                                                                                                                                                                                                                    char2.PrimaryPart = hrp
                                                                                                                                                                                                                    local oldCF = hrp.CFrame
                                                                                                                                                                                                                    local pb = GetAnyPlotBarrier()
                                                                                                                                                                                                                    if pb then
                                                                                                                                                                                                                        pcall(function() char2:SetPrimaryPartCFrame(pb.CFrame * CFrame.new(0, 6, 0)) end)
                                                                                                                                                                                                                        task.wait(0.3)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    local firePart = char2:FindFirstChild("FirePlayerPart", true)
                                                                                                                                                                                                                    if firePart then
                                                                                                                                                                                                                        for _, obj in ipairs(firePart:GetChildren()) do
                                                                                                                                                                                                                            if obj:IsA("Sound") then pcall(function() obj:Stop() end) end
                                                                                                                                                                                                                            if obj:IsA("Light") or obj:IsA("ParticleEmitter") then pcall(function() obj.Enabled = false end) end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        if firePart:FindFirstChild("CanBurn") then
                                                                                                                                                                                                                            pcall(function() firePart.CanBurn.Value = false end)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    if hum:FindFirstChild("FireDebounce") then
                                                                                                                                                                                                                        pcall(function() hum.FireDebounce.Value = false end)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    task.wait(0.5)
                                                                                                                                                                                                                    if char2 and char2.PrimaryPart and antiFireActive then
                                                                                                                                                                                                                        pcall(function() char2:SetPrimaryPartCFrame(oldCF) end)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

