                                                                                                                                                                                                        -- ANTI BANANA SIT
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local antiBananaActive = false
                                                                                                                                                                                                        local antiBananaConn   = nil

                                                                                                                                                                                                        DefR:CreateToggle({
                                                                                                                                                                                                            Name = "Anti Banana Sit",
                                                                                                                                                                                                            Flag = "AntiBananaSit",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                antiBananaActive = Value
                                                                                                                                                                                                                if antiBananaConn then antiBananaConn:Disconnect() antiBananaConn = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                antiBananaConn = R.Heartbeat:Connect(function()
                                                                                                                                                                                                                    if not antiBananaActive then return end
                                                                                                                                                                                                                    local char = LP.Character
                                                                                                                                                                                                                    local hum = char and char:FindFirstChild("Humanoid")
                                                                                                                                                                                                                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if hum and hrp and hum.Health > 0 then
                                                                                                                                                                                                                        hum.Sit = true
                                                                                                                                                                                                                        hum:ChangeState(Enum.HumanoidStateType.Running)
                                                                                                                                                                                                                        local cam = workspace.CurrentCamera
