                                                                                                                                                                                                                            local lookVec = cam.CFrame.LookVector
                                                                                                                                                                                                                            hrp.CFrame = CFrame.new(hrp.Position, hrp.Position + Vector3.new(lookVec.X, 0, lookVec.Z))
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- ANTI RAGDOLL ON BLOB
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local antiRagBlobActive = false
                                                                                                                                                                                                        local antiRagBlobConnections = {}
                                                                                                                                                                                                        local RagdolledSit = false

                                                                                                                                                                                                        local function ApplyAntiRagdoll(char)
                                                                                                                                                                                                            if not char or not antiRagBlobActive then return end
                                                                                                                                                                                                            local hum = char:WaitForChild("Humanoid", 5)
                                                                                                                                                                                                            local HRP = char:WaitForChild("HumanoidRootPart", 5)
                                                                                                                                                                                                            if not (hum and HRP) then return end
                                                                                                                                                                                                            if antiRagBlobConnections["ARSeat"] then antiRagBlobConnections["ARSeat"]:Disconnect() end
                                                                                                                                                                                                            antiRagBlobConnections["ARSeat"] = hum:GetPropertyChangedSignal("SeatPart"):Connect(function()
                                                                                                                                                                                                                if hum.SeatPart and hum.SeatPart.Parent and hum.SeatPart.Parent.Name == "CreatureBlobman" and not RagdolledSit then
                                                                                                                                                                                                                    RagdolledSit = true
                                                                                                                                                                                                                    local Seat = hum.SeatPart
                                                                                                                                                                                                                    while not hum.Sit do task.wait() end
                                                                                                                                                                                                                    if _G.RagdollRemote_Def then _G.RagdollRemote_Def:FireServer(HRP, 3) end
                                                                                                                                                                                                                    local ragdolledVal = hum:FindFirstChild("Ragdolled")
                                                                                                                                                                                                                    while ragdolledVal and not ragdolledVal.Value and not hum.Sit do task.wait() end
                                                                                                                                                                                                                    task.wait(0.4)
                                                                                                                                                                                                                    hum.Sit = false
                                                                                                                                                                                                                    Seat:Sit(hum)
                                                                                                                                                                                                                    task.delay(0.25, function()
                                                                                                                                                                                                                        while hum and hum.SeatPart do
                                                                                                                                                                                                                            if _G.RagdollRemote_Def then _G.RagdollRemote_Def:FireServer(HRP, 1) end
                                                                                                                                                                                                                            task.wait(0.05)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        RagdolledSit = false
                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end)
                                                                                                                                                                                                        end

                                                                                                                                                                                                        DefR:CreateToggle({
                                                                                                                                                                                                            Name = "Anti Ragdoll (On Blob)",
                                                                                                                                                                                                            Flag = "AntiRagdoll",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                antiRagBlobActive = Value
                                                                                                                                                                                                                RagdolledSit = false
                                                                                                                                                                                                                if antiRagBlobConnections["ARChar"] then antiRagBlobConnections["ARChar"]:Disconnect() end
                                                                                                                                                                                                                if antiRagBlobConnections["ARSeat"] then antiRagBlobConnections["ARSeat"]:Disconnect() end
                                                                                                                                                                                                                if antiRagBlobActive then
                                                                                                                                                                                                                    ApplyAntiRagdoll(LP.Character)
                                                                                                                                                                                                                    antiRagBlobConnections["ARChar"] = LP.CharacterAdded:Connect(ApplyAntiRagdoll)
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

