                                                                                                                                                                                                        -- FLYING RESET
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local flyingResetActive = false
                                                                                                                                                                                                        local flyingResetConn   = nil

                                                                                                                                                                                                        DefR:CreateToggle({
                                                                                                                                                                                                            Name = "Flying Reset",
                                                                                                                                                                                                            Flag = "FlyingReset",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                flyingResetActive = Value
                                                                                                                                                                                                                if flyingResetConn then flyingResetConn:Disconnect() flyingResetConn = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                local CorrectionEvents = RS:FindFirstChild("GameCorrectionEvents")
                                                                                                                                                                                                                local GameNotify = CorrectionEvents and CorrectionEvents:FindFirstChild("GameCorrectionsNotify")
                                                                                                                                                                                                                if not GameNotify then return end
                                                                                                                                                                                                                local struggle = RS:FindFirstChild("CharacterEvents") and RS.CharacterEvents:FindFirstChild("Struggle")
                                                                                                                                                                                                                flyingResetConn = GameNotify.OnClientEvent:Connect(function(Type)
                                                                                                                                                                                                                    if not flyingResetActive then return end
                                                                                                                                                                                                                    if Type == "Flying" then
