                                                                                                                                                                                                                        local char = LP.Character
                                                                                                                                                                                                                        if char then
                                                                                                                                                                                                                            local hum = char:FindFirstChildOfClass("Humanoid")
                                                                                                                                                                                                                            if hum then hum.Health = 0 end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- TELEKINESIS SHIELD
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local tkShieldActive = false
                                                                                                                                                                                                        local tkShieldConn   = nil

                                                                                                                                                                                                        DefR:CreateToggle({
                                                                                                                                                                                                            Name = "Telekinesis Shield",
                                                                                                                                                                                                            Flag = "TelekinesisShield",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                tkShieldActive = Value
                                                                                                                                                                                                                if tkShieldConn then tkShieldConn:Disconnect() tkShieldConn = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                tkShieldConn = R.Heartbeat:Connect(function()
                                                                                                                                                                                                                    if not tkShieldActive then return end
                                                                                                                                                                                                                    local char = LP.Character
                                                                                                                                                                                                                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not hrp then return end
                                                                                                                                                                                                                    for _, v in pairs(workspace:GetDescendants()) do
                                                                                                                                                                                                                        if v:IsA("BasePart") and not v.Anchored and not v:IsDescendantOf(char) then
                                                                                                                                                                                                                            local dist = (v.Position - hrp.Position).Magnitude
                                                                                                                                                                                                                            if dist <= 60 then
                                                                                                                                                                                                                                local pushDir = (v.Position - hrp.Position).Unit
                                                                                                                                                                                                                                local velocity = (pushDir + Vector3.new(0, 0.2, 0)).Unit * 100
                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                    if _G.SetNetOwner_Def then _G.SetNetOwner_Def:FireServer(v, v.CFrame) end
                                                                                                                                                                                                                                    v.AssemblyLinearVelocity = velocity
                                                                                                                                                                                                                                    v.AssemblyAngularVelocity = Vector3.new(math.random(-10,10), math.random(-10,10), math.random(-10,10))
                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- FLING AURA
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local flingAuraActive = false
                                                                                                                                                                                                        local flingAuraTask   = nil
                                                                                                                                                                                                        local flingAuraStrength = 400

                                                                                                                                                                                                        DefR:CreateToggle({
                                                                                                                                                                                                            Name = "Fling Aura",
                                                                                                                                                                                                            Flag = "FlingAura",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                flingAuraActive = Value
                                                                                                                                                                                                                if flingAuraTask then task.cancel(flingAuraTask) flingAuraTask = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                flingAuraTask = task.spawn(function()
                                                                                                                                                                                                                    while flingAuraActive do
                                                                                                                                                                                                                        pcall(function()
                                                                                                                                                                                                                            local char = LP.Character
                                                                                                                                                                                                                            local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                            if not hrp then return end
                                                                                                                                                                                                                            for _, plr in ipairs(P:GetPlayers()) do
                                                                                                                                                                                                                                if plr ~= LP and plr.Character and not IsFriend(plr) then
                                                                                                                                                                                                                                    local tRoot = plr.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                                    local tHum = plr.Character:FindFirstChild("Humanoid")
                                                                                                                                                                                                                                    if tRoot and tHum and tHum.Health > 0 then
                                                                                                                                                                                                                                        if (tRoot.Position - hrp.Position).Magnitude <= 30 then
                                                                                                                                                                                                                                            pcall(function()
                                                                                                                                                                                                                                                if _G.SetNetOwner_Def then _G.SetNetOwner_Def:FireServer(tRoot, tRoot.CFrame) end
                                                                                                                                                                                                                                                if not tRoot:FindFirstChild("TrueAmAmFlingAura") then
                                                                                                                                                                                                                                                    local bv = Instance.new("BodyVelocity")
                                                                                                                                                                                                                                                    bv.Name = "TrueAmAmFlingAura"
                                                                                                                                                                                                                                                    bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                                                                                                                                                                                                                                                    local dir = (tRoot.Position - hrp.Position).Unit
                                                                                                                                                                                                                                                    bv.Velocity = Vector3.new(dir.X, 0.5, dir.Z) * flingAuraStrength
                                                                                                                                                                                                                                                    bv.Parent = tRoot
                                                                                                                                                                                                                                                    Debris:AddItem(bv, 0.3)
                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                            end)
                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                        task.wait(0.1)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        DefR:CreateSlider({
                                                                                                                                                                                                            Name = "Fling Aura Strength",
                                                                                                                                                                                                            Flag = "FlingAuraStrength",
                                                                                                                                                                                                            Min = 100, Max = 2000, Default = 400,
                                                                                                                                                                                                            Callback = function(v) flingAuraStrength = v end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- DEATH AURA
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local deathAuraActive = false
                                                                                                                                                                                                        local deathAuraConn   = nil

                                                                                                                                                                                                        DefR:CreateToggle({
