                                                                                                                                                                                                        local antiBlobAuraActive = false
                                                                                                                                                                                                        local antiBlobAuraConn   = nil

                                                                                                                                                                                                        DefR:CreateToggle({
                                                                                                                                                                                                            Name = "Anti Blobman Aura",
                                                                                                                                                                                                            Flag = "AntiBlobmanAura",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                antiBlobAuraActive = Value
                                                                                                                                                                                                                if antiBlobAuraConn then antiBlobAuraConn:Disconnect() antiBlobAuraConn = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                antiBlobAuraConn = R.Heartbeat:Connect(function()
                                                                                                                                                                                                                    if not antiBlobAuraActive then return end
                                                                                                                                                                                                                    local myChar = LP.Character
                                                                                                                                                                                                                    local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not myRoot then return end
                                                                                                                                                                                                                    for _, player in pairs(P:GetPlayers()) do
