                                                                                                                                                                                                        DefR:CreateButton({
                                                                                                                                                                                                            Name = "Break PCLD",
                                                                                                                                                                                                            Callback = function()
                                                                                                                                                                                                                local serverPos = CFrame.new(-272.2197265625, -7.350403785705566, 475.0108947753906)
                                                                                                                                                                                                                workspace.FallenPartsDestroyHeight = 0/0
                                                                                                                                                                                                                local storedJoints = {}
                                                                                                                                                                                                                local char = LP.Character
                                                                                                                                                                                                                if not char then return end
                                                                                                                                                                                                                local root = char:WaitForChild("HumanoidRootPart")
                                                                                                                                                                                                                for _, v in ipairs(char:GetDescendants()) do
                                                                                                                                                                                                                    if v:IsA("Motor6D") then
                                                                                                                                                                                                                        storedJoints[v] = v.Part0
                                                                                                                                                                                                                        v.Part0 = nil
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end
                                                                                                                                                                                                                root.CFrame = serverPos
                                                                                                                                                                                                                local conn = R.RenderStepped:Connect(function()
                                                                                                                                                                                                                    root.AssemblyLinearVelocity = Vector3.zero
                                                                                                                                                                                                                    root.AssemblyAngularVelocity = Vector3.zero
                                                                                                                                                                                                                end)
                                                                                                                                                                                                                task.wait(0.12)
                                                                                                                                                                                                                if conn then conn:Disconnect() end
                                                                                                                                                                                                                for m, p0 in pairs(storedJoints) do
                                                                                                                                                                                                                    if m and m.Parent then m.Part0 = p0 end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- ANTI INPUT LAG
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local AntiInputLagToys = {
                                                                                                                                                                                                            ["Burger"] = "FoodHamburger", ["Pizza"] = "FoodPizzaCheese",
                                                                                                                                                                                                            ["Hotdog"] = "FoodHotdog", ["Donut"] = "FoodDonut",
                                                                                                                                                                                                            ["Cake"] = "FoodCakePink", ["Fries"] = "FoodFrenchFries",
                                                                                                                                                                                                            ["Coconut"] = "FoodCoconut", ["Banana"] = "FoodBanana",
                                                                                                                                                                                                            ["Poop"] = "PoopPile", ["WhiteMug"] = "CupMugWhite",
                                                                                                                                                                                                            ["Ocarina"] = "InstrumentWoodwindOcarina", ["Banjo"] = "InstrumentGuitarBanjo",
                                                                                                                                                                                                            ["Violin"] = "InstrumentGuitarViolin", ["Ukulele"] = "InstrumentGuitarUkulele",
                                                                                                                                                                                                            ["Sax"] = "InstrumentWoodwindSaxophone", ["Bongos"] = "InstrumentDrumBongos",
                                                                                                                                                                                                            ["Snare"] = "InstrumentDrumSnare", ["Mic"] = "InstrumentVoiceMicrophone",
                                                                                                                                                                                                        }
                                                                                                                                                                                                        local AntiInputDropdownValues = {}
                                                                                                                                                                                                        for shortName, _ in pairs(AntiInputLagToys) do
                                                                                                                                                                                                            table.insert(AntiInputDropdownValues, shortName)
                                                                                                                                                                                                        end
                                                                                                                                                                                                        table.sort(AntiInputDropdownValues)
                                                                                                                                                                                                        local SelectedAntiInputToy = "Burger"
                                                                                                                                                                                                        local AntiInputLagActive   = false
                                                                                                                                                                                                        local AntiInputLagTask     = nil

                                                                                                                                                                                                        DefR:CreateDropdown({
                                                                                                                                                                                                            Name = "Anti Input Lag Toy",
                                                                                                                                                                                                            Flag = "AntiInputLagToy",
                                                                                                                                                                                                            Items = AntiInputDropdownValues,
                                                                                                                                                                                                            Default = "Burger",
                                                                                                                                                                                                            Callback = function(v) SelectedAntiInputToy = v end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        DefR:CreateToggle({
                                                                                                                                                                                                            Name = "Anti Input Lag",
                                                                                                                                                                                                            Flag = "AntiInputLag",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                AntiInputLagActive = Value
                                                                                                                                                                                                                if AntiInputLagTask then task.cancel(AntiInputLagTask) AntiInputLagTask = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                AntiInputLagTask = task.spawn(function()
                                                                                                                                                                                                                    while AntiInputLagActive do
                                                                                                                                                                                                                        pcall(function()
                                                                                                                                                                                                                            local char = LP.Character
                                                                                                                                                                                                                            local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                            if not hrp then return end
                                                                                                                                                                                                                            local toyName = AntiInputLagToys[SelectedAntiInputToy] or "FoodHamburger"
                                                                                                                                                                                                                            local toysFolder = workspace:FindFirstChild(LP.Name .. "SpawnedInToys")
                                                                                                                                                                                                                            local item = toysFolder and toysFolder:FindFirstChild(toyName)
                                                                                                                                                                                                                            if not item then
                                                                                                                                                                                                                                if _G.SpawnToy_Def then
                                                                                                                                                                                                                                    pcall(function()
                                                                                                                                                                                                                                        _G.SpawnToy_Def:InvokeServer(toyName, hrp.CFrame * CFrame.new(0, -12, 0), Vector3.zero)
                                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                task.wait(0.1)
                                                                                                                                                                                                                                toysFolder = workspace:FindFirstChild(LP.Name .. "SpawnedInToys")
                                                                                                                                                                                                                                item = toysFolder and toysFolder:FindFirstChild(toyName)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                            if item then
                                                                                                                                                                                                                                local holdPart = item:FindFirstChild("HoldPart")
                                                                                                                                                                                                                                if holdPart then
                                                                                                                                                                                                                                    for _, v in pairs(item:GetDescendants()) do
                                                                                                                                                                                                                                        if v:IsA("BasePart") then
                                                                                                                                                                                                                                            v.CanCollide = false
                                                                                                                                                                                                                                            v.Massless = true
                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                    if holdPart:FindFirstChild("HoldItemRemoteFunction") then
                                                                                                                                                                                                                                        task.spawn(function()
                                                                                                                                                                                                                                            pcall(function()
                                                                                                                                                                                                                                                holdPart.HoldItemRemoteFunction:InvokeServer(item, char)
                                                                                                                                                                                                                                            end)
                                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                    task.wait(0.02)
                                                                                                                                                                                                                                    if holdPart:FindFirstChild("DropItemRemoteFunction") then
                                                                                                                                                                                                                                        task.spawn(function()
                                                                                                                                                                                                                                            pcall(function()
                                                                                                                                                                                                                                                holdPart.DropItemRemoteFunction:InvokeServer(item, CFrame.new(0, 5000, 0), Vector3.zero)
                                                                                                                                                                                                                                            end)
                                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                        task.wait(0.02)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- ANTI KICK (SHURIKEN)
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local antiKickActive = false
                                                                                                                                                                                                        local antiKickTask   = nil

                                                                                                                                                                                                        local function AK_GetPlayersInPlots()
                                                                                                                                                                                                            local pi = workspace:FindFirstChild("PlotItems")
                                                                                                                                                                                                            return pi and pi:FindFirstChild("PlayersInPlots")
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function AK_ClearKunai()
                                                                                                                                                                                                            local inv = workspace:FindFirstChild(LP.Name .. "SpawnedInToys")
                                                                                                                                                                                                            if inv and _G.DestroyToy_Def then
                                                                                                                                                                                                                for _, v in pairs(inv:GetChildren()) do
                                                                                                                                                                                                                    if v.Name == "AntiKick" or v.Name == "NinjaShuriken" then
                                                                                                                                                                                                                        pcall(function() _G.DestroyToy_Def:FireServer(v) end)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function AK_GetHRP()
                                                                                                                                                                                                            if LP.Character and LP.Character:FindFirstChild("HumanoidRootPart") then
                                                                                                                                                                                                                return LP.Character.HumanoidRootPart
                                                                                                                                                                                                            else
                                                                                                                                                                                                                local character = LP.CharacterAdded:Wait()
                                                                                                                                                                                                                return character:WaitForChild("HumanoidRootPart")
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function AK_CheckForHome()
                                                                                                                                                                                                            local playersInPlots = AK_GetPlayersInPlots()
                                                                                                                                                                                                            if not playersInPlots or not playersInPlots:FindFirstChild(LP.Name) then return false end
                                                                                                                                                                                                            local plots = workspace:FindFirstChild("Plots")
                                                                                                                                                                                                            if not plots then return false end
                                                                                                                                                                                                            for _, v in pairs(plots:GetChildren()) do
                                                                                                                                                                                                                local sign = v:FindFirstChild("PlotSign")
                                                                                                                                                                                                                local owners = sign and sign:FindFirstChild("ThisPlotsOwners")
                                                                                                                                                                                                                if owners then
                                                                                                                                                                                                                    for _, b in pairs(owners:GetChildren()) do
                                                                                                                                                                                                                        if b.Value == LP.Name then
                                                                                                                                                                                                                            local pi = workspace:FindFirstChild("PlotItems")
                                                                                                                                                                                                                            local folder = pi and pi:FindFirstChild(v.Name)
                                                                                                                                                                                                                            if folder then return true, folder end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                            return false
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function AK_StickKunai(kunai)
                                                                                                                                                                                                            if not kunai or not kunai:FindFirstChild("StickyPart") then return end
                                                                                                                                                                                                            local currentHRP = AK_GetHRP()
                                                                                                                                                                                                            if not currentHRP then return end
                                                                                                                                                                                                            local soundPart = kunai:FindFirstChild("SoundPart")
                                                                                                                                                                                                            if soundPart and _G.SetNetOwner_Def then
                                                                                                                                                                                                                local po = soundPart:FindFirstChild("PartOwner")
                                                                                                                                                                                                                if not po or po.Value ~= LP.Name then
                                                                                                                                                                                                                    _G.SetNetOwner_Def:FireServer(soundPart, soundPart.CFrame)
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                            local firePart = currentHRP:FindFirstChild("FirePlayerPart") or currentHRP:WaitForChild("FirePlayerPart", 5)
                                                                                                                                                                                                            if firePart and _G.StickyPartEvent_Def then
                                                                                                                                                                                                                _G.StickyPartEvent_Def:FireServer(kunai.StickyPart, firePart, CFrame.new(0, 0, 0) * CFrame.Angles(0, math.rad(90), math.rad(90)))
                                                                                                                                                                                                            end
                                                                                                                                                                                                            for _, obj in pairs(kunai:GetChildren()) do
                                                                                                                                                                                                                if obj:IsA("BasePart") then
                                                                                                                                                                                                                    obj.CanTouch, obj.CanCollide, obj.CanQuery = false, false, false
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function AK_SpawnToy(name)
                                                                                                                                                                                                            local canSpawn = LP:FindFirstChild("CanSpawnToy")
                                                                                                                                                                                                            if not canSpawn then return nil end
                                                                                                                                                                                                            local t = tick()
                                                                                                                                                                                                            while not canSpawn.Value do
                                                                                                                                                                                                                if not antiKickActive or tick() - t > 5 then return nil end
                                                                                                                                                                                                                task.wait(0.1)
                                                                                                                                                                                                            end
                                                                                                                                                                                                            local currentHRP = AK_GetHRP()
                                                                                                                                                                                                            if currentHRP and _G.SpawnToy_Def then
                                                                                                                                                                                                                task.spawn(function()
                                                                                                                                                                                                                    pcall(function()
                                                                                                                                                                                                                        _G.SpawnToy_Def:InvokeServer(name, currentHRP.CFrame * CFrame.new(0, 12, 20), Vector3.new(0, 0, 0))
                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                            local boolik, house = AK_CheckForHome()
                                                                                                                                                                                                            local inv = workspace:FindFirstChild(LP.Name .. "SpawnedInToys")
                                                                                                                                                                                                            local playersInPlots = AK_GetPlayersInPlots()
                                                                                                                                                                                                            if boolik and house then
                                                                                                                                                                                                                return house:WaitForChild(name, 2)
                                                                                                                                                                                                            elseif (not playersInPlots or not playersInPlots:FindFirstChild(LP.Name)) and inv then
                                                                                                                                                                                                                return inv:WaitForChild(name, 2)
                                                                                                                                                                                                            end
                                                                                                                                                                                                            return nil
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function AK_MainLoop()
                                                                                                                                                                                                            while antiKickActive do
                                                                                                                                                                                                                task.wait(0.005)
                                                                                                                                                                                                                if not LP.Character or not LP.Character:FindFirstChild("Humanoid") or LP.Character.Humanoid.Health <= 0 then continue end
                                                                                                                                                                                                                local inv = workspace:FindFirstChild(LP.Name .. "SpawnedInToys")
                                                                                                                                                                                                                local kunai = inv and inv:FindFirstChild("NinjaShuriken")
                                                                                                                                                                                                                local playersInPlots = AK_GetPlayersInPlots()
                                                                                                                                                                                                                if playersInPlots and playersInPlots:FindFirstChild(LP.Name) then
                                                                                                                                                                                                                    local boolik, house = AK_CheckForHome()
                                                                                                                                                                                                                    if boolik and house then
                                                                                                                                                                                                                        local plots = workspace:FindFirstChild("Plots")
                                                                                                                                                                                                                        local plot = plots and plots:FindFirstChild(house.Name)
                                                                                                                                                                                                                        local sign = plot and plot:FindFirstChild("PlotSign")
                                                                                                                                                                                                                        if sign and sign.ThisPlotsOwners.Value.TimeRemainingNum.Value > 89 then
                                                                                                                                                                                                                            kunai = AK_SpawnToy("NinjaShuriken")
                                                                                                                                                                                                                            if kunai == nil then continue end
                                                                                                                                                                                                                            kunai.Name = "AntiKick"
                                                                                                                                                                                                                            AK_StickKunai(kunai)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end
                                                                                                                                                                                                                if not kunai then
                                                                                                                                                                                                                    if playersInPlots and playersInPlots:FindFirstChild(LP.Name) then continue end
                                                                                                                                                                                                                    kunai = AK_SpawnToy("NinjaShuriken")
                                                                                                                                                                                                                    if kunai == nil then continue end
                                                                                                                                                                                                                    kunai.Name = "AntiKick"
                                                                                                                                                                                                                end
                                                                                                                                                                                                                repeat
                                                                                                                                                                                                                    if kunai and kunai:FindFirstChild("StickyPart") and kunai.StickyPart.CanTouch == true then
                                                                                                                                                                                                                        AK_StickKunai(kunai)
                                                                                                                                                                                                                        kunai.Name = "AntiKick"
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    task.wait(0.3)
                                                                                                                                                                                                                until not kunai or not antiKickActive or not kunai:FindFirstChild("StickyPart") or kunai.StickyPart.CanTouch == false
                                                                                                                                                                                                                    or not LP.Character or not LP.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    or (LP.Character.HumanoidRootPart.Position - kunai.StickyPart.Position).Magnitude >= 20
                                                                                                                                                                                                                if not kunai or not kunai:FindFirstChild("StickyPart") or not LP.Character or not LP.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    or (LP.Character.HumanoidRootPart.Position - kunai.StickyPart.Position).Magnitude >= 20 then
                                                                                                                                                                                                                    AK_ClearKunai()
                                                                                                                                                                                                                end
                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                    repeat task.wait(0.05)
                                                                                                                                                                                                                    until not antiKickActive or not LP.Character or not LP.Character:FindFirstChild("Humanoid")
                                                                                                                                                                                                                        or not kunai or not kunai:FindFirstChild("StickyPart") or not kunai.StickyPart:FindFirstChild("StickyWeld")
                                                                                                                                                                                                                        or not kunai.StickyPart.StickyWeld.Part1
                                                                                                                                                                                                                    if not kunai or not kunai:FindFirstChild("StickyPart")
                                                                                                                                                                                                                        or (LP.Character and LP.Character:FindFirstChild("Humanoid") and LP.Character.Humanoid.Health <= 0)
                                                                                                                                                                                                                        or not kunai["StickyPart"]:FindFirstChild("StickyWeld").Part1 then
                                                                                                                                                                                                                        AK_ClearKunai()
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                            AK_ClearKunai()
                                                                                                                                                                                                        end

                                                                                                                                                                                                        DefK:CreateToggle({
                                                                                                                                                                                                            Name = "Anti Kick (Shuriken)",
                                                                                                                                                                                                            Flag = "AntiKick",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                antiKickActive = Value
                                                                                                                                                                                                                if Value then
                                                                                                                                                                                                                    antiKickTask = task.spawn(AK_MainLoop)
                                                                                                                                                                                                                else
                                                                                                                                                                                                                    AK_ClearKunai()
                                                                                                                                                                                                                    if antiKickTask then task.cancel(antiKickTask) antiKickTask = nil end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })
                                                                                                                                                                                                    end

