                                                                                                                                                                                                    do
                                                                                                                                                                                                        local AuraL = Tabs.Auras:CreateBlock({Name = "Offensive Auras", Side = "Left", ImageID = "12614416526"})
                                                                                                                                                                                                        local AuraR = Tabs.Auras:CreateBlock({Name = "Utility Auras", Side = "Right", ImageID = "12614416526"})

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- TELEKINESIS AURA
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local tkAuraActive = false
                                                                                                                                                                                                        local tkAuraConn   = nil

                                                                                                                                                                                                        AuraL:CreateToggle({
                                                                                                                                                                                                            Name = "Telekinesis Aura",
                                                                                                                                                                                                            Flag = "TelekinesisAura",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                tkAuraActive = Value
                                                                                                                                                                                                                if tkAuraConn then tkAuraConn:Disconnect() tkAuraConn = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                tkAuraConn = R.Heartbeat:Connect(function()
                                                                                                                                                                                                                    if not tkAuraActive then return end
                                                                                                                                                                                                                    local char = LP.Character
                                                                                                                                                                                                                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not hrp then return end
                                                                                                                                                                                                                    local cam = workspace.CurrentCamera
                                                                                                                                                                                                                    for _, plr in ipairs(P:GetPlayers()) do
                                                                                                                                                                                                                        if plr ~= LP and plr.Character then
                                                                                                                                                                                                                            local tChar = plr.Character
                                                                                                                                                                                                                            local tRoot = tChar:FindFirstChild("Torso") or tChar:FindFirstChild("UpperTorso")
                                                                                                                                                                                                                            if tRoot and (tRoot.Position - hrp.Position).Magnitude <= 25 then
                                                                                                                                                                                                                                if _G.SetNetOwner_Def then _G.SetNetOwner_Def:FireServer(tRoot, hrp.CFrame) end
                                                                                                                                                                                                                                for _, part in ipairs(tChar:GetDescendants()) do
                                                                                                                                                                                                                                    if part:IsA("BasePart") then part.CanCollide = false end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                local bp = tRoot:FindFirstChild("TrueAmAmTKPos") or Instance.new("BodyPosition")
                                                                                                                                                                                                                                bp.Name = "TrueAmAmTKPos"
                                                                                                                                                                                                                                bp.MaxForce = Vector3.new(100000, 100000, 100000)
                                                                                                                                                                                                                                bp.D = 500
                                                                                                                                                                                                                                bp.P = 50000
                                                                                                                                                                                                                                bp.Parent = tRoot
                                                                                                                                                                                                                                local bg = tRoot:FindFirstChild("TrueAmAmTKGyro") or Instance.new("BodyGyro")
                                                                                                                                                                                                                                bg.Name = "TrueAmAmTKGyro"
                                                                                                                                                                                                                                bg.MaxTorque = Vector3.new(100000, 100000, 100000)
                                                                                                                                                                                                                                bg.D = 500
                                                                                                                                                                                                                                bg.P = 50000
                                                                                                                                                                                                                                bg.Parent = tRoot
                                                                                                                                                                                                                                local look = cam.CFrame.LookVector
                                                                                                                                                                                                                                bp.Position = hrp.Position + look * 15 + Vector3.new(0, 5, 0)
                                                                                                                                                                                                                                bg.CFrame = CFrame.new(tRoot.Position, hrp.Position)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- FLING AURA (Auras tab version)
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local flingAura2Active = false
                                                                                                                                                                                                        local flingAura2Conn   = nil
                                                                                                                                                                                                        local flingStrength2    = 400

                                                                                                                                                                                                        AuraL:CreateToggle({
                                                                                                                                                                                                            Name = "Fling Aura",
                                                                                                                                                                                                            Flag = "FlingAura2",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                flingAura2Active = Value
                                                                                                                                                                                                                if flingAura2Conn then flingAura2Conn:Disconnect() flingAura2Conn = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                flingAura2Conn = R.Heartbeat:Connect(function()
                                                                                                                                                                                                                    if not flingAura2Active then return end
                                                                                                                                                                                                                    local char = LP.Character
                                                                                                                                                                                                                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not hrp then return end
                                                                                                                                                                                                                    for _, plr in ipairs(P:GetPlayers()) do
                                                                                                                                                                                                                        if plr ~= LP and plr.Character and not IsFriend(plr) then
                                                                                                                                                                                                                            local tRoot = plr.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                            local tHum = plr.Character:FindFirstChildOfClass("Humanoid")
                                                                                                                                                                                                                            if tRoot and tHum and tHum.Health > 0 then
                                                                                                                                                                                                                                if (tRoot.Position - hrp.Position).Magnitude <= 30 then
                                                                                                                                                                                                                                    pcall(function()
                                                                                                                                                                                                                                        if _G.SetNetOwner_Def then _G.SetNetOwner_Def:FireServer(tRoot, tRoot.CFrame) end
                                                                                                                                                                                                                                        if not tRoot:FindFirstChild("TrueAmAmFlingAura") then
                                                                                                                                                                                                                                            local bv = Instance.new("BodyVelocity")
                                                                                                                                                                                                                                            bv.Name = "TrueAmAmFlingAura"
                                                                                                                                                                                                                                            bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                                                                                                                                                                                                                                            local dir = (tRoot.Position - hrp.Position).Unit
                                                                                                                                                                                                                                            bv.Velocity = Vector3.new(dir.X, 0.5, dir.Z) * flingStrength2
                                                                                                                                                                                                                                            bv.Parent = tRoot
                                                                                                                                                                                                                                            Debris:AddItem(bv, 0.3)
                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        AuraL:CreateSlider({
                                                                                                                                                                                                            Name = "Fling Strength",
                                                                                                                                                                                                            Flag = "FlingAuraStrength2",
                                                                                                                                                                                                            Min = 100, Max = 2000, Default = 400,
                                                                                                                                                                                                            Callback = function(Value) flingStrength2 = Value end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- DEATH AURA (Auras tab version)
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local deathAura2Active = false
                                                                                                                                                                                                        local deathAura2Conn   = nil

                                                                                                                                                                                                        AuraL:CreateToggle({
                                                                                                                                                                                                            Name = "Death Aura",
                                                                                                                                                                                                            Flag = "DeathAura2",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                deathAura2Active = Value
                                                                                                                                                                                                                if deathAura2Conn then deathAura2Conn:Disconnect() deathAura2Conn = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                deathAura2Conn = R.Heartbeat:Connect(function()
                                                                                                                                                                                                                    if not deathAura2Active then return end
                                                                                                                                                                                                                    local char = LP.Character
                                                                                                                                                                                                                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not hrp then return end
                                                                                                                                                                                                                    for _, plr in ipairs(P:GetPlayers()) do
                                                                                                                                                                                                                        if plr ~= LP and plr.Character then
                                                                                                                                                                                                                            local tRoot = plr.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                            local tHead = plr.Character:FindFirstChild("Head")
                                                                                                                                                                                                                            local tHum = plr.Character:FindFirstChildOfClass("Humanoid")
                                                                                                                                                                                                                            if tRoot and tHead and tHum and tHum.Health > 0 then
                                                                                                                                                                                                                                if (tRoot.Position - hrp.Position).Magnitude <= 25 then
                                                                                                                                                                                                                                    pcall(function()
                                                                                                                                                                                                                                        if _G.SetNetOwner_Def then _G.SetNetOwner_Def:FireServer(tRoot, tRoot.CFrame) end
                                                                                                                                                                                                                                        if _G.DestroyGrabLine_Def then _G.DestroyGrabLine_Def:FireServer(tRoot) end
                                                                                                                                                                                                                                        if tHead:FindFirstChild("PartOwner") and tHead.PartOwner.Value == LP.Name then
                                                                                                                                                                                                                                            for _, part in pairs(tHum.Parent:GetChildren()) do
                                                                                                                                                                                                                                                if part:IsA("BasePart") then
                                                                                                                                                                                                                                                    part.CFrame = CFrame.new(-1e9, 1e9, -1e9)
                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                            local bv = Instance.new("BodyVelocity")
                                                                                                                                                                                                                                            bv.Velocity = Vector3.new(0, -1e7, 0)
                                                                                                                                                                                                                                            bv.MaxForce = Vector3.new(9e9, 9e9, 9e9)
                                                                                                                                                                                                                                            bv.P = 1e7
                                                                                                                                                                                                                                            bv.Parent = tRoot
                                                                                                                                                                                                                                            tHum.Sit = false
                                                                                                                                                                                                                                            tHum.BreakJointsOnDeath = false
                                                                                                                                                                                                                                            tHum:ChangeState(Enum.HumanoidStateType.Dead)
                                                                                                                                                                                                                                            task.delay(2, function()
                                                                                                                                                                                                                                                if bv and bv.Parent then bv:Destroy() end
                                                                                                                                                                                                                                            end)
                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- KICK AURA (1 HAND)
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local kickAura1Active = false
                                                                                                                                                                                                        local kickAura1Conn   = nil
                                                                                                                                                                                                        local kickAura1Radius = 20
                                                                                                                                                                                                        local kickAura1Whitelist = true

                                                                                                                                                                                                        AuraL:CreateToggle({
                                                                                                                                                                                                            Name = "Kick Aura (1 Hand)",
                                                                                                                                                                                                            Flag = "KickAura1",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                kickAura1Active = Value
                                                                                                                                                                                                                if kickAura1Conn then kickAura1Conn:Disconnect() kickAura1Conn = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                kickAura1Conn = R.Heartbeat:Connect(function()
                                                                                                                                                                                                                    if not kickAura1Active then return end
                                                                                                                                                                                                                    local char = LP.Character
                                                                                                                                                                                                                    local hum = char and char:FindFirstChild("Humanoid")
                                                                                                                                                                                                                    local seat = hum and hum.SeatPart
                                                                                                                                                                                                                    local root = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not (seat and root) then return end
                                                                                                                                                                                                                    local blob = seat.Parent
                                                                                                                                                                                                                    if not blob or blob.Name ~= "CreatureBlobman" then return end
                                                                                                                                                                                                                    local scriptObj = blob:FindFirstChild("BlobmanSeatAndOwnerScript")
                                                                                                                                                                                                                    local CG = scriptObj and scriptObj:FindFirstChild("CreatureGrab")
                                                                                                                                                                                                                    local CD = scriptObj and scriptObj:FindFirstChild("CreatureDrop")
                                                                                                                                                                                                                    local R_Det = blob:FindFirstChild("RightDetector")
                                                                                                                                                                                                                    local R_Weld = R_Det and (R_Det:FindFirstChild("RightWeld") or R_Det:FindFirstChildWhichIsA("Weld"))
                                                                                                                                                                                                                    if not (CG and CD and R_Det and R_Weld) then return end
                                                                                                                                                                                                                    for _, plr in ipairs(P:GetPlayers()) do
                                                                                                                                                                                                                        if plr ~= LP and plr.Character then
                                                                                                                                                                                                                            if kickAura1Whitelist and IsFriend(plr) then continue end
                                                                                                                                                                                                                            local tRoot = plr.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                            local tHum = plr.Character:FindFirstChild("Humanoid")
                                                                                                                                                                                                                            if tRoot and tHum and tHum.Health > 0 then
                                                                                                                                                                                                                                if (tRoot.Position - root.Position).Magnitude <= kickAura1Radius then
                                                                                                                                                                                                                                    pcall(function()
                                                                                                                                                                                                                                        CD:FireServer(R_Weld)
                                                                                                                                                                                                                                        CG:FireServer(R_Det, tRoot, R_Weld)
                                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        AuraL:CreateSlider({
                                                                                                                                                                                                            Name = "Radius (1 Hand)",
                                                                                                                                                                                                            Flag = "KickAura1Radius",
                                                                                                                                                                                                            Min = 10, Max = 100, Default = 20,
                                                                                                                                                                                                            Callback = function(Value) kickAura1Radius = Value end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- KICK AURA (2 HANDS)
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local kickAura2Active = false
                                                                                                                                                                                                        local kickAura2Conn   = nil
                                                                                                                                                                                                        local kickAura2Radius = 20
                                                                                                                                                                                                        local kickAura2Whitelist = true

                                                                                                                                                                                                        AuraL:CreateToggle({
                                                                                                                                                                                                            Name = "Kick Aura (2 Hands)",
                                                                                                                                                                                                            Flag = "KickAura2",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                kickAura2Active = Value
                                                                                                                                                                                                                if kickAura2Conn then kickAura2Conn:Disconnect() kickAura2Conn = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                local tickLimiter = 0
                                                                                                                                                                                                                kickAura2Conn = R.Heartbeat:Connect(function()
                                                                                                                                                                                                                    if not kickAura2Active then return end
                                                                                                                                                                                                                    if tick() - tickLimiter < 0.12 then return end
                                                                                                                                                                                                                    tickLimiter = tick()
                                                                                                                                                                                                                    local char = LP.Character
                                                                                                                                                                                                                    local hum = char and char:FindFirstChild("Humanoid")
                                                                                                                                                                                                                    local seat = hum and hum.SeatPart
                                                                                                                                                                                                                    local root = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not (seat and root) then return end
                                                                                                                                                                                                                    local blob = seat.Parent
                                                                                                                                                                                                                    if not blob or blob.Name ~= "CreatureBlobman" then return end
                                                                                                                                                                                                                    local scriptObj = blob:FindFirstChild("BlobmanSeatAndOwnerScript")
                                                                                                                                                                                                                    local CG = scriptObj and scriptObj:FindFirstChild("CreatureGrab")
                                                                                                                                                                                                                    local CD = scriptObj and scriptObj:FindFirstChild("CreatureDrop")
                                                                                                                                                                                                                    local L_Det = blob:FindFirstChild("LeftDetector")
                                                                                                                                                                                                                    local R_Det = blob:FindFirstChild("RightDetector")
                                                                                                                                                                                                                    local L_Weld = L_Det and (L_Det:FindFirstChild("LeftWeld") or L_Det:FindFirstChildWhichIsA("Weld"))
                                                                                                                                                                                                                    local R_Weld = R_Det and (R_Det:FindFirstChild("RightWeld") or R_Det:FindFirstChildWhichIsA("Weld"))
                                                                                                                                                                                                                    if not (CG and CD and L_Weld and R_Weld) then return end
                                                                                                                                                                                                                    for _, plr in ipairs(P:GetPlayers()) do
                                                                                                                                                                                                                        if plr ~= LP and plr.Character then
                                                                                                                                                                                                                            if kickAura2Whitelist and IsFriend(plr) then continue end
                                                                                                                                                                                                                            local tRoot = plr.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                            local tHum = plr.Character:FindFirstChild("Humanoid")
                                                                                                                                                                                                                            if tRoot and tHum and tHum.Health > 0 then
                                                                                                                                                                                                                                if (tRoot.Position - root.Position).Magnitude <= kickAura2Radius then
                                                                                                                                                                                                                                    pcall(function()
                                                                                                                                                                                                                                        CG:FireServer(L_Det, tRoot, L_Weld)
                                                                                                                                                                                                                                        task.wait(0.04)
                                                                                                                                                                                                                                        CD:FireServer(L_Weld, tRoot)
                                                                                                                                                                                                                                        CG:FireServer(R_Det, tRoot, R_Weld)
                                                                                                                                                                                                                                        task.wait(0.04)
                                                                                                                                                                                                                                        CD:FireServer(R_Weld, tRoot)
                                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        AuraL:CreateSlider({
                                                                                                                                                                                                            Name = "Radius (2 Hands)",
                                                                                                                                                                                                            Flag = "KickAura2Radius",
                                                                                                                                                                                                            Min = 10, Max = 100, Default = 20,
                                                                                                                                                                                                            Callback = function(Value) kickAura2Radius = Value end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- DUAL HAND KICK AURA (из Ragalic)
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local dualKickAuraEnabled = false
                                                                                                                                                                                                        local dualKickAuraRadius = 20
                                                                                                                                                                                                        local dualKickAuraWhitelist = true
                                                                                                                                                                                                        local dualKickAuraConn

                                                                                                                                                                                                        AuraL:CreateDropdown({
                                                                                                                                                                                                            Name = "Dual Kick Aura Radius",
                                                                                                                                                                                                            Flag = "DualKickAuraRadius",
                                                                                                                                                                                                            Items = {"10","20","30","40","50","100","250","500","1000","5000","10000"},
                                                                                                                                                                                                            Default = "20",
                                                                                                                                                                                                            Callback = function(v) dualKickAuraRadius = tonumber(v) end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        AuraL:CreateToggle({
                                                                                                                                                                                                            Name = "Dual Hand Kick Aura",
                                                                                                                                                                                                            Flag = "DualHandKickAura",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(on)
                                                                                                                                                                                                                dualKickAuraEnabled = on
                                                                                                                                                                                                                if dualKickAuraConn then dualKickAuraConn:Disconnect() dualKickAuraConn = nil end
                                                                                                                                                                                                                if not on then return end
                                                                                                                                                                                                                local tickLimiter = 0
                                                                                                                                                                                                                dualKickAuraConn = R.Heartbeat:Connect(function()
                                                                                                                                                                                                                    if tick() - tickLimiter < 0.12 then return end
                                                                                                                                                                                                                    tickLimiter = tick()
                                                                                                                                                                                                                    local myChar = LP.Character
                                                                                                                                                                                                                    local hum = myChar and myChar:FindFirstChildOfClass("Humanoid")
                                                                                                                                                                                                                    local seat = hum and hum.SeatPart
                                                                                                                                                                                                                    local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not (seat and myRoot) then return end
                                                                                                                                                                                                                    local seatParent = seat.Parent
                                                                                                                                                                                                                    local scriptFolder = seatParent and seatParent:FindFirstChild("BlobmanSeatAndOwnerScript")
                                                                                                                                                                                                                    local grab = scriptFolder and scriptFolder:FindFirstChild("CreatureGrab")
                                                                                                                                                                                                                    local drop = scriptFolder and scriptFolder:FindFirstChild("CreatureDrop")
                                                                                                                                                                                                                    local leftDet = seatParent:FindFirstChild("LeftDetector")
                                                                                                                                                                                                                    local rightDet = seatParent:FindFirstChild("RightDetector")
                                                                                                                                                                                                                    local leftWeld = leftDet and leftDet:FindFirstChild("LeftWeld")
                                                                                                                                                                                                                    local rightWeld = rightDet and rightDet:FindFirstChild("RightWeld")
                                                                                                                                                                                                                    if not (grab and drop and leftDet and rightDet and leftWeld and rightWeld) then return end
                                                                                                                                                                                                                    for _, plr in ipairs(P:GetPlayers()) do
                                                                                                                                                                                                                        if plr ~= LP and plr.Character and (not dualKickAuraWhitelist or not IsFriend(plr)) then
                                                                                                                                                                                                                            local char = plr.Character
                                                                                                                                                                                                                            local hrp = char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                            local hum2 = char:FindFirstChildOfClass("Humanoid")
                                                                                                                                                                                                                            if hrp and hum2 and hum2.Health > 0 then
                                                                                                                                                                                                                                local dist = (hrp.Position - myRoot.Position).Magnitude
                                                                                                                                                                                                                                if dist <= dualKickAuraRadius then
                                                                                                                                                                                                                                    pcall(function()
                                                                                                                                                                                                                                        grab:FireServer(leftDet, hrp, leftWeld)
                                                                                                                                                                                                                                        task.wait(0.04)
                                                                                                                                                                                                                                        drop:FireServer(leftWeld, hrp)
                                                                                                                                                                                                                                        grab:FireServer(rightDet, hrp, rightWeld)
                                                                                                                                                                                                                                        task.wait(0.04)
                                                                                                                                                                                                                                        drop:FireServer(rightWeld, hrp)
                                                                                                                                                                                                                                        grab:FireServer(leftDet, hrp, leftWeld)
                                                                                                                                                                                                                                        grab:FireServer(rightDet, hrp, rightWeld)
                                                                                                                                                                                                                                        task.wait(0.03)
                                                                                                                                                                                                                                        drop:FireServer(leftWeld, hrp)
                                                                                                                                                                                                                                        drop:FireServer(rightWeld, hrp)
                                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- REMOVE ANTI KICK AURA
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local removeAntiKickAuraActive = false
                                                                                                                                                                                                        local removeAntiKickRadius     = 15
                                                                                                                                                                                                        local useWhitelistRemoveAntiKick = true
                                                                                                                                                                                                        local removeAntiKickAuraConn = nil

                                                                                                                                                                                                        AuraR:CreateToggle({
                                                                                                                                                                                                            Name = "Remove Anti Kick Aura",
                                                                                                                                                                                                            Flag = "RemoveAntiKickAura",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                removeAntiKickAuraActive = Value
                                                                                                                                                                                                                if removeAntiKickAuraConn then removeAntiKickAuraConn:Disconnect() removeAntiKickAuraConn = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                removeAntiKickAuraConn = R.Heartbeat:Connect(function()
                                                                                                                                                                                                                    if not removeAntiKickAuraActive then return end
                                                                                                                                                                                                                    local char = LP.Character
                                                                                                                                                                                                                    local myRoot = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not myRoot then return end
                                                                                                                                                                                                                    for _, target in ipairs(P:GetPlayers()) do
                                                                                                                                                                                                                        if target ~= LP then
                                                                                                                                                                                                                            if useWhitelistRemoveAntiKick and IsFriend(target) then continue end
                                                                                                                                                                                                                            local tChar = target.Character
                                                                                                                                                                                                                            local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                            if not tRoot then continue end
                                                                                                                                                                                                                            if (tRoot.Position - myRoot.Position).Magnitude <= removeAntiKickRadius then
                                                                                                                                                                                                                                local spawned = workspace:FindFirstChild(target.Name .. "SpawnedInToys")
                                                                                                                                                                                                                                if spawned then
                                                                                                                                                                                                                                    for _, toyName in ipairs({"NinjaKunai", "NinjaShuriken", "AntiKick", "ToolPencil"}) do
                                                                                                                                                                                                                                        local toy = spawned:FindFirstChild(toyName)
                                                                                                                                                                                                                                        if toy then
                                                                                                                                                                                                                                            local part = toy:FindFirstChild("SoundPart") or toy:FindFirstChild("StickyPart")
                                                                                                                                                                                                                                            if part and _G.SetNetOwner_Def then
                                                                                                                                                                                                                                                pcall(function() _G.SetNetOwner_Def:FireServer(part, part.CFrame) end)
                                                                                                                                                                                                                                                if part:FindFirstChild("PartOwner") and part.PartOwner.Value == LP.Name then
                                                                                                                                                                                                                                                    part.CFrame = CFrame.new(0, 1000, 0)
                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        AuraR:CreateSlider({
