                                                                                                                                                                                                        local function UpdateAvatar(plr)
                                                                                                                                                                                                            local frame = _G.TrueAmAm_TargetAvatarFrame
                                                                                                                                                                                                            local img = _G.TrueAmAm_TargetAvatarImg
                                                                                                                                                                                                            if not frame or not img then return end
                                                                                                                                                                                                            if not plr then frame.Visible = false img.Image = "" return end
                                                                                                                                                                                                            local ok, url = pcall(function()
                                                                                                                                                                                                                return P:GetUserThumbnailAsync(plr.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size420x420)
                                                                                                                                                                                                            end)
                                                                                                                                                                                                            if ok and url then img.Image = url frame.Visible = true
                                                                                                                                                                                                            else frame.Visible = false end
                                                                                                                                                                                                        end

