                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- POWER KICK
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local powerKickActive = false
                                                                                                                                                                                                        local powerKickTask   = nil

                                                                                                                                                                                                        TargetKick:CreateToggle({
                                                                                                                                                                                                            Name = "Power Kick",
                                                                                                                                                                                                            Flag = "PowerKick",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                powerKickActive = Value
                                                                                                                                                                                                                if powerKickTask then task.cancel(powerKickTask) powerKickTask = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                powerKickTask = task.spawn(function()
                                                                                                                                                                                                                    local GE = RS:WaitForChild("GrabEvents")
                                                                                                                                                                                                                    local myChar = LP.Character
                                                                                                                                                                                                                    local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not myRoot then return end
                                                                                                                                                                                                                    local savedPos = myRoot.CFrame
                                                                                                                                                                                                                    local dragging = false
                                                                                                                                                                                                                    local grabStart = 0
                                                                                                                                                                                                                    while powerKickActive do
                                                                                                                                                                                                                        local target = GetTargetPlayer()
                                                                                                                                                                                                                        if not target or not target.Character then task.wait(0.1) continue end
                                                                                                                                                                                                                        myChar = LP.Character
                                                                                                                                                                                                                        myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        if not myRoot then break end
                                                                                                                                                                                                                        local tChar = target.Character
                                                                                                                                                                                                                        local tRoot = tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        local tHum = tChar:FindFirstChild("Humanoid")
                                                                                                                                                                                                                        if tRoot and tHum and tHum.Health > 0 then
                                                                                                                                                                                                                            tRoot.AssemblyLinearVelocity = Vector3.zero
                                                                                                                                                                                                                            tRoot.AssemblyAngularVelocity = Vector3.zero
                                                                                                                                                                                                                            if not dragging then
                                                                                                                                                                                                                                myRoot.CFrame = tRoot.CFrame
                                                                                                                                                                                                                                myRoot.AssemblyLinearVelocity = Vector3.zero
                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                    tHum.PlatformStand = true
                                                                                                                                                                                                                                    tHum.Sit = true
                                                                                                                                                                                                                                    GE.SetNetworkOwner:FireServer(tRoot, myRoot.CFrame)
                                                                                                                                                                                                                                    GE.CreateGrabLine:FireServer(tRoot, Vector3.zero, tRoot.Position, false)
                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                if grabStart == 0 then grabStart = tick() end
                                                                                                                                                                                                                                if tick() - grabStart > 0.35 then
                                                                                                                                                                                                                                    dragging = true
                                                                                                                                                                                                                                    grabStart = 0
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            else
                                                                                                                                                                                                                                myRoot.CFrame = savedPos
                                                                                                                                                                                                                                myRoot.AssemblyLinearVelocity = Vector3.zero
                                                                                                                                                                                                                                local lockPos = savedPos * CFrame.new(0, 17, 0)
                                                                                                                                                                                                                                tRoot.CFrame = lockPos
                                                                                                                                                                                                                                tRoot.AssemblyLinearVelocity = Vector3.zero
                                                                                                                                                                                                                                tRoot.AssemblyAngularVelocity = Vector3.zero
                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                    tHum.PlatformStand = true
                                                                                                                                                                                                                                    tHum.Sit = false
                                                                                                                                                                                                                                    GE.SetNetworkOwner:FireServer(tRoot, lockPos)
                                                                                                                                                                                                                                    GE.DestroyGrabLine:FireServer(tRoot)
                                                                                                                                                                                                                                    GE.CreateGrabLine:FireServer(tRoot, Vector3.zero, tRoot.Position, false)
                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        else
                                                                                                                                                                                                                            dragging = false
                                                                                                                                                                                                                            grabStart = 0
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        R.Heartbeat:Wait()
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    if myRoot then
                                                                                                                                                                                                                        myRoot.CFrame = savedPos
                                                                                                                                                                                                                        myRoot.AssemblyLinearVelocity = Vector3.zero
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- OWNERSHIP KICK
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local ownKickActive = false
                                                                                                                                                                                                        local ownKickTask   = nil

                                                                                                                                                                                                        TargetKick:CreateToggle({
                                                                                                                                                                                                            Name = "Ownership Kick",
                                                                                                                                                                                                            Flag = "OwnershipKick",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                ownKickActive = Value
                                                                                                                                                                                                                if ownKickTask then task.cancel(ownKickTask) ownKickTask = nil end
                                                                                                                                                                                                                if not Value then
                                                                                                                                                                                                                    local target = GetTargetPlayer()
                                                                                                                                                                                                                    if target and target.Character then
                                                                                                                                                                                                                        local tRoot = target.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        if tRoot then
                                                                                                                                                                                                                            for _, v in pairs(tRoot:GetChildren()) do
                                                                                                                                                                                                                                if v:IsA("BodyPosition") or v:IsA("BodyGyro") then
                                                                                                                                                                                                                                    pcall(function() v:Destroy() end)
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    return
                                                                                                                                                                                                                end
                                                                                                                                                                                                                ownKickTask = task.spawn(function()
                                                                                                                                                                                                                    local GE = RS:FindFirstChild("GrabEvents")
                                                                                                                                                                                                                    if not GE then return end
                                                                                                                                                                                                                    local myChar = LP.Character
                                                                                                                                                                                                                    local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not myRoot then return end
                                                                                                                                                                                                                    local savedPos = myRoot.CFrame
                                                                                                                                                                                                                    local dragging = false
                                                                                                                                                                                                                    local grabStartTime = 0
                                                                                                                                                                                                                    local checkStartTime = 0
                                                                                                                                                                                                                    local currentFPS = 60
                                                                                                                                                                                                                    local fpsConn = R.RenderStepped:Connect(function(dt) currentFPS = 1/dt end)
                                                                                                                                                                                                                    local bodyPos, bodyGyro
                                                                                                                                                                                                                    local function cleanupBodies()
                                                                                                                                                                                                                        if bodyPos then bodyPos:Destroy() bodyPos = nil end
                                                                                                                                                                                                                        if bodyGyro then bodyGyro:Destroy() bodyGyro = nil end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    local function createBodies(tRoot, pos)
                                                                                                                                                                                                                        cleanupBodies()
                                                                                                                                                                                                                        for _, v in pairs(tRoot:GetChildren()) do
                                                                                                                                                                                                                            if v:IsA("BodyPosition") or v:IsA("BodyGyro") then v:Destroy() end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        bodyPos = Instance.new("BodyPosition")
                                                                                                                                                                                                                        bodyPos.MaxForce = Vector3.new(9e9, 9e9, 9e9)
                                                                                                                                                                                                                        bodyPos.D = 100
                                                                                                                                                                                                                        bodyPos.Position = pos
                                                                                                                                                                                                                        bodyPos.Parent = tRoot
                                                                                                                                                                                                                        bodyGyro = Instance.new("BodyGyro")
                                                                                                                                                                                                                        bodyGyro.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
                                                                                                                                                                                                                        bodyGyro.D = 100
                                                                                                                                                                                                                        bodyGyro.CFrame = CFrame.new(pos)
                                                                                                                                                                                                                        bodyGyro.Parent = tRoot
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    while ownKickActive do
                                                                                                                                                                                                                        local target = GetTargetPlayer()
                                                                                                                                                                                                                        if not target or not target.Parent then cleanupBodies() break end
                                                                                                                                                                                                                        myChar = LP.Character
                                                                                                                                                                                                                        myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        local tChar = target.Character
                                                                                                                                                                                                                        local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        local tHum = tChar and tChar:FindFirstChild("Humanoid")
                                                                                                                                                                                                                        if tRoot and tHum and tHum.Health > 0 and myRoot then
                                                                                                                                                                                                                            if not dragging then
                                                                                                                                                                                                                                myRoot.CFrame = tRoot.CFrame * CFrame.new(0, 0, 3)
                                                                                                                                                                                                                                cleanupBodies()
                                                                                                                                                                                                                                checkStartTime = 0
                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                    tHum.PlatformStand = true
                                                                                                                                                                                                                                    tHum.Sit = true
                                                                                                                                                                                                                                    GE.SetNetworkOwner:FireServer(tRoot, tRoot.CFrame)
                                                                                                                                                                                                                                    GE.SetNetworkOwner:FireServer(tRoot, tRoot.CFrame)
                                                                                                                                                                                                                                    GE.DestroyGrabLine:FireServer(tRoot)
                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                myRoot.AssemblyLinearVelocity = Vector3.zero
                                                                                                                                                                                                                                myRoot.AssemblyAngularVelocity = Vector3.zero
                                                                                                                                                                                                                                if grabStartTime == 0 then grabStartTime = tick() end
                                                                                                                                                                                                                                if tick() - grabStartTime > 0.35 then
                                                                                                                                                                                                                                    dragging = true
                                                                                                                                                                                                                                    grabStartTime = 0
                                                                                                                                                                                                                                    checkStartTime = tick()
                                                                                                                                                                                                                                    local lockPos = savedPos * CFrame.new(5, 20, 4)
                                                                                                                                                                                                                                    createBodies(tRoot, lockPos.Position)
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            else
                                                                                                                                                                                                                                myRoot.CFrame = savedPos
                                                                                                                                                                                                                                local lockPos = savedPos * CFrame.new(5, 20, 4)
                                                                                                                                                                                                                                myRoot.AssemblyLinearVelocity = Vector3.zero
                                                                                                                                                                                                                                myRoot.AssemblyAngularVelocity = Vector3.zero
                                                                                                                                                                                                                                if bodyPos and bodyPos.Parent then
                                                                                                                                                                                                                                    bodyPos.Position = lockPos.Position
                                                                                                                                                                                                                                    if bodyGyro then bodyGyro.CFrame = lockPos end
                                                                                                                                                                                                                                else
                                                                                                                                                                                                                                    createBodies(tRoot, lockPos.Position)
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                tHum.PlatformStand = true
                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                    if currentFPS > 200 then
                                                                                                                                                                                                                                        GE.SetNetworkOwner:FireServer(tRoot, lockPos)
                                                                                                                                                                                                                                        GE.SetNetworkOwner:FireServer(tRoot, lockPos)
                                                                                                                                                                                                                                        GE.DestroyGrabLine:FireServer(tRoot)
                                                                                                                                                                                                                                    elseif currentFPS >= 155 then
                                                                                                                                                                                                                                        GE.SetNetworkOwner:FireServer(tRoot, lockPos)
                                                                                                                                                                                                                                        GE.SetNetworkOwner:FireServer(tRoot, lockPos)
                                                                                                                                                                                                                                        GE.SetNetworkOwner:FireServer(tRoot, lockPos)
                                                                                                                                                                                                                                        GE.DestroyGrabLine:FireServer(tRoot)
                                                                                                                                                                                                                                    else
                                                                                                                                                                                                                                        for _ = 1, 4 do GE.SetNetworkOwner:FireServer(tRoot, lockPos) end
                                                                                                                                                                                                                                        GE.DestroyGrabLine:FireServer(tRoot)
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                if checkStartTime > 0 and tick() - checkStartTime > 0.30 then
                                                                                                                                                                                                                                    local dist = (tRoot.Position - lockPos.Position).Magnitude
                                                                                                                                                                                                                                    if dist > 10 then
                                                                                                                                                                                                                                        dragging = false
                                                                                                                                                                                                                                        grabStartTime = 0
                                                                                                                                                                                                                                        checkStartTime = 0
                                                                                                                                                                                                                                        cleanupBodies()
                                                                                                                                                                                                                                        myRoot.CFrame = tRoot.CFrame * CFrame.new(0, 0, 3)
                                                                                                                                                                                                                                    else
                                                                                                                                                                                                                                        checkStartTime = tick()
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        else
                                                                                                                                                                                                                            dragging = false
                                                                                                                                                                                                                            grabStartTime = 0
                                                                                                                                                                                                                            checkStartTime = 0
                                                                                                                                                                                                                            cleanupBodies()
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        R.Heartbeat:Wait()
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    fpsConn:Disconnect()
                                                                                                                                                                                                                    cleanupBodies()
                                                                                                                                                                                                                    if myRoot then myRoot.CFrame = savedPos end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- LOOP KILL
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local loopKillActive = false
                                                                                                                                                                                                        local loopKillTask   = nil

                                                                                                                                                                                                        TargetKick:CreateToggle({
                                                                                                                                                                                                            Name = "Loop Kill",
                                                                                                                                                                                                            Flag = "LoopKill",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                loopKillActive = Value
                                                                                                                                                                                                                if loopKillTask then task.cancel(loopKillTask) loopKillTask = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                loopKillTask = task.spawn(function()
                                                                                                                                                                                                                    local GE = RS:WaitForChild("GrabEvents")
                                                                                                                                                                                                                    while loopKillActive do
                                                                                                                                                                                                                        local target = GetTargetPlayer()
                                                                                                                                                                                                                        if not target or not target.Character then task.wait(0.5) continue end
                                                                                                                                                                                                                        local myChar = LP.Character
                                                                                                                                                                                                                        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        local tChar = target.Character
                                                                                                                                                                                                                        local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        local tHum = tChar and tChar:FindFirstChild("Humanoid")
                                                                                                                                                                                                                        if tRoot and tHum and tHum.Health > 0 and myRoot then
                                                                                                                                                                                                                            local currentPos = myRoot.CFrame
                                                                                                                                                                                                                            local start = tick()
                                                                                                                                                                                                                            while tick() - start < 0.35 and loopKillActive do
                                                                                                                                                                                                                                if not tRoot.Parent then break end
                                                                                                                                                                                                                                myRoot.CFrame = tRoot.CFrame * CFrame.new(0, 0, 2)
                                                                                                                                                                                                                                myRoot.AssemblyLinearVelocity = Vector3.zero
                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                    GE.SetNetworkOwner:FireServer(tRoot, myRoot.CFrame)
                                                                                                                                                                                                                                    tHum:ChangeState(Enum.HumanoidStateType.Dead)
                                                                                                                                                                                                                                    tHum.Health = 0
                                                                                                                                                                                                                                    GE.CreateGrabLine:FireServer(tRoot, Vector3.zero, tRoot.Position, false)
                                                                                                                                                                                                                                    GE.DestroyGrabLine:FireServer(tRoot)
                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                R.Heartbeat:Wait()
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                            if myRoot then
                                                                                                                                                                                                                                myRoot.CFrame = currentPos
                                                                                                                                                                                                                                myRoot.AssemblyLinearVelocity = Vector3.zero
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                            task.wait(1.2)
                                                                                                                                                                                                                        else
                                                                                                                                                                                                                            task.wait(0.5)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- PALLET RAGDOLL
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local palletRagdollActive = false
                                                                                                                                                                                                        local palletRagdollTask   = nil

                                                                                                                                                                                                        TargetKick:CreateToggle({
                                                                                                                                                                                                            Name = "Pallet Ragdoll",
                                                                                                                                                                                                            Flag = "PalletRagdoll",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                palletRagdollActive = Value
                                                                                                                                                                                                                if palletRagdollTask then task.cancel(palletRagdollTask) palletRagdollTask = nil end
                                                                                                                                                                                                                if not Value then
                                                                                                                                                                                                                    task.spawn(function()
                                                                                                                                                                                                                        local folder = workspace:FindFirstChild(LP.Name.."SpawnedInToys")
                                                                                                                                                                                                                        local pallet = folder and folder:FindFirstChild("PalletLightBrown")
                                                                                                                                                                                                                        if pallet then
                                                                                                                                                                                                                            pcall(function() if _G.DestroyToy_Def then _G.DestroyToy_Def:FireServer(pallet) end end)
                                                                                                                                                                                                                            if pallet.Parent then pallet:Destroy() end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                    return
                                                                                                                                                                                                                end
                                                                                                                                                                                                                palletRagdollTask = task.spawn(function()
                                                                                                                                                                                                                    local skyPos = CFrame.new(0, 800000, 0)
                                                                                                                                                                                                                    if _G.SpawnToy_Def then
                                                                                                                                                                                                                        pcall(function() _G.SpawnToy_Def:InvokeServer("PalletLightBrown", skyPos, Vector3.zero) end)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    local pallet
                                                                                                                                                                                                                    local t0 = tick()
                                                                                                                                                                                                                    repeat
                                                                                                                                                                                                                        pallet = workspace:FindFirstChild(LP.Name.."SpawnedInToys")
                                                                                                                                                                                                                            and workspace[LP.Name.."SpawnedInToys"]:FindFirstChild("PalletLightBrown")
                                                                                                                                                                                                                        R.Heartbeat:Wait()
                                                                                                                                                                                                                    until pallet or tick() - t0 > 3 or not palletRagdollActive
                                                                                                                                                                                                                    if not pallet then return end
                                                                                                                                                                                                                    local mainPart = pallet:FindFirstChild("SoundPart")
                                                                                                                                                                                                                    if not mainPart then return end
                                                                                                                                                                                                                    mainPart.CanCollide = false
                                                                                                                                                                                                                    mainPart.Anchored = false
                                                                                                                                                                                                                    local function claim(part)
                                                                                                                                                                                                                        if _G.SetNetOwner_Def then _G.SetNetOwner_Def:FireServer(part, part.CFrame) end
                                                                                                                                                                                                                        if _G.CreateGrabLine_Def then _G.CreateGrabLine_Def:FireServer(part, Vector3.zero, part.Position, false) end
                                                                                                                                                                                                                        if _G.DestroyGrabLine_Def then _G.DestroyGrabLine_Def:FireServer(part) end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    claim(mainPart)
                                                                                                                                                                                                                    while palletRagdollActive do
                                                                                                                                                                                                                        for _ = 1, 20 do R.Heartbeat:Wait() end
                                                                                                                                                                                                                        local target = GetTargetPlayer()
                                                                                                                                                                                                                        if not target or not target.Character then break end
                                                                                                                                                                                                                        local head = target.Character:FindFirstChild("Head")
                                                                                                                                                                                                                        if not head then continue end
                                                                                                                                                                                                                        local targetPos = head.Position
                                                                                                                                                                                                                        mainPart.CFrame = CFrame.new(targetPos.X, targetPos.Y + 0.2, targetPos.Z)
                                                                                                                                                                                                                        mainPart.AssemblyLinearVelocity = Vector3.zero
                                                                                                                                                                                                                        mainPart.AssemblyAngularVelocity = Vector3.new(1000, 1000, 1000)
                                                                                                                                                                                                                        claim(mainPart)
                                                                                                                                                                                                                        mainPart.CanCollide = true
                                                                                                                                                                                                                        for _ = 1, 3 do R.Heartbeat:Wait() end
                                                                                                                                                                                                                        mainPart.CanCollide = false
                                                                                                                                                                                                                        mainPart.CFrame = skyPos
                                                                                                                                                                                                                        mainPart.AssemblyAngularVelocity = Vector3.zero
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    if pallet then
                                                                                                                                                                                                                        pcall(function() if _G.DestroyToy_Def then _G.DestroyToy_Def:FireServer(pallet) end end)
                                                                                                                                                                                                                        if pallet.Parent then pallet:Destroy() end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- SNOWBALL RAGDOLL
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local snowballRagdollActive = false
                                                                                                                                                                                                        local snowballRagdollTask = nil

                                                                                                                                                                                                        TargetKick:CreateToggle({
                                                                                                                                                                                                            Name = "Snowball Ragdoll",
                                                                                                                                                                                                            Flag = "SnowballRagdoll",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                snowballRagdollActive = Value
                                                                                                                                                                                                                if snowballRagdollTask then task.cancel(snowballRagdollTask) snowballRagdollTask = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                snowballRagdollTask = task.spawn(function()
                                                                                                                                                                                                                    local SpawnRemote = RS:WaitForChild("MenuToys"):WaitForChild("SpawnToyRemoteFunction")
                                                                                                                                                                                                                    while snowballRagdollActive do
                                                                                                                                                                                                                        local target = GetTargetPlayer()
                                                                                                                                                                                                                        if not target or not target.Character then task.wait(0.5) continue end
                                                                                                                                                                                                                        local tChar = target.Character
                                                                                                                                                                                                                        local torso = tChar:FindFirstChild("UpperTorso") or tChar:FindFirstChild("Torso")
                                                                                                                                                                                                                        if not torso then task.wait(0.2) continue end
                                                                                                                                                                                                                        pcall(function()
                                                                                                                                                                                                                            local offset = Vector3.new(math.random(-30,30)/100, math.random(-30,30)/100, math.random(-30,30)/100)
                                                                                                                                                                                                                            SpawnRemote:InvokeServer("BallSnowball", torso.CFrame * CFrame.new(offset), Vector3.zero)
                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                        local folder = workspace:FindFirstChild(LP.Name .. "SpawnedInToys")
                                                                                                                                                                                                                        if folder then
                                                                                                                                                                                                                            for _, snowball in pairs(folder:GetChildren()) do
                                                                                                                                                                                                                                if snowball.Name == "BallSnowball" and snowball.Parent then
                                                                                                                                                                                                                                    local part = snowball.PrimaryPart or snowball:FindFirstChildWhichIsA("BasePart")
                                                                                                                                                                                                                                    if part then
                                                                                                                                                                                                                                        local offset = Vector3.new(math.random(-30,30)/100, math.random(-30,30)/100, math.random(-30,30)/100)
                                                                                                                                                                                                                                        part.CFrame = torso.CFrame * CFrame.new(offset)
                                                                                                                                                                                                                                        part.AssemblyLinearVelocity = Vector3.zero
                                                                                                                                                                                                                                        part.AssemblyAngularVelocity = Vector3.zero
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        R.Heartbeat:Wait()
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- REMOVE ANTI KICK (Target)
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local removeAntiKickActive = false
                                                                                                                                                                                                        local removeAntiKickTask   = nil

                                                                                                                                                                                                        TargetKick:CreateToggle({
                                                                                                                                                                                                            Name = "Remove Anti Kick (Target)",
                                                                                                                                                                                                            Flag = "RemoveAntiKick",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                removeAntiKickActive = Value
                                                                                                                                                                                                                if removeAntiKickTask then task.cancel(removeAntiKickTask) removeAntiKickTask = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                removeAntiKickTask = task.spawn(function()
                                                                                                                                                                                                                    while removeAntiKickActive do
                                                                                                                                                                                                                        local target = GetTargetPlayer()
                                                                                                                                                                                                                        if target then
                                                                                                                                                                                                                            local spawned = workspace:FindFirstChild(target.Name .. "SpawnedInToys")
                                                                                                                                                                                                                            if spawned then
                                                                                                                                                                                                                                for _, toyName in ipairs({"NinjaKunai", "NinjaShuriken", "AntiKick", "ToolCleaver", "ToolPencil", "ToolPickaxe"}) do
                                                                                                                                                                                                                                    local toy = spawned:FindFirstChild(toyName)
                                                                                                                                                                                                                                    if toy then
                                                                                                                                                                                                                                        local part = toy:FindFirstChild("SoundPart") or toy:FindFirstChild("StickyPart")
                                                                                                                                                                                                                                        if part and _G.SetNetOwner_Def then
                                                                                                                                                                                                                                            pcall(function()
                                                                                                                                                                                                                                                _G.SetNetOwner_Def:FireServer(part, part.CFrame)
                                                                                                                                                                                                                                                if part:FindFirstChild("PartOwner") and part.PartOwner.Value == LP.Name then
                                                                                                                                                                                                                                                    part.CFrame = CFrame.new(0, 1000, 0)
                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                            end)
                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        task.wait(0.1)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- FLING TARGET
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local flingTargetActive = false
                                                                                                                                                                                                        local flingTargetTask   = nil

                                                                                                                                                                                                        TargetKick:CreateToggle({
                                                                                                                                                                                                            Name = "Fling Target",
                                                                                                                                                                                                            Flag = "FlingTarget",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                flingTargetActive = Value
                                                                                                                                                                                                                if flingTargetTask then task.cancel(flingTargetTask) flingTargetTask = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                flingTargetTask = task.spawn(function()
                                                                                                                                                                                                                    local myChar = LP.Character
                                                                                                                                                                                                                    local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not myRoot then return end
                                                                                                                                                                                                                    local savedPos = myRoot.CFrame
                                                                                                                                                                                                                    while flingTargetActive do
                                                                                                                                                                                                                        local target = GetTargetPlayer()
                                                                                                                                                                                                                        if not target or not target.Character then task.wait(0.5) continue end
                                                                                                                                                                                                                        local tRoot = target.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        local tHum = target.Character:FindFirstChild("Humanoid")
                                                                                                                                                                                                                        if tRoot and tHum and tHum.Health > 0 then
                                                                                                                                                                                                                            myRoot.CFrame = tRoot.CFrame
                                                                                                                                                                                                                            local bav = Instance.new("BodyAngularVelocity")
                                                                                                                                                                                                                            bav.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
                                                                                                                                                                                                                            bav.AngularVelocity = Vector3.new(0, 10000, 0)
                                                                                                                                                                                                                            bav.P = 10000
                                                                                                                                                                                                                            bav.Parent = myRoot
                                                                                                                                                                                                                            task.wait(1.5)
                                                                                                                                                                                                                            bav:Destroy()
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        task.wait(0.1)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    if myRoot then myRoot.CFrame = savedPos end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- METHOD SELECTOR
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local methodOptions = {"Bring", "Kick", "Loop Kick", "Bypass", "Blob Kill", "Blob + Grab", "Lock"}
                                                                                                                                                                                                        local selectedMethod = "Bring"

                                                                                                                                                                                                        TargetMeth:CreateDropdown({
                                                                                                                                                                                                            Name = "Select Method",
                                                                                                                                                                                                            Flag = "TargetMethod",
                                                                                                                                                                                                            Items = methodOptions,
                                                                                                                                                                                                            Default = "Bring",
                                                                                                                                                                                                            Callback = function(Value) selectedMethod = Value end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        local function BlobGet()
                                                                                                                                                                                                            local char = LP.Character
                                                                                                                                                                                                            local hum = char and char:FindFirstChild("Humanoid")
                                                                                                                                                                                                            if not hum then return nil end
                                                                                                                                                                                                            local seat = hum.SeatPart
                                                                                                                                                                                                            if not seat then return nil end
                                                                                                                                                                                                            local blob = seat.Parent
                                                                                                                                                                                                            if not blob or blob.Name ~= "CreatureBlobman" then return nil end
                                                                                                                                                                                                            return blob
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function BlobBring(target)
                                                                                                                                                                                                            if not target then return end
                                                                                                                                                                                                            local blob = BlobGet()
                                                                                                                                                                                                            if not blob then return end
                                                                                                                                                                                                            local char = LP.Character
                                                                                                                                                                                                            local hum = char:FindFirstChild("Humanoid")
                                                                                                                                                                                                            local root = char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            local tChar = target.Character
                                                                                                                                                                                                            local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            if not (tRoot and root) then return end
                                                                                                                                                                                                            local seat = hum.SeatPart
                                                                                                                                                                                                            local seatObj = seat and seat.Parent
                                                                                                                                                                                                            if not seatObj then return end
                                                                                                                                                                                                            local det = seatObj:FindFirstChild("LeftDetector")
                                                                                                                                                                                                            local weld = det and det:FindFirstChild("LeftWeld")
                                                                                                                                                                                                            local grab = seatObj.BlobmanSeatAndOwnerScript and seatObj.BlobmanSeatAndOwnerScript:FindFirstChild("CreatureGrab")
                                                                                                                                                                                                            if not (det and weld and grab) then return end
                                                                                                                                                                                                            local origCF = root.CFrame
                                                                                                                                                                                                            local origTr = {}
                                                                                                                                                                                                            for _, part in ipairs(char:GetDescendants()) do
                                                                                                                                                                                                                if part:IsA("BasePart") then
                                                                                                                                                                                                                    origTr[part] = part.Transparency
                                                                                                                                                                                                                    part.Transparency = 1
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                            root.CFrame = tRoot.CFrame * CFrame.new(0, 0, 2.5)
                                                                                                                                                                                                            task.wait(0.05)
                                                                                                                                                                                                            grab:FireServer(det, tRoot, weld)
                                                                                                                                                                                                            task.wait(0.1)
                                                                                                                                                                                                            grab:FireServer(det, tRoot, weld)
                                                                                                                                                                                                            task.delay(0.2, function()
                                                                                                                                                                                                                root.CFrame = origCF
                                                                                                                                                                                                                for part, tr in pairs(origTr) do
                                                                                                                                                                                                                    if part and part.Parent then part.Transparency = tr end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end)
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function BlobKickBasic(target)
                                                                                                                                                                                                            if not target then return end
                                                                                                                                                                                                            local blob = BlobGet()
                                                                                                                                                                                                            if not blob then return end
                                                                                                                                                                                                            local char = LP.Character
                                                                                                                                                                                                            local root = char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            local tChar = target.Character
                                                                                                                                                                                                            local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            if not (tRoot and root) then return end
                                                                                                                                                                                                            local det = blob:FindFirstChild("LeftDetector")
                                                                                                                                                                                                            local weld = det and det:FindFirstChild("LeftWeld")
                                                                                                                                                                                                            local scriptObj = blob:FindFirstChild("BlobmanSeatAndOwnerScript")
                                                                                                                                                                                                            local grab = scriptObj and scriptObj:FindFirstChild("CreatureGrab")
                                                                                                                                                                                                            local drop = scriptObj and scriptObj:FindFirstChild("CreatureDrop")
                                                                                                                                                                                                            if not (det and weld and grab and drop) then return end
                                                                                                                                                                                                            local origCF = root.CFrame
                                                                                                                                                                                                            root.CFrame = tRoot.CFrame * CFrame.new(0, 0, 3)
                                                                                                                                                                                                            task.wait(0.5)
                                                                                                                                                                                                            grab:FireServer(det, tRoot, weld)
                                                                                                                                                                                                            task.wait(0.7)
                                                                                                                                                                                                            drop:FireServer(weld, tRoot)
                                                                                                                                                                                                            task.wait(0.3)
                                                                                                                                                                                                            grab:FireServer(det, tRoot, weld)
                                                                                                                                                                                                            local bp = Instance.new("BodyPosition")
                                                                                                                                                                                                            bp.Position = Vector3.new(0, 999e5, 0)
                                                                                                                                                                                                            bp.MaxForce = Vector3.new(0, 99999e9, 0)
                                                                                                                                                                                                            bp.Parent = tRoot
                                                                                                                                                                                                            task.wait(0.6)
                                                                                                                                                                                                            grab:FireServer(det, tRoot, weld)
                                                                                                                                                                                                            bp:Destroy()
                                                                                                                                                                                                            root.CFrame = origCF
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local loopMethodActive = false

                                                                                                                                                                                                        local function BlobLoopKick(target)
                                                                                                                                                                                                            if not target then return end
                                                                                                                                                                                                            local blob = BlobGet()
                                                                                                                                                                                                            if not blob then return end
                                                                                                                                                                                                            local char = LP.Character
                                                                                                                                                                                                            local hum = char:FindFirstChild("Humanoid")
                                                                                                                                                                                                            local root = char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            local tChar = target.Character
                                                                                                                                                                                                            local tHum = tChar and tChar:FindFirstChild("Humanoid")
                                                                                                                                                                                                            local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            if not (tHum and tRoot and root and hum) then return end
                                                                                                                                                                                                            local scriptObj = blob:FindFirstChild("BlobmanSeatAndOwnerScript")
                                                                                                                                                                                                            local grab = scriptObj and scriptObj:FindFirstChild("CreatureGrab")
                                                                                                                                                                                                            local drop = scriptObj and scriptObj:FindFirstChild("CreatureDrop")
                                                                                                                                                                                                            local L_Det = blob:FindFirstChild("LeftDetector")
                                                                                                                                                                                                            local R_Det = blob:FindFirstChild("RightDetector")
                                                                                                                                                                                                            local L_Weld = L_Det and L_Det:FindFirstChild("LeftWeld")
                                                                                                                                                                                                            local R_Weld = R_Det and R_Det:FindFirstChild("RightWeld")
                                                                                                                                                                                                            if not (grab and drop and L_Weld and R_Weld) then return end
                                                                                                                                                                                                            local origCF = root.CFrame
                                                                                                                                                                                                            root.CFrame = tRoot.CFrame * CFrame.new(0, -5, 0)
                                                                                                                                                                                                            task.wait(0.1)
                                                                                                                                                                                                            grab:FireServer(L_Det, tRoot, L_Weld)
                                                                                                                                                                                                            task.wait(0.5)
                                                                                                                                                                                                            drop:FireServer(L_Weld, tRoot)
                                                                                                                                                                                                            task.wait(0.2)
                                                                                                                                                                                                            local bp = Instance.new("BodyPosition")
                                                                                                                                                                                                            bp.Position = Vector3.new(0, 999e6, 0)
                                                                                                                                                                                                            bp.MaxForce = Vector3.new(999e6, 999e6, 999e6)
                                                                                                                                                                                                            bp.Parent = tRoot
                                                                                                                                                                                                            grab:FireServer(L_Det, tRoot, L_Weld)
                                                                                                                                                                                                            task.wait(0.5)
                                                                                                                                                                                                            drop:FireServer(L_Weld, tRoot)
                                                                                                                                                                                                            task.wait(0.5)
                                                                                                                                                                                                            local startT = tick()
                                                                                                                                                                                                            while target and target.Parent and tHum.Health > 0 and (tick() - startT < 8) and loopMethodActive do
                                                                                                                                                                                                                grab:FireServer(L_Det, tRoot, L_Weld)
                                                                                                                                                                                                                task.wait()
                                                                                                                                                                                                                drop:FireServer(L_Weld, tRoot)
                                                                                                                                                                                                                task.wait()
                                                                                                                                                                                                                grab:FireServer(R_Det, tRoot, R_Weld)
                                                                                                                                                                                                                task.wait()
                                                                                                                                                                                                                drop:FireServer(R_Weld, tRoot)
                                                                                                                                                                                                                task.wait()
                                                                                                                                                                                                                grab:FireServer(L_Det, tRoot, L_Weld)
                                                                                                                                                                                                                grab:FireServer(R_Det, tRoot, R_Weld)
                                                                                                                                                                                                                task.wait()
                                                                                                                                                                                                                drop:FireServer(L_Weld, tRoot)
                                                                                                                                                                                                                drop:FireServer(R_Weld, tRoot)
                                                                                                                                                                                                                task.wait()
                                                                                                                                                                                                            end
                                                                                                                                                                                                            if bp then bp:Destroy() end
                                                                                                                                                                                                            root.CFrame = origCF
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function BlobBypass(target)
                                                                                                                                                                                                            if not target then return end
                                                                                                                                                                                                            local blob = BlobGet()
                                                                                                                                                                                                            if not blob then return end
                                                                                                                                                                                                            local char = LP.Character
                                                                                                                                                                                                            local hum = char:FindFirstChild("Humanoid")
                                                                                                                                                                                                            local root = char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            local tChar = target.Character
                                                                                                                                                                                                            local tHum = tChar and tChar:FindFirstChild("Humanoid")
                                                                                                                                                                                                            local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            if not (tHum and tRoot and root and hum) then return end
                                                                                                                                                                                                            local scriptObj = blob:FindFirstChild("BlobmanSeatAndOwnerScript")
                                                                                                                                                                                                            local grab = scriptObj and scriptObj:FindFirstChild("CreatureGrab")
                                                                                                                                                                                                            local drop = scriptObj and scriptObj:FindFirstChild("CreatureDrop")
                                                                                                                                                                                                            local L_Det = blob:FindFirstChild("LeftDetector")
                                                                                                                                                                                                            local L_Weld = L_Det and L_Det:FindFirstChild("LeftWeld")
                                                                                                                                                                                                            if not (grab and drop and L_Weld) then return end
                                                                                                                                                                                                            local startT = tick()
                                                                                                                                                                                                            while target and target.Parent and tHum.Health > 0 and (tick() - startT < 8) and loopMethodActive do
                                                                                                                                                                                                                for _ = 1, 20 do
                                                                                                                                                                                                                    grab:FireServer(L_Det, tRoot, L_Weld)
                                                                                                                                                                                                                end
                                                                                                                                                                                                                drop:FireServer(L_Weld, tRoot)
                                                                                                                                                                                                                drop:FireServer(L_Weld, tRoot)
                                                                                                                                                                                                                task.wait(0.01)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function BlobKill(target)
                                                                                                                                                                                                            if not target then return end
                                                                                                                                                                                                            local blob = BlobGet()
                                                                                                                                                                                                            if not blob then return end
                                                                                                                                                                                                            local char = LP.Character
                                                                                                                                                                                                            local hum = char:FindFirstChild("Humanoid")
                                                                                                                                                                                                            local root = char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            local tChar = target.Character
                                                                                                                                                                                                            local tHum = tChar and tChar:FindFirstChild("Humanoid")
                                                                                                                                                                                                            local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            if not (tHum and tRoot and root and hum) then return end
                                                                                                                                                                                                            local scriptObj = blob:FindFirstChild("BlobmanSeatAndOwnerScript")
                                                                                                                                                                                                            local grab = scriptObj and scriptObj:FindFirstChild("CreatureGrab")
                                                                                                                                                                                                            local release = scriptObj and scriptObj:FindFirstChild("CreatureRelease")
                                                                                                                                                                                                            local L_Det = blob:FindFirstChild("LeftDetector")
                                                                                                                                                                                                            local L_Weld = L_Det and L_Det:FindFirstChild("LeftWeld")
                                                                                                                                                                                                            if not (grab and release and L_Weld) then return end
                                                                                                                                                                                                            local savedPos = root.CFrame
                                                                                                                                                                                                            task.spawn(function()
                                                                                                                                                                                                                if _G.SetNetOwner_Def then _G.SetNetOwner_Def:FireServer(tRoot, tRoot.CFrame) end
                                                                                                                                                                                                            end)
                                                                                                                                                                                                            task.wait(0.1)
                                                                                                                                                                                                            for i = 1, 4 do
                                                                                                                                                                                                                if not hum.SeatPart then break end
                                                                                                                                                                                                                root.CFrame = tRoot.CFrame - Vector3.new(0, 10, 0)
                                                                                                                                                                                                                grab:FireServer(L_Det, tRoot, L_Weld)
                                                                                                                                                                                                                task.wait(0.05)
                                                                                                                                                                                                                release:FireServer(L_Weld, tRoot)
                                                                                                                                                                                                                tHum.Health = 0
                                                                                                                                                                                                                task.wait(0.05)
                                                                                                                                                                                                            end
                                                                                                                                                                                                            root.CFrame = savedPos
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local blobPlusGrabActive = false

                                                                                                                                                                                                        local function BlobPlusGrab(target)
                                                                                                                                                                                                            if not target then return end
                                                                                                                                                                                                            local blob = BlobGet()
                                                                                                                                                                                                            if not blob then return end
                                                                                                                                                                                                            local char = LP.Character
                                                                                                                                                                                                            local hum = char:FindFirstChild("Humanoid")
                                                                                                                                                                                                            local root = char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            local tChar = target.Character
                                                                                                                                                                                                            local tHum = tChar and tChar:FindFirstChild("Humanoid")
                                                                                                                                                                                                            local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            if not (tHum and tRoot and root and hum) then return end
                                                                                                                                                                                                            local scriptObj = blob:FindFirstChild("BlobmanSeatAndOwnerScript")
                                                                                                                                                                                                            local grab = scriptObj and scriptObj:FindFirstChild("CreatureGrab")
                                                                                                                                                                                                            local drop = scriptObj and scriptObj:FindFirstChild("CreatureDrop")
                                                                                                                                                                                                            local release = scriptObj and scriptObj:FindFirstChild("CreatureRelease")
                                                                                                                                                                                                            local L_Det = blob:FindFirstChild("LeftDetector")
                                                                                                                                                                                                            local R_Det = blob:FindFirstChild("RightDetector")
                                                                                                                                                                                                            local L_Weld = L_Det and L_Det:FindFirstChild("LeftWeld")
                                                                                                                                                                                                            local R_Weld = R_Det and R_Det:FindFirstChild("RightWeld")
                                                                                                                                                                                                            if not (grab and drop and L_Weld and R_Weld) then return end
                                                                                                                                                                                                            local GE = RS:FindFirstChild("GrabEvents")
                                                                                                                                                                                                            local savedPos = root.CFrame
                                                                                                                                                                                                            pcall(function() root.CFrame = tRoot.CFrame * CFrame.new(0, 0, 3) end)
                                                                                                                                                                                                            task.wait(0.05)
                                                                                                                                                                                                            for _ = 1, 5 do
                                                                                                                                                                                                                if GE then
                                                                                                                                                                                                                    pcall(function() GE.SetNetworkOwner:FireServer(tRoot, tRoot.CFrame) end)
                                                                                                                                                                                                                    pcall(function() GE.CreateGrabLine:FireServer(tRoot, Vector3.zero, tRoot.Position, false) end)
                                                                                                                                                                                                                end
                                                                                                                                                                                                                task.wait(0.01)
                                                                                                                                                                                                            end
                                                                                                                                                                                                            local startT = tick()
                                                                                                                                                                                                            local phase = 0
                                                                                                                                                                                                            while target and target.Parent and tHum.Health > 0 and (tick() - startT < 12) and blobPlusGrabActive do
                                                                                                                                                                                                                phase = (phase + 1) % 4
                                                                                                                                                                                                                if phase == 0 then
                                                                                                                                                                                                                    pcall(function()
                                                                                                                                                                                                                        grab:FireServer(L_Det, tRoot, L_Weld)
                                                                                                                                                                                                                        grab:FireServer(R_Det, tRoot, R_Weld)
                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                    if GE then
                                                                                                                                                                                                                        pcall(function() GE.SetNetworkOwner:FireServer(tRoot, root.CFrame) end)
                                                                                                                                                                                                                        pcall(function() GE.CreateGrabLine:FireServer(tRoot, Vector3.zero, tRoot.Position, false) end)
                                                                                                                                                                                                                        pcall(function() GE.DestroyGrabLine:FireServer(tRoot) end)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                elseif phase == 1 then
                                                                                                                                                                                                                    pcall(function()
                                                                                                                                                                                                                        drop:FireServer(L_Weld, tRoot)
                                                                                                                                                                                                                        release:FireServer(R_Weld, tRoot)
                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                elseif phase == 2 then
                                                                                                                                                                                                                    pcall(function() grab:FireServer(L_Det, tRoot, L_Weld) end)
                                                                                                                                                                                                                    pcall(function() tRoot.AssemblyLinearVelocity = Vector3.new(0, 25, 0) end)
                                                                                                                                                                                                                elseif phase == 3 then
                                                                                                                                                                                                                    pcall(function()
                                                                                                                                                                                                                        grab:FireServer(L_Det, tRoot, L_Weld)
                                                                                                                                                                                                                        grab:FireServer(R_Det, tRoot, R_Weld)
                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                    if GE then
                                                                                                                                                                                                                        pcall(function() GE.SetNetworkOwner:FireServer(tRoot, root.CFrame) end)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end
                                                                                                                                                                                                                task.wait(0.025)
                                                                                                                                                                                                            end
                                                                                                                                                                                                            pcall(function()
                                                                                                                                                                                                                if drop and L_Weld then drop:FireServer(L_Weld, tRoot) end
                                                                                                                                                                                                                if release and R_Weld then release:FireServer(R_Weld, tRoot) end
                                                                                                                                                                                                            end)
                                                                                                                                                                                                            pcall(function() root.CFrame = savedPos end)
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local blobLockLastTP = 0
                                                                                                                                                                                                        local function BlobLock(target)
                                                                                                                                                                                                            if not target then return end
                                                                                                                                                                                                            local myChar = LP.Character
                                                                                                                                                                                                            local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            local myHum = myChar and myChar:FindFirstChild("Humanoid")
                                                                                                                                                                                                            if not (myHRP and myHum and myHum.SeatPart) then return end
                                                                                                                                                                                                            local blob = myHum.SeatPart.Parent
                                                                                                                                                                                                            if not blob or blob.Name ~= "CreatureBlobman" then return end
                                                                                                                                                                                                            local tChar = target.Character
                                                                                                                                                                                                            local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            local tHum = tChar and tChar:FindFirstChild("Humanoid")
                                                                                                                                                                                                            if not (tRoot and tHum) then return end
                                                                                                                                                                                                            local scriptObj = blob:FindFirstChild("BlobmanSeatAndOwnerScript")
                                                                                                                                                                                                            local grab = scriptObj and scriptObj:FindFirstChild("CreatureGrab")
                                                                                                                                                                                                            local release = scriptObj and scriptObj:FindFirstChild("CreatureRelease")
                                                                                                                                                                                                            local LD = blob:FindFirstChild("LeftDetector")
                                                                                                                                                                                                            local LW = LD and LD:FindFirstChild("LeftWeld")
                                                                                                                                                                                                            if not (grab and release and LW) then return end
                                                                                                                                                                                                            local dist = (myHRP.Position - tRoot.Position).Magnitude
                                                                                                                                                                                                            if dist > 15 and tick() - blobLockLastTP > 0.5 then
                                                                                                                                                                                                                local startPos = myHRP.CFrame
                                                                                                                                                                                                                myHRP.CFrame = tRoot.CFrame + Vector3.new(0, 5, 0)
                                                                                                                                                                                                                task.wait(0.05)
                                                                                                                                                                                                                if _G.SetNetOwner_Def then
                                                                                                                                                                                                                    for _ = 1, 3 do
                                                                                                                                                                                                                        pcall(function() _G.SetNetOwner_Def:FireServer(tRoot, tRoot.CFrame) end)
                                                                                                                                                                                                                        task.wait()
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end
                                                                                                                                                                                                                task.wait(0.1)
                                                                                                                                                                                                                myHRP.CFrame = startPos
                                                                                                                                                                                                                blobLockLastTP = tick()
                                                                                                                                                                                                            end
                                                                                                                                                                                                            pcall(function() grab:FireServer(LD, tRoot, LW) end)
                                                                                                                                                                                                            task.wait(0.005)
                                                                                                                                                                                                            pcall(function() release:FireServer(LW, tRoot) end)
                                                                                                                                                                                                        end

                                                                                                                                                                                                        TargetMeth:CreateButton({
                                                                                                                                                                                                            Name = "Apply Once",
                                                                                                                                                                                                            Callback = function()
                                                                                                                                                                                                                local target = GetTargetPlayer()
                                                                                                                                                                                                                if not target then return end
                                                                                                                                                                                                                if selectedMethod == "Bring" then BlobBring(target)
                                                                                                                                                                                                                elseif selectedMethod == "Kick" then BlobKickBasic(target)
                                                                                                                                                                                                                elseif selectedMethod == "Loop Kick" then
                                                                                                                                                                                                                    loopMethodActive = true
                                                                                                                                                                                                                    BlobLoopKick(target)
                                                                                                                                                                                                                    loopMethodActive = false
                                                                                                                                                                                                                elseif selectedMethod == "Bypass" then
                                                                                                                                                                                                                    loopMethodActive = true
                                                                                                                                                                                                                    BlobBypass(target)
                                                                                                                                                                                                                    loopMethodActive = false
                                                                                                                                                                                                                elseif selectedMethod == "Blob Kill" then BlobKill(target)
                                                                                                                                                                                                                elseif selectedMethod == "Blob + Grab" then
                                                                                                                                                                                                                    blobPlusGrabActive = true
                                                                                                                                                                                                                    BlobPlusGrab(target)
                                                                                                                                                                                                                    blobPlusGrabActive = false
                                                                                                                                                                                                                elseif selectedMethod == "Lock" then BlobLock(target)
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        local loopMethodTask = nil
                                                                                                                                                                                                        TargetMeth:CreateToggle({
                                                                                                                                                                                                            Name = "Loop Method",
                                                                                                                                                                                                            Flag = "LoopMethod",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                loopMethodActive = Value
                                                                                                                                                                                                                blobPlusGrabActive = Value
                                                                                                                                                                                                                if loopMethodTask then task.cancel(loopMethodTask) loopMethodTask = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                loopMethodTask = task.spawn(function()
                                                                                                                                                                                                                    while loopMethodActive do
                                                                                                                                                                                                                        local target = GetTargetPlayer()
                                                                                                                                                                                                                        if target then
                                                                                                                                                                                                                            if selectedMethod == "Blob + Grab" then
                                                                                                                                                                                                                                blobPlusGrabActive = true
                                                                                                                                                                                                                                BlobPlusGrab(target)
                                                                                                                                                                                                                                blobPlusGrabActive = false
                                                                                                                                                                                                                            elseif selectedMethod == "Lock" then BlobLock(target)
                                                                                                                                                                                                                            elseif selectedMethod == "Bring" then BlobBring(target)
                                                                                                                                                                                                                            elseif selectedMethod == "Kick" then BlobKickBasic(target)
                                                                                                                                                                                                                            elseif selectedMethod == "Loop Kick" then BlobLoopKick(target)
                                                                                                                                                                                                                            elseif selectedMethod == "Bypass" then BlobBypass(target)
                                                                                                                                                                                                                            elseif selectedMethod == "Blob Kill" then BlobKill(target)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        task.wait(0.1)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- TRACE TO TARGET
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local traceEnabled = false
                                                                                                                                                                                                        local traceColor   = Color3.fromRGB(255, 0, 0)
                                                                                                                                                                                                        local traceBeam    = nil
                                                                                                                                                                                                        local traceConn    = nil
                                                                                                                                                                                                        local tracePart0   = nil
                                                                                                                                                                                                        local tracePart1   = nil

                                                                                                                                                                                                        local function StopTrace()
                                                                                                                                                                                                            if traceConn then traceConn:Disconnect() traceConn = nil end
                                                                                                                                                                                                            if traceBeam then traceBeam:Destroy() traceBeam = nil end
                                                                                                                                                                                                            if tracePart0 then tracePart0:Destroy() tracePart0 = nil end
                                                                                                                                                                                                            if tracePart1 then tracePart1:Destroy() tracePart1 = nil end
                                                                                                                                                                                                        end

                                                                                                                                                                                                        TargetMisc:CreateToggle({
                                                                                                                                                                                                            Name = "Trace to Target",
                                                                                                                                                                                                            Flag = "TraceToTarget",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                traceEnabled = Value
                                                                                                                                                                                                                StopTrace()
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                local target = GetTargetPlayer()
                                                                                                                                                                                                                if not target then traceEnabled = false return end
                                                                                                                                                                                                                tracePart0 = Instance.new("Part")
                                                                                                                                                                                                                tracePart0.Anchored = true tracePart0.CanCollide = false tracePart0.Transparency = 1
                                                                                                                                                                                                                tracePart0.Size = Vector3.new(0.1, 0.1, 0.1) tracePart0.Parent = workspace
                                                                                                                                                                                                                tracePart1 = Instance.new("Part")
                                                                                                                                                                                                                tracePart1.Anchored = true tracePart1.CanCollide = false tracePart1.Transparency = 1
                                                                                                                                                                                                                tracePart1.Size = Vector3.new(0.1, 0.1, 0.1) tracePart1.Parent = workspace
                                                                                                                                                                                                                local att0 = Instance.new("Attachment", tracePart0)
                                                                                                                                                                                                                local att1 = Instance.new("Attachment", tracePart1)
                                                                                                                                                                                                                traceBeam = Instance.new("Beam")
                                                                                                                                                                                                                traceBeam.Attachment0 = att0
                                                                                                                                                                                                                traceBeam.Attachment1 = att1
                                                                                                                                                                                                                traceBeam.Color = ColorSequence.new(traceColor)
                                                                                                                                                                                                                traceBeam.Width0 = 0.6 traceBeam.Width1 = 0.6
                                                                                                                                                                                                                traceBeam.LightEmission = 1 traceBeam.FaceCamera = true
                                                                                                                                                                                                                traceBeam.Parent = workspace
                                                                                                                                                                                                                traceConn = R.RenderStepped:Connect(function()
                                                                                                                                                                                                                    if not traceEnabled then return end
                                                                                                                                                                                                                    local t = GetTargetPlayer()
                                                                                                                                                                                                                    if not t or not t.Character then return end
                                                                                                                                                                                                                    local myChar = LP.Character
                                                                                                                                                                                                                    local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    local tHRP = t.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if myHRP and tHRP and tracePart0 and tracePart1 then
                                                                                                                                                                                                                        tracePart0.Position = myHRP.Position
                                                                                                                                                                                                                        tracePart1.Position = tHRP.Position
                                                                                                                                                                                                                        if traceBeam then traceBeam.Color = ColorSequence.new(traceColor) end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        TargetMisc:CreateColorPicker({
                                                                                                                                                                                                            Name = "Trace Color",
                                                                                                                                                                                                            Flag = "TraceColor",
                                                                                                                                                                                                            Default = Color3.fromRGB(255, 0, 0),
                                                                                                                                                                                                            Callback = function(c) traceColor = c end
                                                                                                                                                                                                        })

