                                                                                                                                                                                                        -- TARGET NOTIFY
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local targetNotifyActive = false
                                                                                                                                                                                                        TargetMisc:CreateToggle({
                                                                                                                                                                                                            Name = "Target Notify",
                                                                                                                                                                                                            Flag = "TargetNotify",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                targetNotifyActive = Value
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                local currentTargetName = nil
                                                                                                                                                                                                                local arr = _G.TrueAmAm_SelectedTargets
                                                                                                                                                                                                                if arr and arr[1] then currentTargetName = arr[1] end
                                                                                                                                                                                                                if not currentTargetName then return end
                                                                                                                                                                                                                local target = P:FindFirstChild(currentTargetName)
                                                                                                                                                                                                                if target then Notify("true am am", target.DisplayName .. " is in game", 3) end
                                                                                                                                                                                                                P.PlayerAdded:Connect(function(player)
                                                                                                                                                                                                                    if targetNotifyActive and player.Name == currentTargetName then
                                                                                                                                                                                                                        Notify("true am am", player.DisplayName .. " joined", 3)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                                P.PlayerRemoving:Connect(function(player)
                                                                                                                                                                                                                    if targetNotifyActive and player.Name == currentTargetName then
                                                                                                                                                                                                                        Notify("true am am", player.DisplayName .. " left", 3)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- RAGDOLL SPAM
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local ragdollSpamActive = false
                                                                                                                                                                                                        local ragdollSpamTask   = nil

                                                                                                                                                                                                        TargetMisc:CreateToggle({
                                                                                                                                                                                                            Name = "Ragdoll Spam",
                                                                                                                                                                                                            Flag = "RagdollSpam",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                ragdollSpamActive = Value
                                                                                                                                                                                                                if ragdollSpamTask then task.cancel(ragdollSpamTask) ragdollSpamTask = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                ragdollSpamTask = task.spawn(function()
                                                                                                                                                                                                                    local skyPos = CFrame.new(0, 800000, 0)
                                                                                                                                                                                                                    if _G.SpawnToy_Def then
                                                                                                                                                                                                                        pcall(function() _G.SpawnToy_Def:InvokeServer("PalletLightBrown", skyPos, Vector3.zero) end)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    local pallet
                                                                                                                                                                                                                    local t0 = tick()
                                                                                                                                                                                                                    repeat
                                                                                                                                                                                                                        pallet = workspace:FindFirstChild(LP.Name.."SpawnedInToys")
                                                                                                                                                                                                                            and workspace[LP.Name.."SpawnedInToys"]:FindFirstChild("PalletLightBrown")
                                                                                                                                                                                                                        R.Heartbeat:Wait()
                                                                                                                                                                                                                    until pallet or tick() - t0 > 3 or not ragdollSpamActive
                                                                                                                                                                                                                    if not pallet then return end
                                                                                                                                                                                                                    local mainPart = pallet:FindFirstChild("SoundPart")
                                                                                                                                                                                                                    if not mainPart then return end
                                                                                                                                                                                                                    mainPart.CanCollide = false
                                                                                                                                                                                                                    mainPart.Anchored = false
                                                                                                                                                                                                                    local strike = false
                                                                                                                                                                                                                    while ragdollSpamActive do
                                                                                                                                                                                                                        R.Heartbeat:Wait()
                                                                                                                                                                                                                        local target = GetTargetPlayer()
                                                                                                                                                                                                                        if not target or not target.Character then continue end
                                                                                                                                                                                                                        local tRoot = target.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        if not tRoot then continue end
                                                                                                                                                                                                                        strike = not strike
                                                                                                                                                                                                                        if strike then
                                                                                                                                                                                                                            mainPart.CFrame = tRoot.CFrame * CFrame.new(0, 2, 0)
                                                                                                                                                                                                                            mainPart.AssemblyLinearVelocity = Vector3.new(0, -9e5, 0)
                                                                                                                                                                                                                        else
                                                                                                                                                                                                                            mainPart.CFrame = tRoot.CFrame * CFrame.new(0, -1, 0)
                                                                                                                                                                                                                            mainPart.AssemblyLinearVelocity = Vector3.new(0, 9e5, 0)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        if _G.SetNetOwner_Def then _G.SetNetOwner_Def:FireServer(mainPart, mainPart.CFrame) end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    if pallet then
                                                                                                                                                                                                                        pcall(function() if _G.DestroyToy_Def then _G.DestroyToy_Def:FireServer(pallet) end end)
                                                                                                                                                                                                                        if pallet.Parent then pallet:Destroy() end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })
                                                                                                                                                                                                    end

