                                                                                                                                                                                                                                repeat
                                                                                                                                                                                                                                    R.Heartbeat:Wait()
                                                                                                                                                                                                                                    folder = workspace:FindFirstChild(LP.Name .. "SpawnedInToys")
                                                                                                                                                                                                                                    blob = folder and folder:FindFirstChild("CreatureBlobman")
                                                                                                                                                                                                                                until blob or tick() - t0 > 5 or not autoSitActive
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                            if blob then
                                                                                                                                                                                                                                local seat = blob:FindFirstChildWhichIsA("VehicleSeat")
                                                                                                                                                                                                                                if seat then
                                                                                                                                                                                                                                    root.CFrame = seat.CFrame * CFrame.new(0, 1, 0)
                                                                                                                                                                                                                                    root.Velocity = Vector3.zero
                                                                                                                                                                                                                                    pcall(function() seat:Sit(hum) end)
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                        task.wait(0.1)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- SIT JUMP
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local sitJumpActive = false
                                                                                                                                                                                                        local sitJumpConn   = nil

                                                                                                                                                                                                        BlobSel:CreateToggle({
                                                                                                                                                                                                            Name = "Sit Jump",
                                                                                                                                                                                                            Flag = "SitJump",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                sitJumpActive = Value
                                                                                                                                                                                                                if sitJumpConn then sitJumpConn:Disconnect() sitJumpConn = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                sitJumpConn = R.Heartbeat:Connect(function()
                                                                                                                                                                                                                    if not sitJumpActive then return end
                                                                                                                                                                                                                    local char = LP.Character
                                                                                                                                                                                                                    local hum = char and char:FindFirstChildOfClass("Humanoid")
                                                                                                                                                                                                                    if hum and hum.SeatPart then
                                                                                                                                                                                                                        hum:ChangeState(Enum.HumanoidStateType.Jumping)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- BLOB + GRAB
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local bpgActive = false
                                                                                                                                                                                                        local bpgTask   = nil

                                                                                                                                                                                                        BlobFn:CreateToggle({
                                                                                                                                                                                                            Name = "Blob + Grab",
                                                                                                                                                                                                            Flag = "BlobPlusGrab",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                bpgActive = Value
                                                                                                                                                                                                                if bpgTask then task.cancel(bpgTask) bpgTask = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                bpgTask = task.spawn(function()
                                                                                                                                                                                                                    while bpgActive do
                                                                                                                                                                                                                        local target = GetBlobTargetPlayer()
                                                                                                                                                                                                                        if not target then task.wait(0.2) continue end
                                                                                                                                                                                                                        local blob = FindBlob()
                                                                                                                                                                                                                        if not blob then task.wait(0.2) continue end
                                                                                                                                                                                                                        local char = LP.Character
                                                                                                                                                                                                                        local hum = char:FindFirstChild("Humanoid")
                                                                                                                                                                                                                        local root = char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        local tChar = target.Character
                                                                                                                                                                                                                        local tHum = tChar and tChar:FindFirstChild("Humanoid")
                                                                                                                                                                                                                        local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        if not (tHum and tRoot and root and hum) or tHum.Health <= 0 then task.wait(0.2) continue end
                                                                                                                                                                                                                        local scriptObj = blob:FindFirstChild("BlobmanSeatAndOwnerScript")
                                                                                                                                                                                                                        local grab = scriptObj and scriptObj:FindFirstChild("CreatureGrab")
                                                                                                                                                                                                                        local drop = scriptObj and scriptObj:FindFirstChild("CreatureDrop")
                                                                                                                                                                                                                        local release = scriptObj and scriptObj:FindFirstChild("CreatureRelease")
                                                                                                                                                                                                                        local L_Det = blob:FindFirstChild("LeftDetector")
                                                                                                                                                                                                                        local R_Det = blob:FindFirstChild("RightDetector")
                                                                                                                                                                                                                        local L_Weld = L_Det and L_Det:FindFirstChild("LeftWeld")
                                                                                                                                                                                                                        local R_Weld = R_Det and R_Det:FindFirstChild("RightWeld")
                                                                                                                                                                                                                        if not (grab and drop and L_Weld and R_Weld) then task.wait(0.2) continue end
                                                                                                                                                                                                                        local GE = RS:FindFirstChild("GrabEvents")
                                                                                                                                                                                                                        local savedPos = root.CFrame
                                                                                                                                                                                                                        pcall(function() root.CFrame = tRoot.CFrame * CFrame.new(0, 0, 3) end)
                                                                                                                                                                                                                        task.wait(0.05)
                                                                                                                                                                                                                        for _ = 1, 5 do
                                                                                                                                                                                                                            if GE then
                                                                                                                                                                                                                                pcall(function() GE.SetNetworkOwner:FireServer(tRoot, tRoot.CFrame) end)
                                                                                                                                                                                                                                pcall(function() GE.CreateGrabLine:FireServer(tRoot, Vector3.zero, tRoot.Position, false) end)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                            task.wait(0.01)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        local startT = tick()
                                                                                                                                                                                                                        local phase = 0
                                                                                                                                                                                                                        while target and target.Parent and tHum.Health > 0 and (tick() - startT < 3) and bpgActive do
                                                                                                                                                                                                                            phase = (phase + 1) % 4
                                                                                                                                                                                                                            if phase == 0 then
                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                    grab:FireServer(L_Det, tRoot, L_Weld)
                                                                                                                                                                                                                                    grab:FireServer(R_Det, tRoot, R_Weld)
                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                if GE then
                                                                                                                                                                                                                                    pcall(function() GE.SetNetworkOwner:FireServer(tRoot, root.CFrame) end)
                                                                                                                                                                                                                                    pcall(function() GE.CreateGrabLine:FireServer(tRoot, Vector3.zero, tRoot.Position, false) end)
                                                                                                                                                                                                                                    pcall(function() GE.DestroyGrabLine:FireServer(tRoot) end)
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            elseif phase == 1 then
                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                    drop:FireServer(L_Weld, tRoot)
                                                                                                                                                                                                                                    release:FireServer(R_Weld, tRoot)
                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                            elseif phase == 2 then
                                                                                                                                                                                                                                pcall(function() grab:FireServer(L_Det, tRoot, L_Weld) end)
                                                                                                                                                                                                                                pcall(function() tRoot.AssemblyLinearVelocity = Vector3.new(0, 25, 0) end)
                                                                                                                                                                                                                            elseif phase == 3 then
                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                    grab:FireServer(L_Det, tRoot, L_Weld)
                                                                                                                                                                                                                                    grab:FireServer(R_Det, tRoot, R_Weld)
                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                                if GE then
                                                                                                                                                                                                                                    pcall(function() GE.SetNetworkOwner:FireServer(tRoot, root.CFrame) end)
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                            task.wait(0.025)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        pcall(function()
                                                                                                                                                                                                                            drop:FireServer(L_Weld, tRoot)
                                                                                                                                                                                                                            release:FireServer(R_Weld, tRoot)
                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                        pcall(function() root.CFrame = savedPos end)
                                                                                                                                                                                                                        task.wait(0.05)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- BLOB KICK
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local blobKickActive = false
                                                                                                                                                                                                        local blobKickTask   = nil

                                                                                                                                                                                                        BlobFn:CreateToggle({
                                                                                                                                                                                                            Name = "Blob Kick",
                                                                                                                                                                                                            Flag = "BlobKick",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                blobKickActive = Value
                                                                                                                                                                                                                if blobKickTask then task.cancel(blobKickTask) blobKickTask = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                blobKickTask = task.spawn(function()
                                                                                                                                                                                                                    while blobKickActive do
                                                                                                                                                                                                                        local target = GetBlobTargetPlayer()
                                                                                                                                                                                                                        if not target then task.wait(0.2) continue end
                                                                                                                                                                                                                        local blob = FindBlob()
                                                                                                                                                                                                                        if not blob then task.wait(0.2) continue end
                                                                                                                                                                                                                        local char = LP.Character
                                                                                                                                                                                                                        local root = char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        local tChar = target.Character
                                                                                                                                                                                                                        local tHum = tChar and tChar:FindFirstChild("Humanoid")
                                                                                                                                                                                                                        local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        if not (tHum and tRoot and root) or tHum.Health <= 0 then task.wait(0.2) continue end
                                                                                                                                                                                                                        local scriptObj = blob:FindFirstChild("BlobmanSeatAndOwnerScript")
                                                                                                                                                                                                                        local grab = scriptObj and scriptObj:FindFirstChild("CreatureGrab")
                                                                                                                                                                                                                        local drop = scriptObj and scriptObj:FindFirstChild("CreatureDrop")
                                                                                                                                                                                                                        local L_Det = blob:FindFirstChild("LeftDetector")
                                                                                                                                                                                                                        local L_Weld = L_Det and L_Det:FindFirstChild("LeftWeld")
                                                                                                                                                                                                                        if not (grab and drop and L_Weld) then task.wait(0.2) continue end
                                                                                                                                                                                                                        local origCF = root.CFrame
                                                                                                                                                                                                                        root.CFrame = tRoot.CFrame * CFrame.new(0, 0, 3)
                                                                                                                                                                                                                        task.wait(0.5)
                                                                                                                                                                                                                        grab:FireServer(L_Det, tRoot, L_Weld)
                                                                                                                                                                                                                        task.wait(0.7)
                                                                                                                                                                                                                        drop:FireServer(L_Weld, tRoot)
                                                                                                                                                                                                                        task.wait(0.3)
                                                                                                                                                                                                                        grab:FireServer(L_Det, tRoot, L_Weld)
                                                                                                                                                                                                                        local bp = Instance.new("BodyPosition")
                                                                                                                                                                                                                        bp.Position = Vector3.new(0, 999e5, 0)
                                                                                                                                                                                                                        bp.MaxForce = Vector3.new(0, 99999e9, 0)
                                                                                                                                                                                                                        bp.Parent = tRoot
                                                                                                                                                                                                                        task.wait(0.6)
                                                                                                                                                                                                                        grab:FireServer(L_Det, tRoot, L_Weld)
                                                                                                                                                                                                                        bp:Destroy()
                                                                                                                                                                                                                        root.CFrame = origCF
                                                                                                                                                                                                                        task.wait(0.1)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- BLOB LOOP KICK
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local blobLoopActive = false
                                                                                                                                                                                                        local blobLoopTask   = nil

                                                                                                                                                                                                        BlobFn:CreateToggle({
                                                                                                                                                                                                            Name = "Blob Loop Kick",
                                                                                                                                                                                                            Flag = "BlobLoopKick",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                blobLoopActive = Value
                                                                                                                                                                                                                if blobLoopTask then task.cancel(blobLoopTask) blobLoopTask = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                blobLoopTask = task.spawn(function()
                                                                                                                                                                                                                    local REMOTE_DELAY = 0.002
                                                                                                                                                                                                                    local lastRemote = 0
                                                                                                                                                                                                                    while blobLoopActive do
                                                                                                                                                                                                                        local target = GetBlobTargetPlayer()
                                                                                                                                                                                                                        if not target then task.wait(0.2) continue end
                                                                                                                                                                                                                        local char = LP.Character or LP.CharacterAdded:Wait()
                                                                                                                                                                                                                        local hum = char:WaitForChild("Humanoid")
                                                                                                                                                                                                                        local seat = hum.SeatPart
                                                                                                                                                                                                                        if not seat or seat.Parent.Name ~= "CreatureBlobman" then task.wait(0.3) continue end
                                                                                                                                                                                                                        local blob = seat.Parent
                                                                                                                                                                                                                        local blobRoot = blob:FindFirstChild("HumanoidRootPart") or blob.PrimaryPart
                                                                                                                                                                                                                        local scriptObj = blob:WaitForChild("BlobmanSeatAndOwnerScript")
                                                                                                                                                                                                                        local CG = scriptObj:WaitForChild("CreatureGrab")
                                                                                                                                                                                                                        local CD = scriptObj:WaitForChild("CreatureDrop")
                                                                                                                                                                                                                        local R_Det = blob:WaitForChild("RightDetector")
                                                                                                                                                                                                                        local savedPos = blobRoot.CFrame
                                                                                                                                                                                                                        local dragging = false
                                                                                                                                                                                                                        local grabStartTime = 0
                                                                                                                                                                                                                        while blobLoopActive do
                                                                                                                                                                                                                            local cur = GetBlobTargetPlayer()
                                                                                                                                                                                                                            if not cur then break end
                                                                                                                                                                                                                            char = LP.Character
                                                                                                                                                                                                                            hum = char and char:FindFirstChild("Humanoid")
                                                                                                                                                                                                                            seat = hum and hum.SeatPart
                                                                                                                                                                                                                            if not seat or seat.Parent.Name ~= "CreatureBlobman" then break end
                                                                                                                                                                                                                            blob = seat.Parent
                                                                                                                                                                                                                            blobRoot = blob:FindFirstChild("HumanoidRootPart") or blob.PrimaryPart
                                                                                                                                                                                                                            local tChar = cur.Character
                                                                                                                                                                                                                            local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                            local tHum = tChar and tChar:FindFirstChild("Humanoid")
                                                                                                                                                                                                                            if tRoot and tHum and tHum.Health > 0 and blobRoot then
                                                                                                                                                                                                                                tRoot.Velocity = Vector3.zero
                                                                                                                                                                                                                                if not dragging then
                                                                                                                                                                                                                                    blobRoot.CFrame = tRoot.CFrame
                                                                                                                                                                                                                                    blobRoot.Velocity = Vector3.zero
                                                                                                                                                                                                                                    if tick() - lastRemote >= REMOTE_DELAY then
                                                                                                                                                                                                                                        lastRemote = tick()
                                                                                                                                                                                                                                        pcall(function()
                                                                                                                                                                                                                                            tHum.PlatformStand = true
                                                                                                                                                                                                                                            tHum.Sit = true
                                                                                                                                                                                                                                            if _G.SetNetOwner_Def then _G.SetNetOwner_Def:FireServer(tRoot, blobRoot.CFrame) end
                                                                                                                                                                                                                                            if _G.DestroyGrabLine_Def then _G.DestroyGrabLine_Def:FireServer(tRoot) end
                                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                    if grabStartTime == 0 then grabStartTime = tick() end
                                                                                                                                                                                                                                    if tick() - grabStartTime > 0.35 then
                                                                                                                                                                                                                                        dragging = true
                                                                                                                                                                                                                                        grabStartTime = 0
                                                                                                                                                                                                                                        blobRoot.CFrame = savedPos
                                                                                                                                                                                                                                        blobRoot.Velocity = Vector3.zero
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                else
                                                                                                                                                                                                                                    blobRoot.CFrame = savedPos
                                                                                                                                                                                                                                    blobRoot.Velocity = Vector3.zero
                                                                                                                                                                                                                                    local lockPos = savedPos * CFrame.new(0, 23, 0)
                                                                                                                                                                                                                                    tRoot.CFrame = lockPos
                                                                                                                                                                                                                                    tHum.PlatformStand = true
                                                                                                                                                                                                                                    tHum.Sit = true
                                                                                                                                                                                                                                    if tick() - lastRemote >= REMOTE_DELAY then
                                                                                                                                                                                                                                        lastRemote = tick()
                                                                                                                                                                                                                                        pcall(function()
                                                                                                                                                                                                                                            if _G.SetNetOwner_Def then _G.SetNetOwner_Def:FireServer(tRoot, lockPos) end
                                                                                                                                                                                                                                            if _G.DestroyGrabLine_Def then _G.DestroyGrabLine_Def:FireServer(tRoot) end
                                                                                                                                                                                                                                            local weld = R_Det:FindFirstChild("RightWeld") or R_Det:FindFirstChildWhichIsA("Weld")
                                                                                                                                                                                                                                            if weld then
                                                                                                                                                                                                                                                CD:FireServer(weld)
                                                                                                                                                                                                                                                CG:FireServer(R_Det, tRoot, weld)
                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            else
                                                                                                                                                                                                                                dragging = false
                                                                                                                                                                                                                                grabStartTime = 0
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                            R.Heartbeat:Wait()
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        if blobRoot then
                                                                                                                                                                                                                            blobRoot.CFrame = savedPos
                                                                                                                                                                                                                            blobRoot.Velocity = Vector3.zero
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        task.wait(0.2)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- BLOB LOCK
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local blobLockActive = false
                                                                                                                                                                                                        local blobLockTask   = nil
                                                                                                                                                                                                        local blobLockLastTP = 0

                                                                                                                                                                                                        BlobFn:CreateToggle({
                                                                                                                                                                                                            Name = "Blob Lock",
                                                                                                                                                                                                            Flag = "BlobLockToggle",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                blobLockActive = Value
                                                                                                                                                                                                                if blobLockTask then task.cancel(blobLockTask) blobLockTask = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                blobLockTask = task.spawn(function()
                                                                                                                                                                                                                    while blobLockActive do
                                                                                                                                                                                                                        local target = GetBlobTargetPlayer()
                                                                                                                                                                                                                        if not target then task.wait(0.2) continue end
                                                                                                                                                                                                                        local myChar = LP.Character
                                                                                                                                                                                                                        local myHRP = myChar and myChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        local myHum = myChar and myChar:FindFirstChild("Humanoid")
                                                                                                                                                                                                                        if not (myHRP and myHum and myHum.SeatPart) then task.wait(0.2) continue end
                                                                                                                                                                                                                        local blob = myHum.SeatPart.Parent
                                                                                                                                                                                                                        if not blob or blob.Name ~= "CreatureBlobman" then task.wait(0.2) continue end
                                                                                                                                                                                                                        local tChar = target.Character
                                                                                                                                                                                                                        local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        local tHum = tChar and tChar:FindFirstChild("Humanoid")
                                                                                                                                                                                                                        if not (tRoot and tHum) then task.wait(0.2) continue end
                                                                                                                                                                                                                        local scriptObj = blob:FindFirstChild("BlobmanSeatAndOwnerScript")
                                                                                                                                                                                                                        local grab = scriptObj and scriptObj:FindFirstChild("CreatureGrab")
                                                                                                                                                                                                                        local release = scriptObj and scriptObj:FindFirstChild("CreatureRelease")
                                                                                                                                                                                                                        local LD = blob:FindFirstChild("LeftDetector")
                                                                                                                                                                                                                        local LW = LD and LD:FindFirstChild("LeftWeld")
                                                                                                                                                                                                                        if not (grab and release and LW) then task.wait(0.2) continue end
                                                                                                                                                                                                                        local dist = (myHRP.Position - tRoot.Position).Magnitude
                                                                                                                                                                                                                        if dist > 15 and tick() - blobLockLastTP > 0.5 then
                                                                                                                                                                                                                            local startPos = myHRP.CFrame
                                                                                                                                                                                                                            myHRP.CFrame = tRoot.CFrame + Vector3.new(0, 5, 0)
                                                                                                                                                                                                                            task.wait(0.05)
                                                                                                                                                                                                                            if _G.SetNetOwner_Def then
                                                                                                                                                                                                                                for _ = 1, 3 do
                                                                                                                                                                                                                                    pcall(function() _G.SetNetOwner_Def:FireServer(tRoot, tRoot.CFrame) end)
                                                                                                                                                                                                                                    task.wait()
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                            task.wait(0.1)
                                                                                                                                                                                                                            myHRP.CFrame = startPos
                                                                                                                                                                                                                            blobLockLastTP = tick()
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        pcall(function() grab:FireServer(LD, tRoot, LW) end)
                                                                                                                                                                                                                        task.wait(0.005)
                                                                                                                                                                                                                        pcall(function() release:FireServer(LW, tRoot) end)
                                                                                                                                                                                                                        task.wait(0.05)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- BLOB KILL
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local blobKillActive = false
                                                                                                                                                                                                        local blobKillTask   = nil

                                                                                                                                                                                                        BlobFn:CreateToggle({
                                                                                                                                                                                                            Name = "Blob Kill",
                                                                                                                                                                                                            Flag = "BlobKillToggle",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                blobKillActive = Value
                                                                                                                                                                                                                if blobKillTask then task.cancel(blobKillTask) blobKillTask = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                blobKillTask = task.spawn(function()
                                                                                                                                                                                                                    while blobKillActive do
                                                                                                                                                                                                                        local target = GetBlobTargetPlayer()
                                                                                                                                                                                                                        if not target then task.wait(0.2) continue end
                                                                                                                                                                                                                        local blob = FindBlob()
                                                                                                                                                                                                                        if not blob then task.wait(0.2) continue end
                                                                                                                                                                                                                        local char = LP.Character
                                                                                                                                                                                                                        local hum = char and char:FindFirstChild("Humanoid")
                                                                                                                                                                                                                        local root = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        local tChar = target.Character
                                                                                                                                                                                                                        local tHum = tChar and tChar:FindFirstChild("Humanoid")
                                                                                                                                                                                                                        local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        if not (tHum and tRoot and root and hum) or tHum.Health <= 0 then task.wait(0.2) continue end
                                                                                                                                                                                                                        local scriptObj = blob:FindFirstChild("BlobmanSeatAndOwnerScript")
                                                                                                                                                                                                                        local grab = scriptObj and scriptObj:FindFirstChild("CreatureGrab")
                                                                                                                                                                                                                        local release = scriptObj and scriptObj:FindFirstChild("CreatureRelease")
                                                                                                                                                                                                                        local L_Det = blob:FindFirstChild("LeftDetector")
                                                                                                                                                                                                                        local L_Weld = L_Det and L_Det:FindFirstChild("LeftWeld")
                                                                                                                                                                                                                        if not (grab and release and L_Weld) then task.wait(0.2) continue end
                                                                                                                                                                                                                        local savedPos = root.CFrame
                                                                                                                                                                                                                        task.spawn(function()
                                                                                                                                                                                                                            if _G.SetNetOwner_Def then _G.SetNetOwner_Def:FireServer(tRoot, tRoot.CFrame) end
                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                        task.wait(0.1)
                                                                                                                                                                                                                        for i = 1, 4 do
                                                                                                                                                                                                                            if not hum.SeatPart then break end
                                                                                                                                                                                                                            root.CFrame = tRoot.CFrame - Vector3.new(0, 10, 0)
                                                                                                                                                                                                                            grab:FireServer(L_Det, tRoot, L_Weld)
                                                                                                                                                                                                                            task.wait(0.05)
                                                                                                                                                                                                                            release:FireServer(L_Weld, tRoot)
                                                                                                                                                                                                                            tHum.Health = 0
                                                                                                                                                                                                                            task.wait(0.05)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        root.CFrame = savedPos
                                                                                                                                                                                                                        task.wait(0.15)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })
                                                                                                                                                                                                    end

                                                                                                                                                                                                    -- ============================================================
                                                                                                                                                                                                    -- GRABS TAB
                                                                                                                                                                                                    -- ============================================================
                                                                                                                                                                                                    do
                                                                                                                                                                                                        local GrabL = Tabs.Grabs:CreateBlock({Name = "Grab Customization", Side = "Left", ImageID = "17313314020"})
                                                                                                                                                                                                        local GrabR = Tabs.Grabs:CreateBlock({Name = "Grab Effects", Side = "Right", ImageID = "17313314020"})
                                                                                                                                                                                                        local LineL = Tabs.Grabs:CreateBlock({Name = "Line Customization", Side = "Left", ImageID = "17313314020"})
                                                                                                                                                                                                        local PanelR = Tabs.Grabs:CreateBlock({Name = "Gamepass", Side = "Right", ImageID = "17313314020"})

                                                                                                                                                                                                        _G.strength = 750

                                                                                                                                                                                                        GrabL:CreateSlider({
                                                                                                                                                                                                            Name = "Throw Power",
                                                                                                                                                                                                            Flag = "ThrowPower",
                                                                                                                                                                                                            Min = 1, Max = 20000, Default = 750,
                                                                                                                                                                                                            Callback = function(Value) _G.strength = Value end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        local strengthConn = nil

                                                                                                                                                                                                        GrabL:CreateToggle({
                                                                                                                                                                                                            Name = "Strength (throw on release)",
                                                                                                                                                                                                            Flag = "StrengthToggle",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Enabled)
                                                                                                                                                                                                                if strengthConn then strengthConn:Disconnect() strengthConn = nil end
                                                                                                                                                                                                                if not Enabled then return end
                                                                                                                                                                                                                strengthConn = workspace.ChildAdded:Connect(function(model)
                                                                                                                                                                                                                    if model.Name == "GrabParts" then
                                                                                                                                                                                                                        local partToImpulse = model.GrabPart.WeldConstraint.Part1
                                                                                                                                                                                                                        if partToImpulse then
                                                                                                                                                                                                                            local velocityObj = Instance.new("BodyVelocity", partToImpulse)
                                                                                                                                                                                                                            model:GetPropertyChangedSignal("Parent"):Connect(function()
                                                                                                                                                                                                                                if not model.Parent then
                                                                                                                                                                                                                                    if U:GetLastInputType() == Enum.UserInputType.MouseButton2 then
                                                                                                                                                                                                                                        velocityObj.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                                                                                                                                                                                                                                        velocityObj.Velocity = workspace.CurrentCamera.CFrame.LookVector * _G.strength
                                                                                                                                                                                                                                        Debris:AddItem(velocityObj, 1)
                                                                                                                                                                                                                                    else
                                                                                                                                                                                                                                        velocityObj:Destroy()
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        local killGrabEnabled = false

                                                                                                                                                                                                        workspace.ChildAdded:Connect(function(v)
                                                                                                                                                                                                            if v:IsA("Model") and v.Name == "GrabParts" and killGrabEnabled then
                                                                                                                                                                                                                task.wait(0.05)
                                                                                                                                                                                                                local grabPart = v:FindFirstChild("GrabPart")
                                                                                                                                                                                                                if grabPart and grabPart:FindFirstChild("WeldConstraint") then
                                                                                                                                                                                                                    local part1 = grabPart.WeldConstraint.Part1
                                                                                                                                                                                                                    if part1 and part1.Parent and part1.Parent ~= LP.Character then
                                                                                                                                                                                                                        local targetChar = part1.Parent
                                                                                                                                                                                                                        local targetHum = targetChar:FindFirstChildOfClass("Humanoid")
                                                                                                                                                                                                                        if targetHum and targetChar then
                                                                                                                                                                                                                            pcall(function()
                                                                                                                                                                                                                                targetHum.Health = 0
                                                                                                                                                                                                                                targetChar:BreakJoints()
                                                                                                                                                                                                                            end)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end)

                                                                                                                                                                                                        GrabL:CreateToggle({
                                                                                                                                                                                                            Name = "Kill Grab",
                                                                                                                                                                                                            Flag = "KillGrab",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value) killGrabEnabled = Value end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- Massless Grab
                                                                                                                                                                                                        local masslessActive = false
                                                                                                                                                                                                        local masslessConn   = nil
                                                                                                                                                                                                        local masslessSense  = 200

                                                                                                                                                                                                        GrabR:CreateToggle({
                                                                                                                                                                                                            Name = "Massless Grab",
                                                                                                                                                                                                            Flag = "MasslessGrab",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                masslessActive = Value
                                                                                                                                                                                                                if masslessConn then masslessConn:Disconnect() masslessConn = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                masslessConn = R.Heartbeat:Connect(function()
                                                                                                                                                                                                                    if not masslessActive then return end
                                                                                                                                                                                                                    local gp = workspace:FindFirstChild("GrabParts")
                                                                                                                                                                                                                    if not gp then return end
                                                                                                                                                                                                                    local dp = gp:FindFirstChild("DragPart")
                                                                                                                                                                                                                    if not dp then return end
                                                                                                                                                                                                                    local ap = dp:FindFirstChild("AlignPosition")
                                                                                                                                                                                                                    local ao = dp:FindFirstChild("AlignOrientation")
                                                                                                                                                                                                                    if ap then
                                                                                                                                                                                                                        ap.Responsiveness = masslessSense
                                                                                                                                                                                                                        ap.MaxForce = math.huge
                                                                                                                                                                                                                        ap.MaxVelocity = math.huge
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    if ao then
                                                                                                                                                                                                                        ao.Responsiveness = masslessSense
                                                                                                                                                                                                                        ao.MaxTorque = math.huge
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        GrabR:CreateSlider({
                                                                                                                                                                                                            Name = "Line Responsiveness",
                                                                                                                                                                                                            Flag = "MasslessSense",
