                                                                                                                                                                                                            Callback = function(v) masslessSense = v end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- Trigger Bot
                                                                                                                                                                                                        local triggerBotActive = false
                                                                                                                                                                                                        local triggerBotConn   = nil
                                                                                                                                                                                                        local triggerBotDist   = 20

                                                                                                                                                                                                        GrabR:CreateToggle({
                                                                                                                                                                                                            Name = "Trigger Bot",
                                                                                                                                                                                                            Flag = "TriggerBot",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                triggerBotActive = Value
                                                                                                                                                                                                                if triggerBotConn then triggerBotConn:Disconnect() triggerBotConn = nil end
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                local rayPrms = RaycastParams.new()
                                                                                                                                                                                                                rayPrms.FilterType = Enum.RaycastFilterType.Exclude
                                                                                                                                                                                                                local canGrab = true
                                                                                                                                                                                                                local lastCheck = 0
                                                                                                                                                                                                                triggerBotConn = R.Heartbeat:Connect(function()
                                                                                                                                                                                                                    if not triggerBotActive or not canGrab then return end
                                                                                                                                                                                                                    if U:GetFocusedTextBox() then return end
                                                                                                                                                                                                                    if tick() - lastCheck < 0.05 then return end
                                                                                                                                                                                                                    lastCheck = tick()
                                                                                                                                                                                                                    local char = LP.Character
                                                                                                                                                                                                                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not hrp then return end
                                                                                                                                                                                                                    if workspace:FindFirstChild("GrabParts") then return end
                                                                                                                                                                                                                    rayPrms.FilterDescendantsInstances = { char, workspace.Terrain }
                                                                                                                                                                                                                    local res = workspace:Raycast(Cam.CFrame.Position, Cam.CFrame.LookVector * 1000, rayPrms)
                                                                                                                                                                                                                    if not res then return end
                                                                                                                                                                                                                    local model = res.Instance:FindFirstAncestorOfClass("Model")
                                                                                                                                                                                                                    if not model or model == char then return end
                                                                                                                                                                                                                    local hum = model:FindFirstChildOfClass("Humanoid")
                                                                                                                                                                                                                    local root = model:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                    if not hum or hum.Health <= 0 or not root then return end
                                                                                                                                                                                                                    if (hrp.Position - root.Position).Magnitude > triggerBotDist then return end
                                                                                                                                                                                                                    canGrab = false
                                                                                                                                                                                                                    task.spawn(function()
                                                                                                                                                                                                                        if mouse1press then pcall(mouse1press) end
                                                                                                                                                                                                                        local t0 = tick()
                                                                                                                                                                                                                        repeat task.wait(0.02) until not workspace:FindFirstChild("GrabParts") or tick() - t0 > 1.6
                                                                                                                                                                                                                        canGrab = true
                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        GrabR:CreateSlider({
                                                                                                                                                                                                            Name = "Trigger Bot Distance",
                                                                                                                                                                                                            Flag = "TriggerBotDist",
                                                                                                                                                                                                            Min = 5, Max = 50, Default = 20,
                                                                                                                                                                                                            Callback = function(Value) triggerBotDist = Value end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- Gamepass: Free Reach / Further Reach
                                                                                                                                                                                                        local grabReachEnabled = false
                                                                                                                                                                                                        local grabReachDist    = 25

                                                                                                                                                                                                        local function ApplyGrabReach(range)
                                                                                                                                                                                                            grabReachDist = range
                                                                                                                                                                                                            pcall(function()
                                                                                                                                                                                                                local DataEvents = RS:FindFirstChild("DataEvents")
                                                                                                                                                                                                                if DataEvents then
                                                                                                                                                                                                                    DataEvents.UpdateLineColorsEvent:FireServer(ColorSequence.new({
                                                                                                                                                                                                                        ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 0, 0)),
                                                                                                                                                                                                                        ColorSequenceKeypoint.new(1, Color3.fromRGB(0, 255, 195)),
                                                                                                                                                                                                                    }))
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end)
                                                                                                                                                                                                            pcall(function()
                                                                                                                                                                                                                local GamepassEvents = RS:FindFirstChild("GamepassEvents")
                                                                                                                                                                                                                if GamepassEvents then
                                                                                                                                                                                                                    local Notifier = GamepassEvents:FindFirstChild("FurtherReachBoughtNotifier")
                                                                                                                                                                                                                    if Notifier and typeof(getconnections) == "function" then
                                                                                                                                                                                                                        for _, conn in pairs(getconnections(Notifier.OnClientEvent)) do
                                                                                                                                                                                                                            for i in debug.getupvalues(conn.Function) do
                                                                                                                                                                                                                                debug.setupvalue(conn.Function, i, range)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end)
                                                                                                                                                                                                        end

                                                                                                                                                                                                        PanelR:CreateToggle({
                                                                                                                                                                                                            Name = "Free Gamepass (Reach)",
                                                                                                                                                                                                            Flag = "FreeGamepass",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                if Value then
                                                                                                                                                                                                                    local Reach = Instance.new("BoolValue")
                                                                                                                                                                                                                    Reach.Name = "FartherReach"
                                                                                                                                                                                                                    Reach.Parent = LP
                                                                                                                                                                                                                    Reach.Value = true
                                                                                                                                                                                                                    local Notifier = RS:FindFirstChild("GamepassEvents")
                                                                                                                                                                                                                    if Notifier then
                                                                                                                                                                                                                        Notifier = Notifier:FindFirstChild("FurtherReachBoughtNotifier")
                                                                                                                                                                                                                        if Notifier and typeof(getconnections) == "function" then
                                                                                                                                                                                                                            for _, conn in pairs(getconnections(Notifier.OnClientEvent)) do
                                                                                                                                                                                                                                pcall(conn.Function)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                else
                                                                                                                                                                                                                    local Reach = LP:FindFirstChild("FartherReach")
                                                                                                                                                                                                                    if Reach then Reach:Destroy() end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        PanelR:CreateToggle({
                                                                                                                                                                                                            Name = "Further Reach",
                                                                                                                                                                                                            Flag = "FurtherReach",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(v)
                                                                                                                                                                                                                grabReachEnabled = v
                                                                                                                                                                                                                if v then ApplyGrabReach(grabReachDist) else ApplyGrabReach(25) end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        PanelR:CreateSlider({
                                                                                                                                                                                                            Name = "Reach Distance",
                                                                                                                                                                                                            Flag = "ReachDistance",
                                                                                                                                                                                                            Default = 25, Min = 25, Max = 45,
                                                                                                                                                                                                            Callback = function(v)
                                                                                                                                                                                                                grabReachDist = v
                                                                                                                                                                                                                if grabReachEnabled then ApplyGrabReach(v) end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

