                                                                                                                                                                                                            ["Bubble"]         = "rbxassetid://1249690853",
                                                                                                                                                                                                            ["Star"]           = "rbxassetid://5639840603",
                                                                                                                                                                                                            ["Robux"]          = "rbxassetid://11560341132",
                                                                                                                                                                                                            ["Roblox-Logo"]    = "rbxassetid://12348119032",
                                                                                                                                                                                                            ["Brick"]          = "rbxassetid://4430903072",
                                                                                                                                                                                                            ["Studs"]          = "rbxassetid://15539356451",
                                                                                                                                                                                                            ["Fire"]           = "rbxassetid://18654087326",
                                                                                                                                                                                                            ["Lazar"]          = "rbxassetid://8922958725",
                                                                                                                                                                                                            ["Spider-Web"]     = "rbxassetid://123815660139244",
                                                                                                                                                                                                            ["Smoke"]          = "rbxassetid://12900071392",
                                                                                                                                                                                                            ["Pulse"]          = "rbxassetid://82163767314193",
                                                                                                                                                                                                            ["Arrow"]          = "rbxassetid://9006027964",
                                                                                                                                                                                                            ["Arrow 2"]        = "rbxassetid://10249261576",
                                                                                                                                                                                                        }

                                                                                                                                                                                                        local CustomLineNames = {}
                                                                                                                                                                                                        for name in pairs(CustomLineTextures) do table.insert(CustomLineNames, name) end
                                                                                                                                                                                                        table.sort(CustomLineNames)

                                                                                                                                                                                                        local CurrentLineTexture = "Low Quality"
                                                                                                                                                                                                        local customLineEnabled  = false
                                                                                                                                                                                                        local lineColorEnabled   = false
                                                                                                                                                                                                        local lineColorA         = Color3.fromRGB(255, 255, 255)
                                                                                                                                                                                                        local lineColorB         = Color3.fromRGB(255, 255, 255)

                                                                                                                                                                                                        local function ApplyLineTexture()
                                                                                                                                                                                                            local url = CustomLineTextures[CurrentLineTexture] or ""
                                                                                                                                                                                                            pcall(function()
                                                                                                                                                                                                                local grabParts = workspace:FindFirstChild("GrabParts")
                                                                                                                                                                                                                if grabParts then
                                                                                                                                                                                                                    local beamPart = grabParts:FindFirstChild("BeamPart")
                                                                                                                                                                                                                    if beamPart then
                                                                                                                                                                                                                        local beam = beamPart:FindFirstChild("GrabBeam")
                                                                                                                                                                                                                        if beam and beam:IsA("Beam") then
                                                                                                                                                                                                                            beam.Texture = url
                                                                                                                                                                                                                            if lineColorEnabled then
                                                                                                                                                                                                                                beam.Color = ColorSequence.new(lineColorA, lineColorB)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end)
                                                                                                                                                                                                        end

                                                                                                                                                                                                        LineL:CreateDropdown({
                                                                                                                                                                                                            Name = "Custom Line",
                                                                                                                                                                                                            Flag = "CustomLineTexture",
                                                                                                                                                                                                            Items = CustomLineNames,
                                                                                                                                                                                                            Default = "Low Quality",
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                CurrentLineTexture = Value
                                                                                                                                                                                                                if customLineEnabled then ApplyLineTexture() end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        LineL:CreateToggle({
                                                                                                                                                                                                            Name = "Enable Custom Line",
                                                                                                                                                                                                            Flag = "CustomLineToggle",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                customLineEnabled = Value
                                                                                                                                                                                                                if Value then
                                                                                                                                                                                                                    ApplyLineTexture()
                                                                                                                                                                                                                    task.spawn(function()
                                                                                                                                                                                                                        while customLineEnabled do
                                                                                                                                                                                                                            ApplyLineTexture()
                                                                                                                                                                                                                            task.wait(0.5)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                else
                                                                                                                                                                                                                    ApplyLineTexture()
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        LineL:CreateColorPicker({
                                                                                                                                                                                                            Name = "Line Color A",
                                                                                                                                                                                                            Flag = "LineColorA",
                                                                                                                                                                                                            Default = Color3.fromRGB(255, 255, 255),
                                                                                                                                                                                                            Callback = function(c) lineColorA = c ApplyLineTexture() end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        LineL:CreateColorPicker({
                                                                                                                                                                                                            Name = "Line Color B",
                                                                                                                                                                                                            Flag = "LineColorB",
                                                                                                                                                                                                            Default = Color3.fromRGB(255, 255, 255),
                                                                                                                                                                                                            Callback = function(c) lineColorB = c ApplyLineTexture() end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        LineL:CreateToggle({
                                                                                                                                                                                                            Name = "Enable Line Color",
                                                                                                                                                                                                            Flag = "LineColorEnable",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(v)
                                                                                                                                                                                                                lineColorEnabled = v
                                                                                                                                                                                                                ApplyLineTexture()
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        workspace.DescendantAdded:Connect(function(obj)
                                                                                                                                                                                                            if not customLineEnabled then return end
                                                                                                                                                                                                            if obj:IsA("Beam") and obj.Name == "GrabBeam" then
                                                                                                                                                                                                                task.defer(ApplyLineTexture)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end)
                                                                                                                                                                                                    end

                                                                                                                                                                                                    -- ============================================================
                                                                                                                                                                                                    -- VISUALS TAB
                                                                                                                                                                                                    -- ============================================================
                                                                                                                                                                                                    do
                                                                                                                                                                                                        local VisL = Tabs.Visuals:CreateBlock({Name = "ESP", Side = "Left", ImageID = "112488114197106"})
                                                                                                                                                                                                        local VisR = Tabs.Visuals:CreateBlock({Name = "Customization", Side = "Right", ImageID = "112488114197106"})

                                                                                                                                                                                                        -- Player ESP
                                                                                                                                                                                                        local espEnabled     = false
                                                                                                                                                                                                        local espColor       = Color3.fromRGB(255, 255, 255)
                                                                                                                                                                                                        local espRainbow     = false
                                                                                                                                                                                                        local espConnections = {}
                                                                                                                                                                                                        local espObjects     = {}

                                                                                                                                                                                                        local function CreateESP(player)
                                                                                                                                                                                                            if not player or not player.Character then return end
                                                                                                                                                                                                            if espObjects[player] then return end
                                                                                                                                                                                                            local h = Instance.new("Highlight")
                                                                                                                                                                                                            h.Name = "TrueAmAmESP"
                                                                                                                                                                                                            h.FillTransparency = 1
                                                                                                                                                                                                            h.OutlineColor = espColor
                                                                                                                                                                                                            h.OutlineTransparency = 0
                                                                                                                                                                                                            h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                                                                                                                                                                                                            h.Adornee = player.Character
                                                                                                                                                                                                            h.Parent = player.Character
                                                                                                                                                                                                            espObjects[player] = h
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function ClearESP()
                                                                                                                                                                                                            for _, h in pairs(espObjects) do pcall(function() h:Destroy() end) end
                                                                                                                                                                                                            espObjects = {}
                                                                                                                                                                                                            for _, c in ipairs(espConnections) do pcall(function() c:Disconnect() end) end
                                                                                                                                                                                                            espConnections = {}
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function UpdateESPAll()
                                                                                                                                                                                                            ClearESP()
                                                                                                                                                                                                            if not espEnabled then return end
                                                                                                                                                                                                            for _, p in ipairs(P:GetPlayers()) do
                                                                                                                                                                                                                if p ~= LP then CreateESP(p) end
                                                                                                                                                                                                            end
                                                                                                                                                                                                            table.insert(espConnections, P.PlayerAdded:Connect(function(p)
                                                                                                                                                                                                                p.CharacterAdded:Connect(function()
                                                                                                                                                                                                                    task.wait(0.3)
                                                                                                                                                                                                                    if espEnabled then CreateESP(p) end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                                task.wait(0.3)
                                                                                                                                                                                                                if espEnabled then CreateESP(p) end
                                                                                                                                                                                                            end))
                                                                                                                                                                                                            table.insert(espConnections, P.PlayerRemoving:Connect(function(p)
                                                                                                                                                                                                                if espObjects[p] then
                                                                                                                                                                                                                    pcall(function() espObjects[p]:Destroy() end)
                                                                                                                                                                                                                    espObjects[p] = nil
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end))
                                                                                                                                                                                                        end

                                                                                                                                                                                                        VisL:CreateToggle({
                                                                                                                                                                                                            Name = "Player ESP",
                                                                                                                                                                                                            Flag = "ESPEnabled",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(v)
                                                                                                                                                                                                                espEnabled = v
                                                                                                                                                                                                                if v then UpdateESPAll() else ClearESP() end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        VisL:CreateColorPicker({
                                                                                                                                                                                                            Name = "ESP Color",
                                                                                                                                                                                                            Flag = "ESPColor",
                                                                                                                                                                                                            Default = Color3.fromRGB(255, 255, 255),
                                                                                                                                                                                                            Callback = function(c)
                                                                                                                                                                                                                espColor = c
                                                                                                                                                                                                                if not espRainbow then
                                                                                                                                                                                                                    for _, h in pairs(espObjects) do pcall(function() h.OutlineColor = c end) end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        VisL:CreateToggle({
                                                                                                                                                                                                            Name = "ESP Rainbow",
                                                                                                                                                                                                            Flag = "ESPRainbow",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(v)
                                                                                                                                                                                                                espRainbow = v
                                                                                                                                                                                                                if not v then
                                                                                                                                                                                                                    for _, h in pairs(espObjects) do pcall(function() h.OutlineColor = espColor end) end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- PCLD ESP
                                                                                                                                                                                                        local pcldEnabled = false
                                                                                                                                                                                                        local pcldColor   = Color3.fromRGB(255, 60, 60)
                                                                                                                                                                                                        local pcldRainbow = false
                                                                                                                                                                                                        local pcldBoxes   = {}
                                                                                                                                                                                                        local pcldConns   = {}

                                                                                                                                                                                                        local function IsPCLD(obj)
                                                                                                                                                                                                            if not obj:IsA("BasePart") then return false end
                                                                                                                                                                                                            local n = string.lower(obj.Name)
                                                                                                                                                                                                            return n == "playercharacterlocationdetector" or n == "partesp"
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function AddPCLDBox(obj)
                                                                                                                                                                                                            if pcldBoxes[obj] then return end
                                                                                                                                                                                                            local box = Instance.new("BoxHandleAdornment")
                                                                                                                                                                                                            box.Adornee = obj box.AlwaysOnTop = true box.ZIndex = 5
                                                                                                                                                                                                            box.Color3 = pcldColor box.Transparency = 0.3 box.Size = obj.Size
                                                                                                                                                                                                            box.Parent = game.CoreGui
                                                                                                                                                                                                            pcldBoxes[obj] = box
                                                                                                                                                                                                            table.insert(pcldConns, obj.AncestryChanged:Connect(function(_, parent)
                                                                                                                                                                                                                if not parent and pcldBoxes[obj] then
                                                                                                                                                                                                                    pcall(function() pcldBoxes[obj]:Destroy() end)
                                                                                                                                                                                                                    pcldBoxes[obj] = nil
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end))
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function ClearPCLD()
                                                                                                                                                                                                            for _, box in pairs(pcldBoxes) do pcall(function() box:Destroy() end) end
                                                                                                                                                                                                            pcldBoxes = {}
                                                                                                                                                                                                            for _, c in ipairs(pcldConns) do pcall(function() c:Disconnect() end) end
                                                                                                                                                                                                            pcldConns = {}
                                                                                                                                                                                                        end

                                                                                                                                                                                                        VisL:CreateToggle({
                                                                                                                                                                                                            Name = "PCLD ESP",
                                                                                                                                                                                                            Flag = "PCLDEnabled",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(v)
                                                                                                                                                                                                                pcldEnabled = v
                                                                                                                                                                                                                if v then
                                                                                                                                                                                                                    for _, obj in ipairs(workspace:GetDescendants()) do
                                                                                                                                                                                                                        if IsPCLD(obj) then AddPCLDBox(obj) end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    table.insert(pcldConns, workspace.DescendantAdded:Connect(function(obj)
                                                                                                                                                                                                                        if pcldEnabled and IsPCLD(obj) then AddPCLDBox(obj) end
                                                                                                                                                                                                                    end))
                                                                                                                                                                                                                else
                                                                                                                                                                                                                    ClearPCLD()
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        VisL:CreateColorPicker({
                                                                                                                                                                                                            Name = "PCLD Color",
                                                                                                                                                                                                            Flag = "PCLDColor",
                                                                                                                                                                                                            Default = Color3.fromRGB(255, 60, 60),
                                                                                                                                                                                                            Callback = function(c)
                                                                                                                                                                                                                pcldColor = c
                                                                                                                                                                                                                if not pcldRainbow then
                                                                                                                                                                                                                    for _, box in pairs(pcldBoxes) do pcall(function() box.Color3 = c end) end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        VisL:CreateToggle({
                                                                                                                                                                                                            Name = "PCLD Rainbow",
                                                                                                                                                                                                            Flag = "PCLDRainbow",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(v)
                                                                                                                                                                                                                pcldRainbow = v
                                                                                                                                                                                                                if not v then
                                                                                                                                                                                                                    for _, box in pairs(pcldBoxes) do pcall(function() box.Color3 = pcldColor end) end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- Sticky ESP
                                                                                                                                                                                                        local stickyEnabled = false
                                                                                                                                                                                                        local stickyColor   = Color3.fromRGB(255, 60, 60)
                                                                                                                                                                                                        local stickyConns   = {}
                                                                                                                                                                                                        local stickyHls     = {}

                                                                                                                                                                                                        local function IsSticky(obj)
                                                                                                                                                                                                            if not obj:IsA("BasePart") then return false end
                                                                                                                                                                                                            return string.find(string.lower(obj.Name), "sticky") ~= nil
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function AddStickyHl(part)
                                                                                                                                                                                                            if not part or not part.Parent then return end
                                                                                                                                                                                                            if stickyHls[part] then return end
                                                                                                                                                                                                            local h = Instance.new("Highlight")
                                                                                                                                                                                                            h.Name = "TrueAmAmStickyESP"
                                                                                                                                                                                                            h.FillColor = stickyColor h.FillTransparency = 0.5
                                                                                                                                                                                                            h.OutlineColor = stickyColor h.OutlineTransparency = 0
                                                                                                                                                                                                            h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                                                                                                                                                                                                            h.Adornee = part h.Parent = part
                                                                                                                                                                                                            stickyHls[part] = h
                                                                                                                                                                                                        end

                                                                                                                                                                                                        VisL:CreateToggle({
                                                                                                                                                                                                            Name = "Sticky ESP",
                                                                                                                                                                                                            Flag = "StickyESP",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(v)
                                                                                                                                                                                                                stickyEnabled = v
                                                                                                                                                                                                                if v then
                                                                                                                                                                                                                    for _, obj in ipairs(workspace:GetDescendants()) do
                                                                                                                                                                                                                        if IsSticky(obj) then AddStickyHl(obj) end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    table.insert(stickyConns, workspace.DescendantAdded:Connect(function(obj)
                                                                                                                                                                                                                        if stickyEnabled and IsSticky(obj) then
                                                                                                                                                                                                                            task.defer(function() if obj and obj.Parent then AddStickyHl(obj) end end)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end))
                                                                                                                                                                                                                else
                                                                                                                                                                                                                    for part, h in pairs(stickyHls) do pcall(function() h:Destroy() end) end
                                                                                                                                                                                                                    stickyHls = {}
                                                                                                                                                                                                                    for _, c in ipairs(stickyConns) do pcall(function() c:Disconnect() end) end
                                                                                                                                                                                                                    stickyConns = {}
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        VisL:CreateColorPicker({
                                                                                                                                                                                                            Name = "Sticky ESP Color",
                                                                                                                                                                                                            Flag = "StickyColor",
                                                                                                                                                                                                            Default = Color3.fromRGB(255, 60, 60),
                                                                                                                                                                                                            Callback = function(c)
                                                                                                                                                                                                                stickyColor = c
                                                                                                                                                                                                                for _, h in pairs(stickyHls) do
                                                                                                                                                                                                                    pcall(function() h.FillColor = c h.OutlineColor = c end)
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- Rainbow updater
                                                                                                                                                                                                        task.spawn(function()
                                                                                                                                                                                                            while true do
                                                                                                                                                                                                                task.wait(0.05)
                                                                                                                                                                                                                local c = Color3.fromHSV(tick() % 1, 1, 1)
                                                                                                                                                                                                                if espRainbow and espEnabled then
                                                                                                                                                                                                                    for _, h in pairs(espObjects) do pcall(function() h.OutlineColor = c end) end
                                                                                                                                                                                                                end
                                                                                                                                                                                                                if pcldRainbow and pcldEnabled then
                                                                                                                                                                                                                    for _, box in pairs(pcldBoxes) do pcall(function() box.Color3 = c end) end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end)

