                                                                                                                                                                                                            Min = 100, Max = 5000, Default = 500,
                                                                                                                                                                                                            Callback = function(v) lineAmount = v end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        ServL:CreateToggle({
                                                                                                                                                                                                            Name = "Line Lag",
