                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                lineLagActive = Value
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                task.spawn(function()
                                                                                                                                                                                                                    local CreateLine = RS:FindFirstChild("GrabEvents") and RS.GrabEvents:FindFirstChild("CreateGrabLine")
                                                                                                                                                                                                                    if not CreateLine then return end
                                                                                                                                                                                                                    while lineLagActive do
