                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        ServL:CreateToggle({
                                                                                                                                                                                                            Name = "Packet Lag (Loop)",
                                                                                                                                                                                                            Flag = "PacketLag",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                packetLagActive = Value
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                task.spawn(function()
                                                                                                                                                                                                                    local ExtendGrabLine = RS:FindFirstChild("GrabEvents") and RS.GrabEvents:FindFirstChild("ExtendGrabLine")
                                                                                                                                                                                                                    if not ExtendGrabLine then return end
                                                                                                                                                                                                                    while packetLagActive do
                                                                                                                                                                                                                        task.wait(1)
                                                                                                                                                                                                                        pcall(function()
                                                                                                                                                                                                                            ExtendGrabLine:FireServer(string.rep("metaballs ", 100 * packetLagStrength))
                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

