                                                                                                                                                                                                        ServR:CreateDropdown({
                                                                                                                                                                                                            Name = "Destroy Height",
                                                                                                                                                                                                            Flag = "DestroyHeight",
                                                                                                                                                                                                            Items = {"Spawn", "Heaven"},
                                                                                                                                                                                                            Default = "Spawn",
                                                                                                                                                                                                            Callback = function(Value) end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        ServR:CreateButton({
                                                                                                                                                                                                            Name = "Destroy Server (Kick All)",
                                                                                                                                                                                                            Callback = function()
                                                                                                                                                                                                                task.spawn(function()
                                                                                                                                                                                                                    local GrabEvents = RS:FindFirstChild("GrabEvents")
                                                                                                                                                                                                                    local SetNetOwner = GrabEvents and GrabEvents:FindFirstChild("SetNetworkOwner")
                                                                                                                                                                                                                    local CreateLine = GrabEvents and GrabEvents:FindFirstChild("CreateGrabLine")
                                                                                                                                                                                                                    if not (SetNetOwner and CreateLine) then return end
                                                                                                                                                                                                                    for _, plr in ipairs(P:GetPlayers()) do
                                                                                                                                                                                                                        if plr ~= LP and plr.Character and not IsFriend(plr) then
                                                                                                                                                                                                                            local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                            if hrp then
                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                    SetNetOwner:FireServer(hrp, hrp.CFrame)
                                                                                                                                                                                                                                    CreateLine:FireServer(hrp, CFrame.new(0, 1e9, 0))
                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        ServR:CreateButton({
                                                                                                                                                                                                            Name = "Blobman Kick All",
                                                                                                                                                                                                            Callback = function()
                                                                                                                                                                                                                task.spawn(function()
                                                                                                                                                                                                                    local char = LP.Character
                                                                                                                                                                                                                    local hum = char and char:FindFirstChild("Humanoid")
                                                                                                                                                                                                                    if not hum or not hum.SeatPart then
                                                                                                                                                                                                                        Notify("true am am", "Сначала сядь на блобмана!", 3)
                                                                                                                                                                                                                        return
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    local blob = hum.SeatPart.Parent
                                                                                                                                                                                                                    if blob.Name ~= "CreatureBlobman" then return end
                                                                                                                                                                                                                    local scriptObj = blob:FindFirstChild("BlobmanSeatAndOwnerScript")
                                                                                                                                                                                                                    local grab = scriptObj and scriptObj:FindFirstChild("CreatureGrab")
                                                                                                                                                                                                                    local release = scriptObj and scriptObj:FindFirstChild("CreatureRelease")
                                                                                                                                                                                                                    local R_Det = blob:FindFirstChild("RightDetector")
                                                                                                                                                                                                                    local R_Weld = R_Det and R_Det:FindFirstChild("RightWeld")
                                                                                                                                                                                                                    if not (grab and release and R_Weld) then return end
                                                                                                                                                                                                                    for _, plr in ipairs(P:GetPlayers()) do
                                                                                                                                                                                                                        if plr ~= LP and plr.Character and not IsFriend(plr) then
                                                                                                                                                                                                                            local tRoot = plr.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                            local tHum = plr.Character:FindFirstChild("Humanoid")
                                                                                                                                                                                                                            if tRoot and tHum and tHum.Health > 0 then
                                                                                                                                                                                                                                for _ = 1, 5 do
                                                                                                                                                                                                                                    pcall(function()
                                                                                                                                                                                                                                        grab:FireServer(R_Det, tRoot, R_Weld)
                                                                                                                                                                                                                                        task.wait(0.03)
                                                                                                                                                                                                                                        release:FireServer(R_Weld, tRoot)
                                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                                    task.wait(0.03)
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })
                                                                                                                                                                                                    end

