                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- SPAWN TOY
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local ToyFriendlyNames = {
                                                                                                                                                                                                            PalletLightBrown = 'Pallet', BallSnowball = 'Snowball',
                                                                                                                                                                                                            BombBalloon = 'Balloon Bomb', BombDarkMatter = 'Dark Matter Bomb',
                                                                                                                                                                                                            BombMissile = 'Missile', CreatureBlobman = 'Blobman',
                                                                                                                                                                                                            CreatureRobot = 'Robot', NinjaKunai = 'Kunai',
                                                                                                                                                                                                            NinjaShuriken = 'Shuriken', ToolCleaver = 'Cleaver',
                                                                                                                                                                                                            ToolPencil = 'Pencil', ToolPickaxe = 'Pickaxe',
                                                                                                                                                                                                            TractorGreen = 'Tractor (Green)', TractorOrange = 'Tractor (Orange)',
                                                                                                                                                                                                            TractorRed = 'Tractor (Red)', YouDecoy = 'Decoy', YouLittle = 'Mini Me',
                                                                                                                                                                                                            FoodBanana = 'Banana', FoodBread = 'Bread', FoodCakePink = 'Pink Cake',
                                                                                                                                                                                                            FoodCoconut = 'Coconut', FoodDippyEgg = 'Dippy Egg', FoodDonut = 'Donut',
                                                                                                                                                                                                            FoodFrenchFries = 'French Fries', FoodHamburger = 'Burger',
                                                                                                                                                                                                            FoodHotdog = 'Hotdog', FoodMayonnaise = 'Mayo', FoodMeatStick = 'Meat Stick',
                                                                                                                                                                                                            FoodMushroomPoison = 'Poison Mushroom', FoodPizzaCheese = 'Cheese Pizza',
                                                                                                                                                                                                            FoodPizzaPepperoni = 'Pepperoni Pizza',
                                                                                                                                                                                                            InstrumentGuitarBanjo = 'Banjo', InstrumentGuitarViolin = 'Violin',
                                                                                                                                                                                                            InstrumentGuitarUkulele = 'Ukulele', InstrumentWoodwindSaxophone = 'Saxophone',
                                                                                                                                                                                                            InstrumentWoodwindOcarina = 'Ocarina', InstrumentBrassTrumpet = 'Trumpet',
                                                                                                                                                                                                            InstrumentDrumBongos = 'Bongos', InstrumentDrumSnare = 'Snare Drum',
                                                                                                                                                                                                            InstrumentPianoMelodica = 'Melodica', InstrumentVoiceMicrophone = 'Microphone',
                                                                                                                                                                                                            CupMugBrown = 'Mug (Brown)', CupMugWhite = 'Mug (White)',
                                                                                                                                                                                                            PoopPile = 'Poop', PoopPileSparkle = 'Sparkle Poop',
                                                                                                                                                                                                            SprayCanWD = 'Spray Can', SpookyCandle1 = 'Candle (x1)',
                                                                                                                                                                                                            JapaneseLantern = 'Japanese Lantern', FireworkSparkler = 'Sparkler',
                                                                                                                                                                                                        }
                                                                                                                                                                                                        local ToyDropdownValues = {}
                                                                                                                                                                                                        local DisplayToInternal = {}
                                                                                                                                                                                                        for internalName, displayName in pairs(ToyFriendlyNames) do
                                                                                                                                                                                                            table.insert(ToyDropdownValues, displayName)
                                                                                                                                                                                                            DisplayToInternal[displayName] = internalName
                                                                                                                                                                                                        end
                                                                                                                                                                                                        table.sort(ToyDropdownValues)

                                                                                                                                                                                                        local SelectedToy = "PalletLightBrown"
                                                                                                                                                                                                        local SpawnToyToggleValue = false

                                                                                                                                                                                                        ToySpawn:CreateDropdown({
                                                                                                                                                                                                            Name = "Selected Toy",
                                                                                                                                                                                                            Flag = "SpawnToyDropdown",
                                                                                                                                                                                                            Items = ToyDropdownValues,
                                                                                                                                                                                                            Default = "Pallet",
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                SelectedToy = DisplayToInternal[Value] or "PalletLightBrown"
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        ToySpawn:CreateToggle({
                                                                                                                                                                                                            Name = "Spawn Toy",
                                                                                                                                                                                                            Flag = "SpawnToyToggle",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(v) SpawnToyToggleValue = v end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        ToySpawn:CreateKeybind({
                                                                                                                                                                                                            Name = "Spawn Keybind",
                                                                                                                                                                                                            Flag = "SpawnToyKeybind",
                                                                                                                                                                                                            Default = Enum.KeyCode.Tab,
                                                                                                                                                                                                            Callback = function()
                                                                                                                                                                                                                if not SpawnToyToggleValue then return end
                                                                                                                                                                                                                local char = LP.Character
                                                                                                                                                                                                                local camPart = char and char:FindFirstChild("CamPart")
                                                                                                                                                                                                                if not camPart then return end
                                                                                                                                                                                                                if _G.SpawnToy_Def then
                                                                                                                                                                                                                    pcall(function()
                                                                                                                                                                                                                        _G.SpawnToy_Def:InvokeServer(SelectedToy, camPart.CFrame, Vector3.new(0, camPart.Orientation.Y, 0))
                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- OBJECT FLINGER
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local flingerSelectedPlayers = {}
                                                                                                                                                                                                        local flingerToy = "DiceBig"
                                                                                                                                                                                                        local flingerEnabled = false
                                                                                                                                                                                                        local flingerConnection = nil

                                                                                                                                                                                                        local function FlingerGetTargets()
                                                                                                                                                                                                            local list = {}
                                                                                                                                                                                                            for _, p in ipairs(P:GetPlayers()) do
                                                                                                                                                                                                                if p ~= LP and flingerSelectedPlayers[p.Name] then
                                                                                                                                                                                                                    table.insert(list, p)
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                            return list
                                                                                                                                                                                                        end

                                                                                                                                                                                                        ObjectFlinger:CreateDropdown({
                                                                                                                                                                                                            Name = "Select Players",
                                                                                                                                                                                                            Flag = "FlingerPlayers",
                                                                                                                                                                                                            Items = _G.TrueAmAm_PlayerList(),
                                                                                                                                                                                                            Default = "No players",
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                flingerSelectedPlayers = {}
                                                                                                                                                                                                                if type(Value) == "table" then
                                                                                                                                                                                                                    for k, v in pairs(Value) do
                                                                                                                                                                                                                        if v then
                                                                                                                                                                                                                            local name = _G.TrueAmAm_ParseName(k)
                                                                                                                                                                                                                            if name then flingerSelectedPlayers[name] = true end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                else
                                                                                                                                                                                                                    local name = _G.TrueAmAm_ParseName(Value)
                                                                                                                                                                                                                    if name then flingerSelectedPlayers[name] = true end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        ObjectFlinger:CreateDropdown({
                                                                                                                                                                                                            Name = "Fling Toy",
                                                                                                                                                                                                            Flag = "FlingerToy",
                                                                                                                                                                                                            Items = {"YouLittle", "YouDecoy", "DiceSmall", "DiceBig"},
                                                                                                                                                                                                            Default = "DiceBig",
                                                                                                                                                                                                            Callback = function(v) flingerToy = v end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        ObjectFlinger:CreateToggle({
                                                                                                                                                                                                            Name = "Loop Fling Target",
                                                                                                                                                                                                            Flag = "FlingerToggle",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                flingerEnabled = Value
                                                                                                                                                                                                                if flingerConnection then flingerConnection:Disconnect() flingerConnection = nil end
                                                                                                                                                                                                                if not Value then
                                                                                                                                                                                                                    local folder = workspace:FindFirstChild(LP.Name .. "SpawnedInToys")
                                                                                                                                                                                                                    if folder then
                                                                                                                                                                                                                        for _, v in pairs(folder:GetChildren()) do
                                                                                                                                                                                                                            if v.Name == flingerToy or v.Name == "FlingerDecoy" then
                                                                                                                                                                                                                                pcall(function() if _G.DestroyToy_Def then _G.DestroyToy_Def:FireServer(v) end end)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    return
                                                                                                                                                                                                                end

                                                                                                                                                                                                                local currentDecoy = nil
                                                                                                                                                                                                                local currentTarget = nil
                                                                                                                                                                                                                local flungMap = {}
                                                                                                                                                                                                                local UNIQUE_ATTR = "TrueAmAmFlinger"

                                                                                                                                                                                                                local function spawnFlingerDecoy()
                                                                                                                                                                                                                    if currentDecoy and currentDecoy.Parent then return end
                                                                                                                                                                                                                    if _G.SpawnToy_Def then
                                                                                                                                                                                                                        local root = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        if root then
                                                                                                                                                                                                                            pcall(function()
                                                                                                                                                                                                                                _G.SpawnToy_Def:InvokeServer(flingerToy, root.CFrame * CFrame.new(5, 0, 5), Vector3.new(0, 33, 0))
                                                                                                                                                                                                                            end)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end

                                                                                                                                                                                                                task.spawn(function()
                                                                                                                                                                                                                    while flingerEnabled do
                                                                                                                                                                                                                        task.wait(0.1)
                                                                                                                                                                                                                        if not currentDecoy or not currentDecoy.Parent then
                                                                                                                                                                                                                            local folder = workspace:FindFirstChild(LP.Name .. "SpawnedInToys")
                                                                                                                                                                                                                            if folder then
                                                                                                                                                                                                                                for _, v in pairs(folder:GetChildren()) do
                                                                                                                                                                                                                                    if v.Name == flingerToy and not v:GetAttribute(UNIQUE_ATTR) then
                                                                                                                                                                                                                                        v:SetAttribute(UNIQUE_ATTR, true)
                                                                                                                                                                                                                                        v.Name = "FlingerDecoy"
                                                                                                                                                                                                                                        currentDecoy = v
                                                                                                                                                                                                                                        break
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        if not currentDecoy then spawnFlingerDecoy() end
                                                                                                                                                                                                                        if currentDecoy and currentDecoy.Parent then
                                                                                                                                                                                                                            local hrp = currentDecoy:FindFirstChild("HumanoidRootPart") or currentDecoy.PrimaryPart or currentDecoy:FindFirstChildWhichIsA("BasePart")
                                                                                                                                                                                                                            if hrp then
                                                                                                                                                                                                                                hrp.CanCollide = false
                                                                                                                                                                                                                                local targets = FlingerGetTargets()
                                                                                                                                                                                                                                if #targets > 0 then
                                                                                                                                                                                                                                    if not currentTarget or not currentTarget.Character then
                                                                                                                                                                                                                                        currentTarget = targets[math.random(1, #targets)]
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                    if currentTarget and currentTarget.Character then
                                                                                                                                                                                                                                        local tHRP = currentTarget.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                                        if tHRP then
                                                                                                                                                                                                                                            for _, part in pairs(currentDecoy:GetDescendants()) do
                                                                                                                                                                                                                                                if part:IsA("BasePart") then
                                                                                                                                                                                                                                                    pcall(function() part.CFrame = tHRP.CFrame end)
                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                else
                                                                                                                                                                                                                                    local root = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                                    if root then
                                                                                                                                                                                                                                        pcall(function() currentDecoy:PivotTo(root.CFrame * CFrame.new(0, 20, 5)) end)
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- SPARKLER AURAS
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local activeSparklers = {}
                                                                                                                                                                                                        local sparklerConfig = {
