                                                                                                                                                                                                        local function GetSparklerOffset(index, total, t, cfg)
                                                                                                                                                                                                            local a = (index / total) * math.pi * 2 + t * cfg.Speed
                                                                                                                                                                                                            local shape = cfg.CurrentShape
                                                                                                                                                                                                            local r, h = cfg.Radius, cfg.Height
                                                                                                                                                                                                            if shape == "Sphere" then
                                                                                                                                                                                                                local phi = math.acos(1 - 2 * (index / total))
                                                                                                                                                                                                                local theta = index * math.pi * (3 - math.sqrt(5)) + t * cfg.Speed * 2
                                                                                                                                                                                                                return Vector3.new(math.cos(theta) * math.sin(phi) * r, math.cos(phi) * r + h, math.sin(theta) * math.sin(phi) * r)
                                                                                                                                                                                                            elseif shape == "Cylinder" then
                                                                                                                                                                                                                local y = (index / total) * r * 1.5 - r * 0.75
                                                                                                                                                                                                                return Vector3.new(math.cos(a) * r, h + y, math.sin(a) * r)
                                                                                                                                                                                                            elseif shape == "Double Ring" then
                                                                                                                                                                                                                if index % 2 == 0 then
                                                                                                                                                                                                                    return Vector3.new(math.cos(a) * r, h, math.sin(a) * r)
                                                                                                                                                                                                                else
                                                                                                                                                                                                                    return Vector3.new(0, h + math.cos(a) * r, math.sin(a) * r)
                                                                                                                                                                                                                end
                                                                                                                                                                                                            elseif shape == "Star" then
                                                                                                                                                                                                                local rr = (index % 2 == 0) and r or r * 0.38
                                                                                                                                                                                                                return Vector3.new(math.cos(a) * rr, h + math.sin(t * cfg.Speed * 1.5 + index * 0.3) * 1.5, math.sin(a) * rr)
                                                                                                                                                                                                            elseif shape == "Heart" then
                                                                                                                                                                                                                local scale = (r / 15) * (1 + 0.12 * math.sin(t * cfg.Speed * 2))
                                                                                                                                                                                                                local x = 16 * math.sin(a) ^ 3
                                                                                                                                                                                                                local z = -(13 * math.cos(a) - 5 * math.cos(2 * a) - 2 * math.cos(3 * a) - math.cos(4 * a))
                                                                                                                                                                                                                return Vector3.new(x * scale, h + math.sin(t * cfg.Speed * 2) * 0.5, z * scale)
                                                                                                                                                                                                            elseif shape == "DNA Helix" then
                                                                                                                                                                                                                local y = (index / total) * r * 2 - r
                                                                                                                                                                                                                local aa = a + y * 0.5
                                                                                                                                                                                                                local side = (index % 2 == 0) and 1 or -1
                                                                                                                                                                                                                return Vector3.new(math.cos(aa) * r * side, h + y, math.sin(aa) * r * side)
                                                                                                                                                                                                            elseif shape == "Triple Helix" then
                                                                                                                                                                                                                local y = (index / total) * r * 2 - r
                                                                                                                                                                                                                local aa = a + y * 0.5
                                                                                                                                                                                                                local phase = (index % 3) * (math.pi * 2 / 3)
                                                                                                                                                                                                                return Vector3.new(math.cos(aa + phase) * r, h + y, math.sin(aa + phase) * r)
                                                                                                                                                                                                            elseif shape == "Tornado" then
                                                                                                                                                                                                                local y = (index / total) * r * 2 - r
                                                                                                                                                                                                                local rr = ((y + r) / (r * 2)) * r + 2
                                                                                                                                                                                                                local aa = a + y * 0.5
                                                                                                                                                                                                                return Vector3.new(math.cos(aa) * rr, h + y, math.sin(aa) * rr)
                                                                                                                                                                                                            elseif shape == "Galaxy Spiral" then
                                                                                                                                                                                                                local frac = index / total
                                                                                                                                                                                                                local aa = frac * 12 + t * cfg.Speed
                                                                                                                                                                                                                return Vector3.new(math.cos(aa) * r * (frac ^ 1.5), h + math.sin(t * cfg.Speed * 2 + frac * 10), math.sin(aa) * r * (frac ^ 1.5))
                                                                                                                                                                                                            elseif shape == "Spring Coil" then
                                                                                                                                                                                                                local frac = index / total
                                                                                                                                                                                                                local aa = frac * math.pi * 2 * 5 + t * cfg.Speed
                                                                                                                                                                                                                local y = frac * r * 2 - r
                                                                                                                                                                                                                return Vector3.new(math.cos(aa) * r * 0.5, h + y, math.sin(aa) * r * 0.5)
                                                                                                                                                                                                            elseif shape == "Vortex Funnel" then
                                                                                                                                                                                                                local frac = index / total
                                                                                                                                                                                                                local aa = frac * math.pi * 2 * 4 + t * cfg.Speed
                                                                                                                                                                                                                local rr = frac * r
                                                                                                                                                                                                                local y = (1 - frac) * r * 1.5
                                                                                                                                                                                                                return Vector3.new(math.cos(aa) * rr, h + y, math.sin(aa) * rr)
                                                                                                                                                                                                            else
                                                                                                                                                                                                                return Vector3.new(math.cos(a) * r, h, math.sin(a) * r)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end

                                                                                                                                                                                                        R.RenderStepped:Connect(function()
                                                                                                                                                                                                            local char = LP.Character
                                                                                                                                                                                                            local targetRoot = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                            if not targetRoot then return end
                                                                                                                                                                                                            local t = tick()
                                                                                                                                                                                                            local prediction = targetRoot.AssemblyLinearVelocity * 0.12
                                                                                                                                                                                                            local rot = targetRoot.CFrame.Rotation
                                                                                                                                                                                                            for i = #activeSparklers, 1, -1 do
                                                                                                                                                                                                                local obj = activeSparklers[i]
                                                                                                                                                                                                                if obj and obj.Parent then
                                                                                                                                                                                                                    local main = obj:IsA("BasePart") and obj or obj.PrimaryPart
                                                                                                                                                                                                                    if main then
                                                                                                                                                                                                                        local offset = GetSparklerOffset(i, #activeSparklers, t, sparklerConfig)
                                                                                                                                                                                                                        main.CFrame = CFrame.new(targetRoot.Position + prediction + (rot * offset))
                                                                                                                                                                                                                        if _G.SetNetOwner_Def then
                                                                                                                                                                                                                            pcall(function() _G.SetNetOwner_Def:FireServer(main, main.CFrame) end)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                else
                                                                                                                                                                                                                    table.remove(activeSparklers, i)
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end)

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- COCONUTS
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local CoconutBodyEnabled = false
                                                                                                                                                                                                        local CoconutOrbitEnabled = false
                                                                                                                                                                                                        local CoconutAmount = 10

                                                                                                                                                                                                        CocoGroup:CreateSlider({
                                                                                                                                                                                                            Name = "Coconut Amount",
                                                                                                                                                                                                            Flag = "CoconutAmount",
                                                                                                                                                                                                            Min = 3, Max = 25, Default = 10,
                                                                                                                                                                                                            Callback = function(v) CoconutAmount = v end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        CocoGroup:CreateToggle({
                                                                                                                                                                                                            Name = "Coconut Body Parts",
                                                                                                                                                                                                            Flag = "CoconutBody",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                CoconutBodyEnabled = Value
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                task.spawn(function()
                                                                                                                                                                                                                    while CoconutBodyEnabled do
                                                                                                                                                                                                                        local char = LP.Character
                                                                                                                                                                                                                        local root = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        if not root then task.wait(0.1) continue end
                                                                                                                                                                                                                        local folder = workspace:FindFirstChild(LP.Name .. "SpawnedInToys")
                                                                                                                                                                                                                        if not folder then task.wait(0.1) continue end
                                                                                                                                                                                                                        local coconuts = {}
                                                                                                                                                                                                                        for _, v in pairs(folder:GetChildren()) do
                                                                                                                                                                                                                            if v.Name == "FoodCoconut" then table.insert(coconuts, v) end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        if #coconuts < 4 then
                                                                                                                                                                                                                            for _ = 1, 4 - #coconuts do
                                                                                                                                                                                                                                if _G.SpawnToy_Def then
                                                                                                                                                                                                                                    pcall(function() _G.SpawnToy_Def:InvokeServer("FoodCoconut", root.CFrame * CFrame.new(-5, 0, 10), Vector3.zero) end)
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        for i = 1, math.min(4, #coconuts) do
                                                                                                                                                                                                                            local c = coconuts[i]
                                                                                                                                                                                                                            local part = c:FindFirstChild("SoundPart")
                                                                                                                                                                                                                            local holdPart = c:FindFirstChild("HoldPart")
                                                                                                                                                                                                                            local rigid = holdPart and holdPart:FindFirstChild("RigidConstraint")
                                                                                                                                                                                                                            if part then
                                                                                                                                                                                                                                local po = part:FindFirstChild("PartOwner")
                                                                                                                                                                                                                                if po and po.Value == LP.Name then
                                                                                                                                                                                                                                    local targetCF
                                                                                                                                                                                                                                    if i == 1 then targetCF = root.CFrame * CFrame.new(-0.4, 0.3, -0.55)
                                                                                                                                                                                                                                    elseif i == 2 then targetCF = root.CFrame * CFrame.new(0.4, 0.3, -0.55)
                                                                                                                                                                                                                                    elseif i == 3 then targetCF = root.CFrame * CFrame.new(-0.35, -1.1, 0.45)
                                                                                                                                                                                                                                    else targetCF = root.CFrame * CFrame.new(0.35, -1.1, 0.45) end
                                                                                                                                                                                                                                    part.CFrame = targetCF
                                                                                                                                                                                                                                    part.Velocity = Vector3.zero
                                                                                                                                                                                                                                else
                                                                                                                                                                                                                                    if _G.SetNetOwner_Def then _G.SetNetOwner_Def:FireServer(part, part.CFrame) end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                if rigid and rigid.Attachment1 then
                                                                                                                                                                                                                                    if _G.DestroyToy_Def then _G.DestroyToy_Def:FireServer(c) end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                for _, po2 in ipairs(c:GetChildren()) do
                                                                                                                                                                                                                                    if po2:IsA("BasePart") then
                                                                                                                                                                                                                                        po2.CanCollide = false
                                                                                                                                                                                                                                        po2.CanQuery = false
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        task.wait(0.01)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        -- AUTO EXPLODE
                                                                                                                                                                                                        -- ============================================
                                                                                                                                                                                                        local ExplosionType = "BombMissile"
                                                                                                                                                                                                        local ExplosionAmount = 3
                                                                                                                                                                                                        local ExplosionInterval = 0
                                                                                                                                                                                                        local PredictMovement = false
                                                                                                                                                                                                        local _expTarget = nil
                                                                                                                                                                                                        local AutoExplosionEnabled = false

                                                                                                                                                                                                        ExplodeGroup:CreateDropdown({
                                                                                                                                                                                                            Name = "Target",
                                                                                                                                                                                                            Flag = "ExplosionTarget",
                                                                                                                                                                                                            Items = _G.TrueAmAm_PlayerList(),
                                                                                                                                                                                                            Default = "No players",
                                                                                                                                                                                                            Callback = function(v)
                                                                                                                                                                                                                _expTarget = _G.TrueAmAm_ParseName(v)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        ExplodeGroup:CreateDropdown({
                                                                                                                                                                                                            Name = "Explosion Type",
                                                                                                                                                                                                            Flag = "ExplosionType",
                                                                                                                                                                                                            Items = {"Missile", "Firework", "Void", "Balloon", "Small Present", "Big Present"},
                                                                                                                                                                                                            Default = "Missile",
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                local typeMap = {
                                                                                                                                                                                                                    Missile = "BombMissile", Firework = "FireworkMissile",
                                                                                                                                                                                                                    Void = "BombDarkMatter", Balloon = "BombBalloon",
                                                                                                                                                                                                                    ["Small Present"] = "PresentSmall", ["Big Present"] = "PresentBig",
                                                                                                                                                                                                                }
                                                                                                                                                                                                                ExplosionType = typeMap[Value] or "BombMissile"
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        ExplodeGroup:CreateSlider({
                                                                                                                                                                                                            Name = "Bomb Amount",
                                                                                                                                                                                                            Flag = "BombAmount",
                                                                                                                                                                                                            Min = 1, Max = 10, Default = 3,
                                                                                                                                                                                                            Callback = function(v) ExplosionAmount = v end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        ExplodeGroup:CreateSlider({
                                                                                                                                                                                                            Name = "Explosion Interval",
                                                                                                                                                                                                            Flag = "ExplosionInterval",
                                                                                                                                                                                                            Min = 0, Max = 5, Default = 0,
                                                                                                                                                                                                            Callback = function(v) ExplosionInterval = v end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        ExplodeGroup:CreateToggle({
                                                                                                                                                                                                            Name = "Predict Movement",
                                                                                                                                                                                                            Flag = "PredictMovement",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(v) PredictMovement = v end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        ExplodeGroup:CreateToggle({
                                                                                                                                                                                                            Name = "Loop Explode",
                                                                                                                                                                                                            Flag = "AutoExplosion",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(Value)
                                                                                                                                                                                                                AutoExplosionEnabled = Value
                                                                                                                                                                                                                if not Value then return end
                                                                                                                                                                                                                if not _expTarget then
                                                                                                                                                                                                                    AutoExplosionEnabled = false
                                                                                                                                                                                                                    Notify("true am am", "Выбери цель!", 3)
                                                                                                                                                                                                                    return
                                                                                                                                                                                                                end
                                                                                                                                                                                                                task.spawn(function()
                                                                                                                                                                                                                    local HitboxNames = {
                                                                                                                                                                                                                        BombMissile = "PartHitDetector", BombDarkMatter = "PartHitDetector",
                                                                                                                                                                                                                        FireworkMissile = "PartHitDetector", BombBalloon = "Balloon",
                                                                                                                                                                                                                        PresentBig = "Box", PresentSmall = "Box",
                                                                                                                                                                                                                    }
                                                                                                                                                                                                                    local SetupParts = {
                                                                                                                                                                                                                        BombMissile = "Body", BombDarkMatter = "Pyramid",
                                                                                                                                                                                                                        FireworkMissile = "Hitbox", BombBalloon = "Balloon",
                                                                                                                                                                                                                        PresentBig = "Box", PresentSmall = "Box",
                                                                                                                                                                                                                    }
                                                                                                                                                                                                                    local BombEvents = RS:FindFirstChild("BombEvents")
                                                                                                                                                                                                                    if not BombEvents then return end
                                                                                                                                                                                                                    local function getBombs()
                                                                                                                                                                                                                        local folder = workspace:FindFirstChild(LP.Name .. "SpawnedInToys")
                                                                                                                                                                                                                        local list = {}
                                                                                                                                                                                                                        if folder then
                                                                                                                                                                                                                            for _, v in pairs(folder:GetChildren()) do
                                                                                                                                                                                                                                if v.Name == ExplosionType then table.insert(list, v) end
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        return list
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    local function clearBombs()
                                                                                                                                                                                                                        for _, bomb in ipairs(getBombs()) do
                                                                                                                                                                                                                            pcall(function() if _G.DestroyToy_Def then _G.DestroyToy_Def:FireServer(bomb) end end)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                    while AutoExplosionEnabled do
                                                                                                                                                                                                                        local target = P:FindFirstChild(_expTarget)
                                                                                                                                                                                                                        if not target or not target.Character then
                                                                                                                                                                                                                            AutoExplosionEnabled = false
                                                                                                                                                                                                                            break
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        local tHRP = target.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        if not tHRP then task.wait(0.2) continue end
                                                                                                                                                                                                                        clearBombs()
                                                                                                                                                                                                                        task.wait(0.1)
                                                                                                                                                                                                                        local myRoot = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        local spawnPos = myRoot and myRoot.Position or Vector3.new(0, 0, 0)
                                                                                                                                                                                                                        for i = 1, ExplosionAmount do
                                                                                                                                                                                                                            if _G.SpawnToy_Def then
                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                    _G.SpawnToy_Def:InvokeServer(ExplosionType, CFrame.new(spawnPos + Vector3.new(0, 5, 0)), Vector3.zero)
                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                            task.wait(0.03)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        task.wait(0.2)
                                                                                                                                                                                                                        local bombs = getBombs()
                                                                                                                                                                                                                        for _, bomb in ipairs(bombs) do
                                                                                                                                                                                                                            local setupPart = bomb:FindFirstChild(SetupParts[bomb.Name])
                                                                                                                                                                                                                            if setupPart and _G.SetNetOwner_Def then
                                                                                                                                                                                                                                pcall(function() _G.SetNetOwner_Def:FireServer(setupPart, setupPart.CFrame) end)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        task.wait(0.1)
                                                                                                                                                                                                                        for _, bomb in ipairs(bombs) do
                                                                                                                                                                                                                            local hitbox = bomb:FindFirstChild(HitboxNames[bomb.Name])
                                                                                                                                                                                                                            if hitbox then
                                                                                                                                                                                                                                local targetPos = tHRP.Position
                                                                                                                                                                                                                                if PredictMovement then
                                                                                                                                                                                                                                    targetPos = targetPos + tHRP.Velocity / 1.93
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                pcall(function()
                                                                                                                                                                                                                                    BombEvents.BombExplode:FireServer({
                                                                                                                                                                                                                                        Hitbox = hitbox,
                                                                                                                                                                                                                                        PositionPart = tHRP,
                                                                                                                                                                                                                                    }, targetPos)
                                                                                                                                                                                                                                end)
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                            task.wait(0.01)
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        task.wait(0.15)
                                                                                                                                                                                                                        clearBombs()
                                                                                                                                                                                                                        task.wait(ExplosionInterval)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })
                                                                                                                                                                                                    end

