                                                                                                                                                                                                        local function UpdateLimb(section, axis, value)
                                                                                                                                                                                                            if FGM.Configuration[section] and FGM.Configuration[section][axis] ~= nil then
                                                                                                                                                                                                                FGM.Configuration[section][axis] = value
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function GetActiveSections()
                                                                                                                                                                                                            return LIMB_SECTION_MAP[SelectedLimb] or LIMB_SECTION_MAP.Torso
                                                                                                                                                                                                        end

