                                                                                                                                                                                                            Callback = function()
                                                                                                                                                                                                                if FGM.State.FigureGrabEnabled then ToggleFigureGrab() end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })
                                                                                                                                                                                                    end

