                                                                                                                                                                                                        -- Auto Claim Plot
                                                                                                                                                                                                        local ClaimPlotEnabled = false
                                                                                                                                                                                                        local SelectedPlot = "Plot1"
                                                                                                                                                                                                        local PlotNames = {[1] = "Plot1", [2] = "Plot2", [3] = "Plot3", [4] = "Plot4", [5] = "Plot5"}

                                                                                                                                                                                                        TpRight:CreateDropdown({
                                                                                                                                                                                                            Name = "Select Plot",
                                                                                                                                                                                                            Flag = "ClaimPlotSelect",
                                                                                                                                                                                                            Items = {"Plot1", "Plot2", "Plot3", "Plot4", "Plot5"},
                                                                                                                                                                                                            Default = "Plot1",
                                                                                                                                                                                                            Callback = function(v) SelectedPlot = v end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        TpRight:CreateToggle({
                                                                                                                                                                                                            Name = "Auto Claim Plot",
                                                                                                                                                                                                            Flag = "ClaimPlotToggle",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(v)
                                                                                                                                                                                                                ClaimPlotEnabled = v
                                                                                                                                                                                                                if not v then return end
                                                                                                                                                                                                                task.spawn(function()
                                                                                                                                                                                                                    while ClaimPlotEnabled do
                                                                                                                                                                                                                        task.wait(0.5)
                                                                                                                                                                                                                        local char = LP.Character
                                                                                                                                                                                                                        local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                        if not hrp then continue end
                                                                                                                                                                                                                        local oldCFrame = hrp.CFrame
                                                                                                                                                                                                                        local oldVel = hrp.AssemblyLinearVelocity
                                                                                                                                                                                                                        for i, plot in ipairs(workspace.Plots:GetChildren()) do
                                                                                                                                                                                                                            if PlotNames[i] == SelectedPlot then
                                                                                                                                                                                                                                local ownersFolder = plot.PlotSign.ThisPlotsOwners
                                                                                                                                                                                                                                if #ownersFolder:GetChildren() <= 0 then
                                                                                                                                                                                                                                    local sign = plot.PlotSign
                                                                                                                                                                                                                                    local plus = sign and sign:FindFirstChild("Sign") and sign.Sign:FindFirstChild("Plus")
                                                                                                                                                                                                                                    local jellyfish = plus and plus:FindFirstChild("PlusGrabPart")
                                                                                                                                                                                                                                    if jellyfish then
                                                                                                                                                                                                                                        while #ownersFolder:GetChildren() <= 0 and ClaimPlotEnabled do
                                                                                                                                                                                                                                            if LP.Character and LP.Character:FindFirstChild("HumanoidRootPart") then
                                                                                                                                                                                                                                                hrp.CFrame = jellyfish.CFrame + Vector3.new(10, 10, 10)
                                                                                                                                                                                                                                                if _G.SetNetOwner_Def then
                                                                                                                                                                                                                                                    _G.SetNetOwner_Def:FireServer(jellyfish, jellyfish.CFrame)
                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                            task.wait(0.1)
                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                break
                                                                                                                                                                                                                            end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                        hrp.CFrame = oldCFrame
                                                                                                                                                                                                                        hrp.AssemblyLinearVelocity = oldVel
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end)
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })
                                                                                                                                                                                                    end

