                                                                                                                                                                                                        local MapL = Tabs.MapBreak:CreateBlock({Name = "Break Objects", Side = "Left", ImageID = "11710306257"})
                                                                                                                                                                                                        local MapR = Tabs.MapBreak:CreateBlock({Name = "Break Plots", Side = "Right", ImageID = "11710306257"})

                                                                                                                                                                                                        local function SpawnPencilAndBreak(targetPart, callback)
                                                                                                                                                                                                            if not targetPart then return end
                                                                                                                                                                                                            task.spawn(function()
                                                                                                                                                                                                                local canSpawn = LP:FindFirstChild("CanSpawnToy")
                                                                                                                                                                                                                if canSpawn then
                                                                                                                                                                                                                    local t = tick()
                                                                                                                                                                                                                    while not canSpawn.Value do
                                                                                                                                                                                                                        if tick() - t > 5 then return end
                                                                                                                                                                                                                        task.wait(0.1)
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end
                                                                                                                                                                                                                local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                if not hrp then return end
                                                                                                                                                                                                                if _G.SpawnToy_Def then
                                                                                                                                                                                                                    pcall(function()
                                                                                                                                                                                                                        _G.SpawnToy_Def:InvokeServer("ToolPencil", hrp.CFrame * CFrame.Angles(-0.605224, -0.321753, 0), Vector3.zero)
                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                end
                                                                                                                                                                                                                task.wait(0.3)
                                                                                                                                                                                                                local folder = workspace:FindFirstChild(LP.Name .. "SpawnedInToys")
                                                                                                                                                                                                                local pencil = folder and folder:FindFirstChild("ToolPencil")
                                                                                                                                                                                                                if not pencil then return end
                                                                                                                                                                                                                local soundPart = pencil:FindFirstChild("SoundPart")
                                                                                                                                                                                                                if soundPart then
                                                                                                                                                                                                                    if _G.SetNetOwner_Def then
                                                                                                                                                                                                                        for _ = 1, 20 do
                                                                                                                                                                                                                            _G.SetNetOwner_Def:FireServer(soundPart, soundPart.CFrame)
                                                                                                                                                                                                                            if soundPart:FindFirstChild("PartOwner") and soundPart.PartOwner.Value == LP.Name then break end
                                                                                                                                                                                                                        end
                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end
                                                                                                                                                                                                                local stickyPart = pencil:FindFirstChild("StickyPart")
                                                                                                                                                                                                                if stickyPart and _G.StickyPartEvent_Def then
                                                                                                                                                                                                                    _G.StickyPartEvent_Def:FireServer(stickyPart, targetPart, CFrame.new(1e45, math.huge, 1e98))
                                                                                                                                                                                                                end
                                                                                                                                                                                                                if callback then callback() end
                                                                                                                                                                                                            end)
                                                                                                                                                                                                        end

                                                                                                                                                                                                        MapL:CreateButton({
                                                                                                                                                                                                            Name = "Break Outer UFO",
                                                                                                                                                                                                            Callback = function()
                                                                                                                                                                                                                local ufoModel = workspace.Map and workspace.Map:FindFirstChild("AlwaysHereTweenedObjects")
                                                                                                                                                                                                                ufoModel = ufoModel and ufoModel:FindFirstChild("OuterUFO")
                                                                                                                                                                                                                local body = ufoModel and ufoModel:FindFirstChild("Object") and ufoModel.Object:FindFirstChild("ObjectModel") and ufoModel.Object.ObjectModel:FindFirstChild("Body")
                                                                                                                                                                                                                if body then
                                                                                                                                                                                                                    SpawnPencilAndBreak(body)
                                                                                                                                                                                                                    Notify("true am am", "Outer UFO breaking...", 3)
                                                                                                                                                                                                                else
                                                                                                                                                                                                                    Notify("true am am", "Outer UFO not found!", 3)
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        MapL:CreateButton({
                                                                                                                                                                                                            Name = "Break Inner UFO",
                                                                                                                                                                                                            Callback = function()
                                                                                                                                                                                                                local ufoModel = workspace.Map and workspace.Map:FindFirstChild("AlwaysHereTweenedObjects")
