                                                                                                                                                                                                            Callback = function()
                                                                                                                                                                                                                local cave = workspace.Map and workspace.Map:FindFirstChild("AlwaysHereTweenedObjects")
                                                                                                                                                                                                                cave = cave and cave:FindFirstChild("CaveCart")
