                                                                                                                                                                                                                    end
                                                                                                                                                                                                                end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        local SelectedPlotBreak = "1"

                                                                                                                                                                                                        MapR:CreateDropdown({
                                                                                                                                                                                                            Name = "Select Plot",
                                                                                                                                                                                                            Flag = "PlotBreakerSelect",
                                                                                                                                                                                                            Items = {"Plot1", "Plot2", "Plot3", "Plot4", "Plot5"},
                                                                                                                                                                                                            Default = "Plot1",
                                                                                                                                                                                                            Callback = function(Value) SelectedPlotBreak = Value:match("Plot(%d)") or "1" end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        MapR:CreateButton({
