                                                                                                                                                                                                        -- Animations
                                                                                                                                                                                                        local Animations = {
                                                                                                                                                                                                            ["Crazy"]    = "rbxassetid://248263260",
                                                                                                                                                                                                            ["Insane"]   = "rbxassetid://35654637",
                                                                                                                                                                                                            ["Collapse"] = "rbxassetid://35154961",
                                                                                                                                                                                                            ["Zombie"]   = "rbxassetid://33796059",
                                                                                                                                                                                                        }
                                                                                                                                                                                                        local animEnabled = false
                                                                                                                                                                                                        local currentTrack = nil
                                                                                                                                                                                                        local selectedAnimName = "Crazy"

                                                                                                                                                                                                        local function playAnimation()
                                                                                                                                                                                                            local char = LP.Character or LP.CharacterAdded:Wait()
                                                                                                                                                                                                            local hum = char:FindFirstChildOfClass("Humanoid")
                                                                                                                                                                                                            if not hum then return end
                                                                                                                                                                                                            local animator = hum:FindFirstChildOfClass("Animator")
                                                                                                                                                                                                            if not animator then
                                                                                                                                                                                                                animator = Instance.new("Animator")
                                                                                                                                                                                                                animator.Parent = hum
                                                                                                                                                                                                            end
                                                                                                                                                                                                            if currentTrack then currentTrack:Stop() currentTrack = nil end
                                                                                                                                                                                                            local anim = Instance.new("Animation")
                                                                                                                                                                                                            anim.AnimationId = Animations[selectedAnimName]
                                                                                                                                                                                                            currentTrack = animator:LoadAnimation(anim)
                                                                                                                                                                                                            currentTrack.Priority = Enum.AnimationPriority.Action
                                                                                                                                                                                                            currentTrack.Looped = true
                                                                                                                                                                                                            currentTrack:Play()
                                                                                                                                                                                                        end

                                                                                                                                                                                                        local function stopAnimation()
                                                                                                                                                                                                            if currentTrack then
                                                                                                                                                                                                                currentTrack:Stop()
                                                                                                                                                                                                                currentTrack = nil
                                                                                                                                                                                                            end
                                                                                                                                                                                                        end

                                                                                                                                                                                                        FunR:CreateToggle({
                                                                                                                                                                                                            Name = "Play Animation",
                                                                                                                                                                                                            Flag = "AnimToggle",
                                                                                                                                                                                                            Default = false,
                                                                                                                                                                                                            Callback = function(on)
                                                                                                                                                                                                                animEnabled = on
                                                                                                                                                                                                                if on then playAnimation() else stopAnimation() end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })

                                                                                                                                                                                                        FunR:CreateDropdown({
                                                                                                                                                                                                            Name = "Animation",
                                                                                                                                                                                                            Flag = "AnimSelect",
                                                                                                                                                                                                            Items = {"Crazy", "Insane", "Collapse", "Zombie"},
                                                                                                                                                                                                            Default = "Crazy",
                                                                                                                                                                                                            Callback = function(v)
                                                                                                                                                                                                                selectedAnimName = v
                                                                                                                                                                                                                if animEnabled then playAnimation() end
                                                                                                                                                                                                            end
                                                                                                                                                                                                        })
                                                                                                                                                                                                    end

